"use client";

import {
  type HTMLMotionProps,
  motion,
  useMotionTemplate,
  useMotionValue,
  useSpring,
  useTransform,
} from "framer-motion";
import type { PointerEvent, ReactNode } from "react";
import { useCallback } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const magneticCardVariants = tv({
  base: [
    "group relative overflow-hidden rounded-2xl border border-border bg-card text-card-foreground",
    "shadow-sm outline-none [transform-style:preserve-3d]",
    "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
  ],
  variants: {
    size: {
      sm: "max-w-[280px] p-5",
      md: "max-w-[340px] p-6",
      lg: "max-w-[420px] p-7",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type MagneticCardProps = Omit<HTMLMotionProps<"div">, "children"> &
  VariantProps<typeof magneticCardVariants> & {
    children?: ReactNode;
    intensity?: number;
    tilt?: number;
    stiffness?: number;
    damping?: number;
  };

export function MagneticCard({
  className,
  size,
  intensity = 12,
  tilt = 8,
  stiffness = 220,
  damping = 18,
  children,
  ...props
}: MagneticCardProps) {
  const config = { stiffness, damping, mass: 0.6 };

  const pointerX = useMotionValue(0.5);
  const pointerY = useMotionValue(0.5);

  const offsetX = useSpring(useMotionValue(0), config);
  const offsetY = useSpring(useMotionValue(0), config);
  const rotateX = useSpring(useMotionValue(0), config);
  const rotateY = useSpring(useMotionValue(0), config);

  const glowX = useTransform(pointerX, (value) => `${value * 100}%`);
  const glowY = useTransform(pointerY, (value) => `${value * 100}%`);
  const glowBackground = useMotionTemplate`radial-gradient(220px circle at ${glowX} ${glowY}, color-mix(in oklab, var(--ring) 22%, transparent), transparent 70%)`;

  const handlePointerMove = useCallback(
    (event: PointerEvent<HTMLDivElement>) => {
      const rect = event.currentTarget.getBoundingClientRect();
      const relX = (event.clientX - rect.left) / rect.width;
      const relY = (event.clientY - rect.top) / rect.height;

      pointerX.set(relX);
      pointerY.set(relY);
      offsetX.set((relX - 0.5) * intensity * 2);
      offsetY.set((relY - 0.5) * intensity * 2);
      rotateY.set((relX - 0.5) * tilt * 2);
      rotateX.set((0.5 - relY) * tilt * 2);
    },
    [intensity, offsetX, offsetY, pointerX, pointerY, rotateX, rotateY, tilt],
  );

  const handlePointerLeave = useCallback(() => {
    pointerX.set(0.5);
    pointerY.set(0.5);
    offsetX.set(0);
    offsetY.set(0);
    rotateX.set(0);
    rotateY.set(0);
  }, [offsetX, offsetY, pointerX, pointerY, rotateX, rotateY]);

  return (
    <motion.div
      data-slot="magnetic-card"
      className={twMerge(magneticCardVariants({ size }), className)}
      onPointerMove={handlePointerMove}
      onPointerLeave={handlePointerLeave}
      style={{ x: offsetX, y: offsetY, rotateX, rotateY, perspective: 900 }}
      {...props}
    >
      <motion.div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 opacity-0 transition-opacity duration-300 group-hover:opacity-100"
        style={{ background: glowBackground }}
      />
      <div className="relative transform-[translateZ(40px)]">{children}</div>
    </motion.div>
  );
}

"use client";

import { motion, useMotionValue, useSpring, useTransform } from "framer-motion";
import type { ComponentProps } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const springSliderVariants = tv({
  base: ["group relative w-full touch-none select-none"],
  variants: {
    size: {
      sm: "max-w-[220px]",
      md: "max-w-[320px]",
      lg: "max-w-[420px]",
      full: "max-w-full",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

export type SpringSliderProps = Omit<
  ComponentProps<"div">,
  "onChange" | "defaultValue"
> &
  VariantProps<typeof springSliderVariants> & {
    min?: number;
    max?: number;
    step?: number;
    defaultValue?: number;
    value?: number;
    onValueChange?: (value: number) => void;
    stiffness?: number;
    damping?: number;
  };

export function SpringSlider({
  className,
  size,
  min = 0,
  max = 100,
  step = 1,
  defaultValue = 50,
  value,
  onValueChange,
  stiffness = 380,
  damping = 24,
  ...props
}: SpringSliderProps) {
  const trackRef = useRef<HTMLDivElement>(null);
  const [internalValue, setInternalValue] = useState(defaultValue);
  const [dragging, setDragging] = useState(false);
  const current = value ?? internalValue;

  const progress = useMotionValue((current - min) / (max - min));
  const springProgress = useSpring(progress, { stiffness, damping, mass: 0.7 });

  const fillWidth = useTransform(
    springProgress,
    (p) => `${clamp(p, 0, 1) * 100}%`,
  );
  const thumbLeft = useTransform(
    springProgress,
    (p) => `${clamp(p, 0, 1) * 100}%`,
  );
  const thumbScale = useTransform(springProgress, () => (dragging ? 1.15 : 1));

  useEffect(() => {
    progress.set((current - min) / (max - min));
  }, [current, min, max, progress]);

  const commit = useCallback(
    (next: number) => {
      const snapped = clamp(Math.round(next / step) * step, min, max);
      if (value === undefined) {
        setInternalValue(snapped);
      }
      onValueChange?.(snapped);
    },
    [max, min, onValueChange, step, value],
  );

  const setFromClientX = useCallback(
    (clientX: number) => {
      const track = trackRef.current;
      if (!track) return;
      const rect = track.getBoundingClientRect();
      const ratio = clamp((clientX - rect.left) / rect.width, 0, 1);
      commit(min + ratio * (max - min));
    },
    [commit, max, min],
  );

  const handlePointerDown = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      event.currentTarget.setPointerCapture(event.pointerId);
      setDragging(true);
      setFromClientX(event.clientX);
    },
    [setFromClientX],
  );

  const handlePointerMove = useCallback(
    (event: React.PointerEvent<HTMLDivElement>) => {
      if (!dragging) return;
      setFromClientX(event.clientX);
    },
    [dragging, setFromClientX],
  );

  const stopDragging = useCallback(() => setDragging(false), []);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowRight" || event.key === "ArrowUp") {
        event.preventDefault();
        commit(current + step);
      } else if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
        event.preventDefault();
        commit(current - step);
      }
    },
    [commit, current, step],
  );

  return (
    <div
      data-slot="spring-slider"
      className={twMerge(springSliderVariants({ size }), className)}
      {...props}
    >
      <div
        ref={trackRef}
        role="slider"
        tabIndex={0}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={current}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={stopDragging}
        onPointerCancel={stopDragging}
        onKeyDown={handleKeyDown}
        className="relative flex h-6 cursor-pointer items-center outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background rounded-full"
      >
        <div className="relative h-2 w-full overflow-hidden rounded-full bg-muted">
          <motion.div
            className="absolute inset-y-0 left-0 rounded-full bg-primary"
            style={{ width: fillWidth }}
          />
        </div>
        <motion.div
          className="absolute top-1/2 size-5 -translate-x-1/2 -translate-y-1/2 rounded-full border border-border bg-background shadow-md"
          style={{ left: thumbLeft, scale: thumbScale }}
        >
          <span className="absolute inset-1.5 rounded-full bg-primary" />
        </motion.div>
      </div>
    </div>
  );
}

"use client";

import { motion } from "framer-motion";
import type { ComponentProps } from "react";
import { useCallback, useState } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const bouncyToggleVariants = tv({
  base: [
    "relative inline-flex shrink-0 cursor-pointer items-center rounded-full p-1 outline-none transition-colors",
    "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
    "disabled:cursor-not-allowed disabled:opacity-50",
  ],
  variants: {
    size: {
      sm: "h-6 w-11",
      md: "h-7 w-[52px]",
      lg: "h-8 w-[60px]",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

const knobSize: Record<string, string> = {
  sm: "size-4",
  md: "size-5",
  lg: "size-6",
};

export type BouncyToggleProps = Omit<
  ComponentProps<"button">,
  "onChange" | "value"
> &
  VariantProps<typeof bouncyToggleVariants> & {
    checked?: boolean;
    defaultChecked?: boolean;
    onCheckedChange?: (checked: boolean) => void;
    stiffness?: number;
    damping?: number;
  };

export function BouncyToggle({
  className,
  size = "md",
  checked,
  defaultChecked = false,
  onCheckedChange,
  disabled,
  stiffness = 500,
  damping = 15,
  ...props
}: BouncyToggleProps) {
  const [internal, setInternal] = useState(defaultChecked);
  const isOn = checked ?? internal;

  const toggle = useCallback(() => {
    const next = !isOn;
    if (checked === undefined) {
      setInternal(next);
    }
    onCheckedChange?.(next);
  }, [checked, isOn, onCheckedChange]);

  return (
    <button
      type="button"
      role="switch"
      aria-checked={isOn}
      disabled={disabled}
      onClick={toggle}
      data-slot="bouncy-toggle"
      data-state={isOn ? "checked" : "unchecked"}
      className={twMerge(
        bouncyToggleVariants({ size }),
        isOn ? "bg-primary" : "bg-muted",
        className,
      )}
      {...props}
    >
      <motion.span
        layout
        transition={{ type: "spring", stiffness, damping, mass: 0.6 }}
        className={twMerge(
          "rounded-full bg-background shadow-sm",
          knobSize[size ?? "md"],
        )}
        style={{ marginLeft: isOn ? "auto" : 0 }}
        whileTap={{ scaleX: 1.25 }}
      />
    </button>
  );
}

"use client";

import { motion, useSpring, useTransform } from "framer-motion";
import type { ComponentProps } from "react";
import { useEffect } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const physicsCounterVariants = tv({
  base: [
    "inline-flex items-baseline font-semibold tabular-nums tracking-tight",
  ],
  variants: {
    size: {
      sm: "text-2xl",
      md: "text-4xl",
      lg: "text-6xl",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type PhysicsCounterProps = ComponentProps<"span"> &
  VariantProps<typeof physicsCounterVariants> & {
    value: number;
    decimals?: number;
    prefix?: string;
    suffix?: string;
    stiffness?: number;
    damping?: number;
  };

export function PhysicsCounter({
  className,
  size,
  value,
  decimals = 0,
  prefix,
  suffix,
  stiffness = 90,
  damping = 18,
  ...props
}: PhysicsCounterProps) {
  const spring = useSpring(value, { stiffness, damping, mass: 1 });
  const display = useTransform(spring, (latest) =>
    latest.toLocaleString(undefined, {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    }),
  );

  useEffect(() => {
    spring.set(value);
  }, [spring, value]);

  return (
    <span
      data-slot="physics-counter"
      className={twMerge(physicsCounterVariants({ size }), className)}
      {...props}
    >
      {prefix ? <span className="text-muted-foreground">{prefix}</span> : null}
      <motion.span>{display}</motion.span>
      {suffix ? (
        <span className="ml-1 text-[0.5em] font-medium text-muted-foreground">
          {suffix}
        </span>
      ) : null}
    </span>
  );
}

"use client";

import {
  AnimatePresence,
  animate,
  type MotionValue,
  motion,
  useMotionValue,
  useReducedMotion,
  useTransform,
} from "framer-motion";
import { Check } from "lucide-react";
import {
  type ComponentProps,
  type ReactNode,
  useEffect,
  useId,
  useRef,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

import { spring } from "@/lib/motion-tokens";

export const progressRingVariants = tv({
  base: ["relative inline-grid shrink-0 place-items-center text-primary"],
  variants: {
    size: {
      sm: "size-16 text-[0.8rem]",
      md: "size-24 text-base",
      lg: "size-32 text-xl",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

// Track thickness scales with the ring so the stroke reads the same weight at
// every size. Overridable via `thickness`.
const DEFAULT_THICKNESS = { sm: 6, md: 8, lg: 10 } as const;
// The geometry is authored on a fixed 100-unit viewBox and scaled by CSS, so
// one path math covers every size.
const VIEWBOX = 100;

// The tiers `motionForOffset` can't reach are still fine to pick by hand here:
// a ring filling is a value settling, not a surface lifting.
type RingTier = "fast" | "moderate" | "slow" | "playful";

export type ProgressRingProps = Omit<ComponentProps<"div">, "children"> &
  VariantProps<typeof progressRingVariants> & {
    /** 0–100. Values outside the range are clamped. */
    value: number;
    /** Stroke width in viewBox units (the ring is a 100-unit square). */
    thickness?: number;
    /** Spring character for the fill + count-up. Defaults to `moderate`. */
    tier?: RingTier;
    /** Primary → chart-2 gradient stroke. `true` by default. */
    gradient?: boolean;
    /** Render the animated percentage in the centre. `true` by default. */
    showValue?: boolean;
    /** Swap the centre for a check once the value reaches 100. `true` by default. */
    checkOnComplete?: boolean;
    /** Replaces the centre entirely — you own what's shown. */
    children?: ReactNode;
    /** Accessible name for the progressbar. */
    "aria-label"?: string;
  };

const clamp = (n: number) => Math.max(0, Math.min(100, n));

export function ProgressRing({
  className,
  size = "md",
  value,
  thickness,
  tier = "moderate",
  gradient = true,
  showValue = true,
  checkOnComplete = true,
  children,
  "aria-label": ariaLabel,
  ...props
}: ProgressRingProps) {
  const shouldReduceMotion = useReducedMotion();
  const gradientId = useId();

  const target = clamp(value);
  const stroke = thickness ?? DEFAULT_THICKNESS[size ?? "md"];
  const radius = (VIEWBOX - stroke) / 2;
  const circumference = 2 * Math.PI * radius;

  // One motion value drives everything — the arc and the number can never drift
  // out of sync because they read the same source.
  const progress = useMotionValue(0);
  const dashoffset = useTransform(
    progress,
    (p) => circumference * (1 - clamp(p) / 100),
  );

  useEffect(() => {
    if (shouldReduceMotion) {
      progress.set(target);
      return;
    }
    const controls = animate(progress, target, {
      type: "spring",
      visualDuration: spring[tier].visualDuration,
      bounce: spring[tier].bounce,
    });
    return () => controls.stop();
  }, [target, tier, shouldReduceMotion, progress]);

  const complete = target >= 100;
  const showCheck = checkOnComplete && complete && !children;

  return (
    <div
      data-slot="progress-ring"
      data-complete={complete || undefined}
      role="progressbar"
      aria-valuenow={Math.round(target)}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-label={ariaLabel ?? "Progress"}
      className={twMerge(progressRingVariants({ size }), className)}
      {...props}
    >
      <RingPulse active={complete} reduced={!!shouldReduceMotion}>
        <svg
          viewBox={`0 0 ${VIEWBOX} ${VIEWBOX}`}
          className="size-full -rotate-90"
          aria-hidden="true"
        >
          {gradient ? (
            <defs>
              <linearGradient
                id={gradientId}
                x1="0%"
                y1="0%"
                x2="100%"
                y2="100%"
              >
                <stop offset="0%" stopColor="var(--color-primary)" />
                <stop offset="100%" stopColor="var(--color-chart-2)" />
              </linearGradient>
            </defs>
          ) : null}
          <circle
            cx={VIEWBOX / 2}
            cy={VIEWBOX / 2}
            r={radius}
            fill="none"
            strokeWidth={stroke}
            className="stroke-current opacity-15"
          />
          <motion.circle
            cx={VIEWBOX / 2}
            cy={VIEWBOX / 2}
            r={radius}
            fill="none"
            strokeWidth={stroke}
            strokeLinecap="round"
            stroke={gradient ? `url(#${gradientId})` : "var(--color-primary)"}
            strokeDasharray={circumference}
            style={{ strokeDashoffset: dashoffset as MotionValue<number> }}
          />
        </svg>
      </RingPulse>

      <div className="absolute inset-0 grid place-items-center">
        {children ? (
          children
        ) : (
          <AnimatePresence mode="popLayout" initial={false}>
            {showCheck ? (
              <motion.span
                key="check"
                initial={
                  shouldReduceMotion ? false : { scale: 0.3, opacity: 0 }
                }
                animate={{ scale: 1, opacity: 1 }}
                exit={
                  shouldReduceMotion
                    ? { opacity: 0 }
                    : { scale: 0.3, opacity: 0 }
                }
                transition={{
                  type: "spring",
                  visualDuration: spring.playful.visualDuration,
                  bounce: spring.playful.bounce,
                }}
                className="text-primary"
              >
                <Check
                  className="size-[1.6em]"
                  strokeWidth={2.75}
                  aria-hidden="true"
                />
              </motion.span>
            ) : showValue ? (
              <motion.span
                key="value"
                initial={shouldReduceMotion ? false : { opacity: 0, y: 4 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -4 }}
                transition={{
                  type: "spring",
                  visualDuration: spring.fast.visualDuration,
                  bounce: spring.fast.bounce,
                }}
                className="font-semibold text-foreground tabular-nums tracking-tight"
              >
                <RingValue progress={progress} />
                <span className="ml-[0.1em] align-top text-[0.55em] font-medium text-muted-foreground">
                  %
                </span>
              </motion.span>
            ) : null}
          </AnimatePresence>
        )}
      </div>
    </div>
  );
}

/** Reads the shared motion value straight into text — no state, so the number
 *  updates on the same frame as the arc it belongs to. */
function RingValue({ progress }: { progress: MotionValue<number> }) {
  const text = useTransform(progress, (p) => String(Math.round(clamp(p))));
  return <motion.span>{text}</motion.span>;
}

/** A single soft scale pop the moment the ring completes — the celebration is
 *  one beat, not a loop. Silent under reduced motion. */
function RingPulse({
  active,
  reduced,
  children,
}: {
  active: boolean;
  reduced: boolean;
  children: ReactNode;
}) {
  const wasActive = useRef(active);
  const justCompleted = active && !wasActive.current;
  wasActive.current = active;

  return (
    <motion.div
      className="size-full"
      animate={
        justCompleted && !reduced ? { scale: [1, 1.045, 1] } : { scale: 1 }
      }
      transition={{
        duration: 0.5,
        ease: [0.22, 1, 0.36, 1],
      }}
    >
      {children}
    </motion.div>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type ComponentProps, useState } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

import { spring, stagger } from "@/lib/motion-tokens";

export const avatarGroupVariants = tv({
  base: [
    "group/avatars not-prose relative isolate flex w-fit list-none items-center",
  ],
  variants: {
    size: {
      sm: "text-[0.62rem]",
      md: "text-[0.72rem]",
      lg: "text-[0.82rem]",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

// diameter / overlap pull / open-state spread, all in px so Framer interpolates
// the x offset cleanly (a `calc()` string would not tween).
const SIZES = {
  sm: { d: 28, gap: 10, spread: 15 },
  md: { d: 36, gap: 13, spread: 21 },
  lg: { d: 44, gap: 16, spread: 26 },
} as const;

export type AvatarGroupItem = {
  /** Image URL. Falls back to initials when absent or on load error. */
  src?: string;
  /** Full name — used for the alt text, the title, and the hover label. */
  name: string;
  /** Explicit initials. Derived from `name` when omitted. */
  fallback?: string;
};

export type AvatarGroupProps = Omit<
  ComponentProps<"ul">,
  "children" | "onAnimationStart" | "onDrag" | "onDragEnd" | "onDragStart"
> &
  VariantProps<typeof avatarGroupVariants> & {
    items: AvatarGroupItem[];
    /** Show at most this many avatars; the rest collapse into a +N chip. */
    max?: number;
    /** Fan the stack apart on hover / focus. `true` by default. */
    spreadOnHover?: boolean;
    /** Float each name above its avatar while the stack is open. `true` by default. */
    showLabels?: boolean;
    "aria-label"?: string;
  };

function initialsOf(name: string) {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}

export function AvatarGroup({
  className,
  size = "md",
  items,
  max,
  spreadOnHover = true,
  showLabels = true,
  "aria-label": ariaLabel,
  ...props
}: AvatarGroupProps) {
  const shouldReduceMotion = useReducedMotion();
  const [open, setOpen] = useState(false);
  const [hovered, setHovered] = useState<number | null>(null);

  const dims = SIZES[size ?? "md"];
  const visible = typeof max === "number" ? items.slice(0, max) : items;
  const overflow = items.length - visible.length;

  // The spread is the whole interaction — with it suppressed there is nothing
  // to open, so the handlers just no-op.
  const canSpread = spreadOnHover && !shouldReduceMotion;
  const spread = canSpread && open;

  const cells: Array<
    | { kind: "avatar"; item: AvatarGroupItem; index: number }
    | { kind: "overflow"; index: number }
  > = [
    ...visible.map((item, index) => ({ kind: "avatar" as const, item, index })),
    ...(overflow > 0
      ? [{ kind: "overflow" as const, index: visible.length }]
      : []),
  ];

  const closeAll = () => {
    setOpen(false);
    setHovered(null);
  };

  return (
    <ul
      aria-label={ariaLabel ?? "People"}
      data-slot="avatar-group"
      data-open={spread || undefined}
      className={twMerge(avatarGroupVariants({ size }), className)}
      onPointerEnter={() => canSpread && setOpen(true)}
      onPointerLeave={closeAll}
      onFocusCapture={() => canSpread && setOpen(true)}
      onBlurCapture={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) closeAll();
      }}
      {...props}
    >
      {cells.map((cell) => {
        const isHovered = hovered === cell.index;
        const clearHover = () =>
          setHovered((current) => (current === cell.index ? null : current));
        return (
          <motion.li
            key={cell.kind === "avatar" ? cell.item.name : "overflow"}
            className="relative shrink-0"
            style={{
              width: dims.d,
              height: dims.d,
              // Overlap: every cell after the first pulls left onto its
              // neighbour. Opening cancels it out via the x offset.
              marginLeft: cell.index === 0 ? 0 : -dims.gap,
              zIndex: isHovered ? 50 : 40 - cell.index,
            }}
            initial={false}
            animate={{
              x: spread ? cell.index * dims.spread : 0,
              y: isHovered && spread ? -4 : 0,
              scale: isHovered && spread ? 1.06 : 1,
            }}
            transition={{
              x: {
                type: "spring",
                visualDuration: spring.moderate.visualDuration,
                bounce: spring.moderate.bounce,
                // Staggered so the fan unrolls left-to-right instead of snapping.
                delay: spread ? cell.index * stagger.fast : 0,
              },
              y: spring.fast,
              scale: spring.fast,
            }}
            onPointerEnter={() => setHovered(cell.index)}
            onPointerLeave={clearHover}
          >
            {cell.kind === "avatar" ? (
              <Avatar
                item={cell.item}
                onFocus={() => setHovered(cell.index)}
                onBlur={clearHover}
              />
            ) : (
              <span
                className="grid size-full select-none place-items-center rounded-full bg-muted font-semibold text-muted-foreground ring-2 ring-background"
                title={`${overflow} more`}
              >
                +{overflow}
              </span>
            )}

            <AnimatePresence>
              {showLabels && spread && isHovered && cell.kind === "avatar" ? (
                <motion.span
                  key="label"
                  initial={{ opacity: 0, y: 4, scale: 0.9 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, y: 4, scale: 0.9 }}
                  transition={spring.fast}
                  className="-translate-x-1/2 pointer-events-none absolute bottom-[calc(100%+0.4rem)] left-1/2 z-50 whitespace-nowrap rounded-md bg-foreground px-1.5 py-0.5 font-medium text-[0.7rem] text-background shadow-sm"
                >
                  {cell.item.name}
                </motion.span>
              ) : null}
            </AnimatePresence>
          </motion.li>
        );
      })}
    </ul>
  );
}

function Avatar({
  item,
  onFocus,
  onBlur,
}: {
  item: AvatarGroupItem;
  onFocus: () => void;
  onBlur: () => void;
}) {
  const [broken, setBroken] = useState(false);
  const initials = item.fallback ?? initialsOf(item.name);

  return (
    <button
      type="button"
      title={item.name}
      aria-label={item.name}
      onFocus={onFocus}
      onBlur={onBlur}
      className="block size-full overflow-hidden rounded-full outline-none ring-2 ring-background focus-visible:ring-2 focus-visible:ring-ring"
    >
      {item.src && !broken ? (
        // biome-ignore lint/performance/noImgElement: registry components must work outside Next.js.
        <img
          src={item.src}
          alt={item.name}
          loading="lazy"
          onError={() => setBroken(true)}
          className="size-full object-cover"
        />
      ) : (
        <span className="grid size-full select-none place-items-center bg-secondary font-semibold text-secondary-foreground">
          {initials}
        </span>
      )}
    </button>
  );
}

