function ReactiveButton({
  variant = "default",
  size = "md",
  status = "idle",
  loadingText = "Loading...",
  successText = "Done",
  errorText = "Try again",
  countdown,
  icon,
  loadingIcon,
  successIcon,
  errorIcon,
  autoReset = false,
  resetDelay = 1800,
  onStatusReset,
  className,
  children,
  disabled,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  "aria-busy": ariaBusy,
  ...props
}: ReactiveButtonProps) {
  const shouldReduceMotion = useReducedMotion();
  const [autoResetStatus, setAutoResetStatus] =
    useState<ReactiveButtonStatus | null>(null);
  const onStatusResetRef = useRef(onStatusReset);
  const visibleStatus = autoResetStatus === status ? "idle" : status;
  const isLoading = visibleStatus === "loading";
  const isIconButton = size === "icon";
  const displayCountdown =
    typeof countdown === "number" && Number.isFinite(countdown)
      ? Math.max(0, Math.floor(countdown))
      : null;
  const hasCountdown = displayCountdown !== null;
  const resolvedAriaLabel =
    ariaLabel ??
    (isIconButton
      ? typeof children === "string"
        ? children
        : "Button action"
      : undefined);

  useEffect(() => {
    if (autoResetStatus && autoResetStatus !== status) {
      setAutoResetStatus(null);
    }
  }, [autoResetStatus, status]);

  useEffect(() => {
    onStatusResetRef.current = onStatusReset;
  }, [onStatusReset]);

  useEffect(() => {
    if (!autoReset || (status !== "success" && status !== "error")) {
      return;
    }

    const resetTimer = window.setTimeout(() => {
      setAutoResetStatus(status);
      onStatusResetRef.current?.();
    }, resetDelay);

    return () => window.clearTimeout(resetTimer);
  }, [autoReset, resetDelay, status]);

  const stateContent: Record<
    ReactiveButtonStatus,
    { icon?: ReactNode; label: ReactNode }
  > = {
    idle: { icon, label: children },
    loading: {
      icon: loadingIcon ?? (
        <LoadingIndicator shouldReduceMotion={Boolean(shouldReduceMotion)} />
      ),
      label: loadingText,
    },
    success: {
      icon: successIcon ?? (
        <AnimatedSuccessIcon shouldReduceMotion={Boolean(shouldReduceMotion)} />
      ),
      label: successText,
    },
    error: {
      icon: errorIcon ?? (
        <AnimatedErrorIcon shouldReduceMotion={Boolean(shouldReduceMotion)} />
      ),
      label: errorText,
    },
  };
  const activeContent = stateContent[visibleStatus];
  const contentKey = `${visibleStatus}-${hasCountdown ? "countdown" : "default"}`;
  const transition = shouldReduceMotion
    ? { duration: 0 }
    : { duration: reactiveTiming.quick, ease: reactiveEase };

  return (
    <button
      type="button"
      data-slot="reactive-button"
      data-status={visibleStatus}
      aria-busy={ariaBusy ?? isLoading}
      aria-label={resolvedAriaLabel}
      aria-labelledby={ariaLabelledby}
      disabled={disabled || isLoading}
      className={twMerge(
        reactiveButtonVariants({ variant, size }),
        statusStyles[visibleStatus],
        hasCountdown && "rounded-full",
        className,
      )}
      {...props}
    >
      <AnimatePresence>
        {hasCountdown ? (
          <ReactiveButtonCountdownSurface
            shouldReduceMotion={Boolean(shouldReduceMotion)}
          />
        ) : null}
      </AnimatePresence>
      <ReactiveButtonSurface
        status={visibleStatus}
        shouldReduceMotion={Boolean(shouldReduceMotion)}
      />
      <span
        data-slot="reactive-button-content"
        className="relative z-10 grid items-center justify-items-center"
        aria-live={visibleStatus !== "idle" ? "polite" : undefined}
        aria-atomic="true"
      >
        {Object.entries(stateContent).map(([state, content]) => (
          <span
            key={`reactive-button-measure-${state}`}
            className="invisible col-start-1 row-start-1 inline-flex items-center gap-1.5"
            aria-hidden="true"
          >
            {content.icon ? <span className="size-4 shrink-0" /> : null}
            {!isIconButton ? content.label : null}
          </span>
        ))}

        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            key={contentKey}
            data-slot="reactive-button-state"
            className="col-start-1 row-start-1 inline-flex items-center gap-1.5"
            initial={shouldReduceMotion ? false : { opacity: 0, y: 2 }}
            animate={{ opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? undefined : { opacity: 0, y: -2 }}
            transition={transition}
          >
            {activeContent.icon ? (
              <motion.span
                className="inline-flex shrink-0 items-center justify-center"
                initial={
                  shouldReduceMotion || visibleStatus !== "success"
                    ? false
                    : { scale: 0.82 }
                }
                animate={{ scale: 1 }}
                transition={transition}
                aria-hidden="true"
              >
                {activeContent.icon}
              </motion.span>
            ) : null}
            {isIconButton ? (
              <span className="sr-only">{activeContent.label}</span>
            ) : (
              activeContent.label
            )}
          </motion.span>
        </AnimatePresence>
      </span>

      <AnimatePresence initial={false}>
        {hasCountdown ? (
          <motion.span
            aria-hidden="true"
            className="relative -mr-0.5 ml-1 inline-flex size-5 shrink-0 items-center justify-center rounded-full border border-destructive/30 bg-destructive/15 font-semibold text-[0.625rem] text-destructive tabular-nums"
            initial={
              shouldReduceMotion
                ? false
                : { marginLeft: 0, opacity: 0, scale: 0.45, width: 0 }
            }
            animate={{ marginLeft: 4, opacity: 1, scale: 1, width: 20 }}
            exit={
              shouldReduceMotion
                ? { opacity: 0 }
                : { marginLeft: 0, opacity: 0, scale: 0.45, width: 0 }
            }
            transition={{
              duration: shouldReduceMotion ? 0.12 : reactiveTiming.settle,
              ease: countdownEase,
            }}
          >
            <AnimatePresence initial={false}>
              <motion.span
                key={`reactive-button-countdown-pulse-${displayCountdown}`}
                className="pointer-events-none absolute inset-0 rounded-full bg-destructive/25"
                initial={
                  shouldReduceMotion ? false : { opacity: 0.5, scale: 0.8 }
                }
                animate={{ opacity: 0, scale: shouldReduceMotion ? 1 : 1.45 }}
                transition={{
                  duration: shouldReduceMotion ? 0 : 0.42,
                  ease: "easeOut",
                }}
              />
            </AnimatePresence>
            <AnimatePresence initial={false} mode="popLayout">
              <motion.span
                key={displayCountdown}
                className="relative"
                initial={shouldReduceMotion ? false : { opacity: 0, y: -8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={
                  shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 }
                }
                transition={{
                  duration: shouldReduceMotion ? 0.1 : reactiveTiming.draw,
                }}
              >
                {displayCountdown}
              </motion.span>
            </AnimatePresence>
          </motion.span>
        ) : null}
      </AnimatePresence>

      {hasCountdown ? (
        <span className="sr-only" aria-live="polite">
          {displayCountdown} seconds remaining
        </span>
      ) : null}
    </button>
  );
}

export { ReactiveButton };

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Monitor, Moon, Sun } from "lucide-react";
import { useTheme } from "next-themes";
import {
  type ComponentProps,
  type MouseEvent,
  type ReactNode,
  useCallback,
  useMemo,
  useRef,
} from "react";
import { flushSync } from "react-dom";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

export const themeTogglerButtonVariants = tv({
  base: [
    "relative inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full border border-transparent text-foreground outline-none select-none",
    "transition-[background-color,border-color,box-shadow,transform] duration-moderate ease-spring",
    "hover:bg-muted/70 active:scale-90 motion-reduce:active:scale-100",
    "focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50",
    "disabled:pointer-events-none disabled:opacity-50",
  ],
  variants: {
    size: {
      sm: "size-7 [&_svg]:size-3.5",
      md: "size-8 [&_svg]:size-4",
      lg: "size-10 [&_svg]:size-[1.125rem]",
      icon: "size-9 [&_svg]:size-4",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

/**
 * Reveal animation played on the incoming theme when the View Transitions API
 * is available. "fade" is also used as the safe fallback shape.
 */
export type ThemeTogglerButtonVariant =
  | "circle"
  | "circle-blur"
  | "iris"
  | "polygon"
  | "slide"
  | "fade";

/** Origin edge/rotation used by the reveal sweep and the icon swap. */
export type ThemeTogglerButtonDirection = "ltr" | "rtl" | "ttb" | "btt";

export type ThemeTogglerButtonMode = "light" | "dark" | "system";

type ViewTransitionLike = {
  ready: Promise<void>;
  finished: Promise<void>;
};

type DocumentWithViewTransitions = Document & {
  startViewTransition?: (callback: () => void) => ViewTransitionLike;
};

function getMaxRadius(x: number, y: number) {
  const width = window.innerWidth;
  const height = window.innerHeight;

  return Math.hypot(Math.max(x, width - x), Math.max(y, height - y));
}

function circleClipPath(x: number, y: number, radius: number) {
  return `circle(${radius}px at ${x}px ${y}px)`;
}

/** Straight curtain wipe: the far inset shrinks from 100% to 0% along `direction`. */
function insetClipPath(
  direction: ThemeTogglerButtonDirection,
  progress: number,
) {
  const hidden = `${100 - progress * 100}%`;

  switch (direction) {
    case "ltr":
      return `inset(0 ${hidden} 0 0)`;
    case "rtl":
      return `inset(0 0 0 ${hidden})`;
    case "ttb":
      return `inset(0 0 ${hidden} 0)`;
    case "btt":
      return `inset(${hidden} 0 0 0)`;
  }
}

/**
 * Diagonal wipe: both edges of the reveal travel from `originEdge` to the
 * opposite edge, but one edge is eased with an exponent so it lags behind the
 * other mid-flight and rejoins it at 0 and 1 - producing a slanted edge that
 * resolves flush at both ends of the animation.
 */
function polygonClipPath(
  direction: ThemeTogglerButtonDirection,
  progress: number,
) {
  const horizontal = direction === "ltr" || direction === "rtl";
  const originEdge = direction === "ltr" || direction === "ttb" ? 0 : 100;
  const oppositeEdge = 100 - originEdge;
  const lagged = progress ** 1.7;
  const frontA = originEdge + (oppositeEdge - originEdge) * progress;
  const frontB = originEdge + (oppositeEdge - originEdge) * lagged;

  return horizontal
    ? `polygon(${originEdge}% 0%, ${frontA}% 0%, ${frontB}% 100%, ${originEdge}% 100%)`
    : `polygon(0% ${originEdge}%, 0% ${frontA}%, 100% ${frontB}%, 100% ${originEdge}%)`;
}

type TransitionFrames = {
  keyframes: Keyframe[];
  easing: string;
};

function buildTransitionFrames(
  variant: ThemeTogglerButtonVariant,
  direction: ThemeTogglerButtonDirection,
  origin: { x: number; y: number },
): TransitionFrames {
  switch (variant) {
    case "circle-blur": {
      const radius = getMaxRadius(origin.x, origin.y);
      return {
        keyframes: [
          {
            clipPath: circleClipPath(origin.x, origin.y, 0),
            filter: "blur(18px)",
          },
          {
            clipPath: circleClipPath(origin.x, origin.y, radius),
            filter: "blur(0px)",
          },
        ],
        easing: "ease-out",
      };
    }
    case "iris": {
      const radius = getMaxRadius(origin.x, origin.y);
      return {
        keyframes: [
          { clipPath: circleClipPath(origin.x, origin.y, 0) },
          { clipPath: circleClipPath(origin.x, origin.y, radius) },
        ],
        // Overshoots past full coverage then settles back, like a lens snapping into focus.
        easing: "cubic-bezier(0.34, 1.56, 0.64, 1)",
      };
    }
    case "polygon": {
      const steps = 8;
      const keyframes = Array.from({ length: steps + 1 }, (_, index) => ({
        clipPath: polygonClipPath(direction, index / steps),
      }));
      return { keyframes, easing: "ease-in-out" };
    }
    case "slide": {
      return {
        keyframes: [
          { clipPath: insetClipPath(direction, 0) },
          { clipPath: insetClipPath(direction, 1) },
        ],
        easing: "cubic-bezier(0.65, 0, 0.35, 1)",
      };
    }
    case "fade": {
      return {
        keyframes: [{ opacity: 0 }, { opacity: 1 }],
        easing: "ease",
      };
    }
    default: {
      const radius = getMaxRadius(origin.x, origin.y);
      return {
        keyframes: [
          { clipPath: circleClipPath(origin.x, origin.y, 0) },
          { clipPath: circleClipPath(origin.x, origin.y, radius) },
        ],
        easing: "ease-in-out",
      };
    }
  }
}

const defaultIcons: Record<ThemeTogglerButtonMode, ReactNode> = {
  light: <Sun />,
  dark: <Moon />,
  system: <Monitor />,
};

export type ThemeTogglerButtonProps = Omit<
  ComponentProps<"button">,
  "children"
> &
  VariantProps<typeof themeTogglerButtonVariants> & {
    variant?: ThemeTogglerButtonVariant;
    direction?: ThemeTogglerButtonDirection;
    modes?: ThemeTogglerButtonMode[];
    /** Duration (ms) of the reveal animation. */
    duration?: number;
    icons?: Partial<Record<ThemeTogglerButtonMode, ReactNode>>;
  };

function ThemeTogglerButton({
  variant = "circle",
  direction = "ltr",
  size = "md",
  modes = ["light", "dark"],
  duration = 650,
  icons,
  className,
  onClick,
  "aria-label": ariaLabel,
  ...props
}: ThemeTogglerButtonProps) {
  const { theme, resolvedTheme, setTheme } = useTheme();
  const shouldReduceMotion = useReducedMotion();
  const buttonRef = useRef<HTMLButtonElement | null>(null);

  const modeList: ThemeTogglerButtonMode[] =
    modes.length > 0 ? modes : ["light", "dark"];
  const activeMode: ThemeTogglerButtonMode =
    theme && (modeList as string[]).includes(theme)
      ? (theme as ThemeTogglerButtonMode)
      : modeList[0];
  const displayMode: ThemeTogglerButtonMode =
    activeMode === "system"
      ? "system"
      : resolvedTheme === "dark"
        ? "dark"
        : "light";

  const nextMode = useMemo(() => {
    const currentIndex = modeList.indexOf(activeMode);
    return modeList[(currentIndex + 1) % modeList.length] ?? modeList[0];
  }, [modeList, activeMode]);

  const runTransition = useCallback(
    (target: ThemeTogglerButtonMode) => {
      const doc = document as DocumentWithViewTransitions;
      const prefersReducedMotion =
        shouldReduceMotion ??
        window.matchMedia("(prefers-reduced-motion: reduce)").matches;

      if (
        typeof doc.startViewTransition !== "function" ||
        prefersReducedMotion
      ) {
        setTheme(target);
        return;
      }

      const rect = buttonRef.current?.getBoundingClientRect();
      const origin = {
        x: rect ? rect.left + rect.width / 2 : window.innerWidth / 2,
        y: rect ? rect.top + rect.height / 2 : window.innerHeight / 2,
      };

      const style = document.createElement("style");
      style.textContent =
        "::view-transition-old(root), ::view-transition-new(root) { animation: none; mix-blend-mode: normal; }";
      document.head.appendChild(style);

      const transition = doc.startViewTransition(() => {
        flushSync(() => setTheme(target));
      });

      transition.finished.finally(() => style.remove());

      transition.ready
        .then(() => {
          const { keyframes, easing } = buildTransitionFrames(
            variant,
            direction,
            origin,
          );

          document.documentElement.animate(keyframes, {
            duration,
            easing,
            pseudoElement: "::view-transition-new(root)",
          });
        })
        .catch(() => {
          // Transition was skipped (e.g. another one started first).
        });
    },
    [direction, duration, setTheme, shouldReduceMotion, variant],
  );

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    onClick?.(event);
    runTransition(nextMode);
  }

  const spin = direction === "rtl" || direction === "btt" ? -1 : 1;
  const icon = icons?.[displayMode] ?? defaultIcons[displayMode];

  return (
    <button
      ref={buttonRef}
      type="button"
      data-slot="theme-toggler-button"
      aria-label={ariaLabel ?? `Switch to ${nextMode} theme`}
      onClick={handleClick}
      className={twMerge(themeTogglerButtonVariants({ size }), className)}
      {...props}
    >
      <AnimatePresence mode="wait" initial={false}>
        <motion.span
          key={displayMode}
          data-slot="theme-toggler-button-icon"
          className="inline-flex"
          initial={
            shouldReduceMotion
              ? false
              : { opacity: 0, rotate: -90 * spin, scale: 0.4 }
          }
          animate={{ opacity: 1, rotate: 0, scale: 1 }}
          exit={
            shouldReduceMotion
              ? undefined
              : { opacity: 0, rotate: 90 * spin, scale: 0.4 }
          }
          transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
        >
          {icon}
        </motion.span>
      </AnimatePresence>
    </button>
  );
}

export { ThemeTogglerButton };

