function BadgeDot({ pulse }: { pulse?: boolean }) {
  return (
    <span
      data-slot="badge-dot"
      data-pulse={pulse ? "" : undefined}
      className={twMerge(
        "relative size-1.5 shrink-0 rounded-full bg-current opacity-70",
