        <span className="absolute top-1/2 left-1/2 h-px w-2 -translate-x-1/2 -translate-y-1/2 rotate-45 rounded-full bg-current transition-transform duration-200 group-hover/dismiss:rotate-[50deg]" />
        <span className="absolute top-1/2 left-1/2 h-px w-2 -translate-x-1/2 -translate-y-1/2 -rotate-45 rounded-full bg-current transition-transform duration-200 group-hover/dismiss:-rotate-[50deg]" />
