export function Badge({
  className,
  variant,
  size,
  shape,
  interactive = false,
  selected,
  iconLeft,
  iconRight,
  dot,
  pulse,
  count,
  dismissible,
  dismissLabel = "Remove badge",
  onDismiss,
  children,
  disabled,
  type = "button",
  onClick,
  ...props
}: BadgeProps) {
  const substrate = useSurface();
  const isLive = variant === "live" || variant === "pulse";
  const showDot = Boolean(dot || pulse || isLive || shape === "dot");
  const showPulse = Boolean(pulse || isLive);
  const content = count ?? children;
  const surfaceClassName =
    variant === "surface"
      ? surfaceClasses(Math.min(substrate + 1, 8), substrate)
      : variant === "inset"
        ? surfaceClasses(Math.max(substrate - 1, 1), substrate)
        : undefined;
  const badgeClassName = twMerge(
    badgeVariants({ variant, size, shape, interactive, selected }),
    surfaceClassName,
    className,
  );

  const badgeContent = (
    <>
      {showDot ? <BadgeDot pulse={showPulse} /> : null}
      {iconLeft ? <BadgeIcon>{iconLeft}</BadgeIcon> : null}
      {content !== undefined && content !== null ? (
        <span className="min-w-0 truncate">{content}</span>
      ) : null}
      {iconRight ? <BadgeIcon>{iconRight}</BadgeIcon> : null}
    </>
  );

  if (interactive && !dismissible) {
    return (
      <button
        data-slot="badge"
        data-selected={selected ? "" : undefined}
        disabled={disabled}
        type={type}
        onClick={onClick}
        className={badgeClassName}
        {...props}
      >
        {badgeContent}
      </button>
    );
  }

  return (
    <span
      data-slot="badge"
      data-selected={selected ? "" : undefined}
      className={badgeClassName}
      {...props}
    >
      {interactive ? (
        <button
          type={type}
          disabled={disabled}
          onClick={onClick}
          className="inline-flex min-w-0 items-center gap-[inherit] rounded-[inherit] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50"
        >
          {badgeContent}
        </button>
      ) : (
        badgeContent
      )}
      {dismissible ? (
        <BadgeDismiss
          label={dismissLabel}
          onDismiss={onDismiss}
          disabled={disabled}
        />
      ) : null}
    </span>
  );
}

"use client";

import {
  type Column,
  type ColumnDef,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  type SortingState,
  type Table as TanStackTable,
  useReactTable,
} from "@tanstack/react-table";
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  ChevronDown,
  ChevronLeft,
  ChevronRight,
} from "lucide-react";
import type { ComponentProps } from "react";
import { useState } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";

import { Elevated } from "@/components/matos-ui/elevated";

export const dataTableVariants = tv({
  base: "not-prose w-full text-foreground",
});

export type DataTableProps<TData, TValue> = ComponentProps<"div"> &
  VariantProps<typeof dataTableVariants> & {
    data: TData[];
    columns: ColumnDef<TData, TValue>[];
    pageSize?: number;
    totalItems?: number;
    showingLabel?: string;
    loading?: boolean;
    footer?: boolean;
  };

export function DataTable<TData, TValue>({
  data,
  columns,
  pageSize = 7,
  totalItems,
  showingLabel = "SHOWING",
  loading = false,
  footer = true,
  className,
  ...props
}: DataTableProps<TData, TValue>) {
  const [sorting, setSorting] = useState<SortingState>([]);

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
    },
    initialState: {
      pagination: {
        pageSize,
      },
    },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
  });

  const rows = table.getRowModel().rows;
  const filteredRows = table.getFilteredRowModel().rows.length;
  const finalTotalItems = totalItems ?? filteredRows;
  const currentPage = table.getState().pagination.pageIndex + 1;
  const pageCount = table.getPageCount();

  return (
    <div
      data-slot="data-table"
      className={twMerge(dataTableVariants(), className)}
      {...props}
    >
      <Elevated
        data-slot="data-table-card"
        offset={1}
        className="overflow-hidden rounded-2xl p-2"
      >
        <Elevated
          data-slot="data-table-panel"
          offset={1}
          className="overflow-hidden rounded-xl"
        >
          <Table>
            <TableHeader>
              {table.getHeaderGroups().map((headerGroup) => (
                <TableRow
                  key={headerGroup.id}
                  className=" bg-muted/30 hover:bg-muted/30"
                >
                  {headerGroup.headers.map((header) => (
                    <TableHead
                      key={header.id}
                      style={{
                        width:
                          header.getSize() !== 150
                            ? header.getSize()
                            : undefined,
                      }}
                    >
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext(),
                          )}
                    </TableHead>
                  ))}
                </TableRow>
              ))}
            </TableHeader>

            <TableBody>
              {loading ? (
                <DataTableSkeleton rows={pageSize} columns={columns.length} />
              ) : rows.length ? (
                rows.map((row) => (
                  <TableRow key={row.id}>
                    {row.getVisibleCells().map((cell) => (
                      <TableCell key={cell.id}>
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </TableCell>
                    ))}
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell
                    colSpan={columns.length}
                    className="h-32 text-center text-muted-foreground"
                  >
                    No results found.
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </Elevated>

        {footer ? (
          <DataTablePagination
            table={table}
            showingLabel={showingLabel}
            currentCount={rows.length}
            totalItems={finalTotalItems}
            currentPage={currentPage}
            pageCount={pageCount}
            loading={loading}
          />
        ) : null}
      </Elevated>
    </div>
  );
}

export function DataTablePagination<TData>({
  table,
  showingLabel,
  currentCount,
  totalItems,
  currentPage,
  pageCount,
  loading,
  className,
}: ComponentProps<"div"> & {
  table: TanStackTable<TData>;
  showingLabel: string;
  currentCount: number;
  totalItems: number;
  currentPage: number;
  pageCount: number;
  loading?: boolean;
}) {
  return (
    <div
      data-slot="data-table-footer"
      className={twMerge(
        "flex min-h-9 flex-col items-stretch gap-2 px-2 pt-2 text-muted-foreground sm:h-9 sm:flex-row sm:items-center sm:justify-between sm:px-3",
        className,
      )}
    >
      <p className="text-center font-mono text-[0.68rem] uppercase tracking-[0.16em] sm:text-left">
        {showingLabel}: <span className="text-foreground">{currentCount}</span>{" "}
        of <span className="text-foreground">{totalItems}</span> items
      </p>

      <div
        data-slot="data-table-pagination"
        className="flex items-center justify-center gap-2 sm:justify-start"
      >
        <button
          type="button"
          aria-label="Previous page"
          disabled={!table.getCanPreviousPage() || loading}
          className="inline-flex size-6 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-background hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-35"
          onClick={() => table.previousPage()}
        >
          <ChevronLeft className="size-4" aria-hidden="true" />
        </button>

        <span className="min-w-8 text-center font-medium text-xs text-foreground">
          {currentPage}/{pageCount || 1}
        </span>

        <button
          type="button"
          aria-label="Next page"
          disabled={!table.getCanNextPage() || loading}
          className="inline-flex size-6 items-center justify-center rounded-md bg-background text-muted-foreground shadow-xs ring-1 ring-border/70 transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-35"
          onClick={() => table.nextPage()}
        >
          <ChevronRight className="size-4" aria-hidden="true" />
        </button>
      </div>
    </div>
  );
}

export function DataTableColumnHeader<TData, TValue>({
  column,
  title,
  className,
}: {
  column: Column<TData, TValue>;
  title: string;
  className?: string;
}) {
  if (!column.getCanSort()) {
    return (
      <span
        data-slot="data-table-column-header"
        className={twMerge(
          "inline-flex items-center gap-1 font-mono text-[0.68rem] font-semibold uppercase tracking-[0.14em] text-muted-foreground",
          className,
        )}
      >
        {title}
      </span>
    );
  }

  const sorted = column.getIsSorted();
  const SortIcon =
    sorted === "asc" ? ArrowUp : sorted === "desc" ? ArrowDown : ArrowUpDown;

  return (
    <button
      type="button"
      data-slot="data-table-column-header"
      aria-label={`Sort by ${title}`}
      className={twMerge(
        "inline-flex items-center gap-1 rounded-md font-mono text-[0.68rem] font-semibold uppercase tracking-[0.14em] text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
        sorted && "text-foreground",
        className,
      )}
      onClick={column.getToggleSortingHandler()}
    >
      <span>{title}</span>
      <SortIcon className="size-3" aria-hidden="true" />
    </button>
  );
}

