  return (
    <motion.span
      layout
      layoutId={layoutId}
      className={twMerge(
        styles.media(),
        expanded ? styles.mediaExpanded() : styles.mediaCompact(),
        activity.variant === "recording"
          ? "bg-destructive/15 text-destructive dark:bg-destructive/20"
