          }
          transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}
          aria-hidden="true"
        />
      ) : null}
      {activity.image
        ? null
        : (children ?? <ActivityIcon activity={activity} />)}
    </motion.span>
  );
}

function Equalizer({ active }: { active?: boolean }) {
  const shouldReduceMotion = useReducedMotion();
  const bars = [
    { id: "low", height: 0.4 },
    { id: "peak", height: 0.8 },
    { id: "mid", height: 0.56 },
    { id: "high", height: 0.95 },
  ];

  return (
    <span className="flex h-4 shrink-0 items-end gap-0.5" aria-hidden="true">
      {bars.map((bar) => (
        <motion.span
          key={bar.id}
          className="w-0.5 rounded-full bg-background dark:bg-primary"
          animate={
            shouldReduceMotion || !active
              ? { height: `${bar.height * 54}%`, opacity: active ? 1 : 0.42 }
              : {
                  height: [
                    `${bar.height * 42}%`,
                    `${bar.height * 100}%`,
                    `${bar.height * 58}%`,
                  ],
                  opacity: [0.65, 1, 0.75],
                }
          }
          transition={{
            duration:
              bar.id === "low"
                ? 0.7
                : bar.id === "peak"
                  ? 0.78
                  : bar.id === "mid"
                    ? 0.86
                    : 0.94,
            repeat: active ? Infinity : 0,
            repeatType: "mirror",
            ease: "easeInOut",
          }}
        />
      ))}
    </span>
  );
}

