function generateId() {
  return Math.random().toString(36).slice(2, 10);
}

function formatFileSize(bytes: number): string {
  if (bytes === 0) {
    return "0 B";
  }

  const units = ["B", "KB", "MB", "GB"];
  const index = Math.min(
    Math.floor(Math.log(bytes) / Math.log(1024)),
    units.length - 1,
  );

  return `${(bytes / 1024 ** index).toFixed(index === 0 ? 0 : 1)} ${
    units[index]
  }`;
}

function formatAccept(accept?: string) {
  if (!accept) {
    return "Any file";
  }

  return accept
    .split(",")
    .slice(0, 3)
    .map((item) => item.trim().replace("image/*", "images"))
    .join(", ");
}

function getEntryStatus(entry: FileUploadFile): FileUploadFileStatus {
  if (entry.error) {
    return "error";
  }

  return entry.status ?? "success";
}

function getStatusLabel(status: FileUploadFileStatus) {
  if (status === "uploading") {
    return "Uploading";
  }

  if (status === "success") {
    return "Ready";
  }

  if (status === "error") {
    return "Invalid";
  }

  return "Queued";
}

export function FileUpload({
  className,
  variant = "default",
  size = "md",
  state,
  accept,
  multiple = false,
  maxSize,
  maxFiles,
  files: controlledFiles,
  onFilesChange,
  title,
  description,
  disabled = false,
  uploading = false,
  ...props
}: FileUploadProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const shouldReduceMotion = useReducedMotion();
  const [dragging, setDragging] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);
  const [internalFiles, setInternalFiles] = useState<FileUploadFile[]>([]);

  const isControlled = controlledFiles !== undefined;
  const files = isControlled ? controlledFiles : internalFiles;
  const hasError = Boolean(lastError || files.some((entry) => entry.error));
  const resolvedState =
    state ?? (hasError ? "error" : uploading ? "uploading" : "default");

  const styles = fileUploadVariants({
    variant,
    size,
    isDragging: dragging,
    disabled,
    state: resolvedState,
  });

  const updateFiles = useCallback(
    (next: FileUploadFile[]) => {
      if (!isControlled) {
        setInternalFiles(next);
      }

      onFilesChange?.(next);
    },
    [isControlled, onFilesChange],
  );

  const validateFile = useCallback(
    (file: File): string | undefined => {
      if (maxSize && file.size > maxSize) {
        return `Larger than ${formatFileSize(maxSize)}`;
      }

      return undefined;
    },
    [maxSize],
  );

  const addFiles = useCallback(
    (incoming: File[]) => {
      if (disabled || incoming.length === 0) {
        return;
      }

      setLastError(null);

      const allowedSlots = multiple
        ? Math.max(
            (maxFiles ?? incoming.length + files.length) - files.length,
            0,
          )
        : 1;

      if (multiple && maxFiles && files.length + incoming.length > maxFiles) {
        setLastError(`Maximum ${maxFiles} files`);
      }

      if (allowedSlots === 0) {
        return;
      }

      const entries: FileUploadFile[] = incoming
        .slice(0, allowedSlots)
        .map((file) => {
          const error = validateFile(file);

          return {
            file,
            id: generateId(),
            error,
            status: error ? "error" : uploading ? "uploading" : "success",
            progress: uploading && !error ? 48 : undefined,
          };
        });

      updateFiles(multiple ? [...files, ...entries] : entries.slice(0, 1));
    },
    [disabled, files, maxFiles, multiple, updateFiles, uploading, validateFile],
  );

  const removeFile = useCallback(
    (id: string) => {
      updateFiles(files.filter((entry) => entry.id !== id));
    },
    [files, updateFiles],
  );

  const openFileDialog = useCallback(() => {
    if (!disabled) {
      inputRef.current?.click();
    }
  }, [disabled]);

  const handleDragOver = useCallback(
    (event: DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      event.stopPropagation();

      if (!disabled) {
        setDragging(true);
      }
    },
    [disabled],
  );

  const handleDragLeave = useCallback((event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();

    if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
      setDragging(false);
    }
  }, []);

  const handleDrop = useCallback(
    (event: DragEvent<HTMLDivElement>) => {
      event.preventDefault();
      event.stopPropagation();
      setDragging(false);

      addFiles(Array.from(event.dataTransfer.files ?? []));
    },
    [addFiles],
  );

  const handleChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      addFiles(Array.from(event.target.files ?? []));
      event.target.value = "";
    },
    [addFiles],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openFileDialog();
      }
    },
    [openFileDialog],
  );

  const defaultTitle = dragging ? "Drop files here" : "Upload files";
  const defaultDescription = multiple
    ? "Drag files here or choose from your device"
    : "Drag a file here or choose from your device";

  return (
    <Elevated
      data-slot="file-upload"
      offset={1}
      className={twMerge(styles.root(), className)}
      {...props}
    >
      <Elevated offset={1} className="rounded-xl">
        <motion.div
          data-slot="file-upload-dropzone"
          role="button"
          tabIndex={disabled ? -1 : 0}
          aria-label={title ?? defaultTitle}
          aria-disabled={disabled}
          data-disabled={disabled}
          onClick={openFileDialog}
          onKeyDown={handleKeyDown}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          className={styles.dropzone()}
          animate={
            shouldReduceMotion
              ? undefined
              : hasError
                ? { x: [0, -2, 2, -1, 1, 0] }
                : { scale: dragging ? 1.01 : 1 }
          }
          whileHover={
            shouldReduceMotion || disabled ? undefined : { y: -1, scale: 1.002 }
          }
          whileTap={
            shouldReduceMotion || disabled ? undefined : { scale: 0.998 }
          }
          transition={
            hasError ? { duration: 0.24, ease: smoothEase } : spring.fast
          }
        >
          <motion.span
            className={styles.iconWrap()}
            animate={
              shouldReduceMotion
                ? undefined
                : { y: dragging ? -1 : 0, scale: dragging ? 1.04 : 1 }
            }
            transition={{ duration: 0.22, ease: smoothEase }}
            aria-hidden="true"
          >
            {resolvedState === "uploading" ? (
              <Loader2 className="size-4 animate-spin" />
            ) : resolvedState === "success" ? (
              <motion.span
                initial={
                  shouldReduceMotion ? false : { scale: 0.7, opacity: 0 }
                }
                animate={{ scale: 1, opacity: 1 }}
                transition={{ duration: 0.18, ease: smoothEase }}
              >
                <Check className="size-4" />
              </motion.span>
            ) : resolvedState === "error" ? (
              <AlertCircle className="size-4" />
            ) : (
              <Upload className="size-4" />
            )}
          </motion.span>

          <div className={styles.copy()}>
            <div className={styles.header()}>
              <span className={styles.title()}>{title ?? defaultTitle}</span>
              <span className={styles.badge()}>{formatAccept(accept)}</span>
            </div>
            <p className={styles.description()}>
              {description ?? defaultDescription}
            </p>
          </div>
        </motion.div>
      </Elevated>

      <input
        ref={inputRef}
        id={inputId}
        type="file"
        className="sr-only"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        onChange={handleChange}
      />

      <AnimatePresence initial={false}>
        {(files.length > 0 || lastError) && (
          <motion.div
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 4 }}
            animate={shouldReduceMotion ? { opacity: 1 } : { opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
            transition={spring.fast}
          >
            {lastError ? (
              <p className={styles.error()} aria-live="polite">
                <AlertCircle className="size-3.5" aria-hidden="true" />
                {lastError}
              </p>
            ) : null}

            {files.length > 0 ? (
              <motion.ul
                data-slot="file-upload-list"
                className={styles.list()}
                variants={shouldReduceMotion ? undefined : listVariants}
                initial={shouldReduceMotion ? false : "hidden"}
                animate="visible"
              >
                <AnimatePresence initial={false}>
                  {files.map((entry) => {
                    const status = getEntryStatus(entry);
                    const progress =
                      entry.progress ?? (status === "uploading" ? 52 : 100);

                    return (
                      <motion.li
                        key={entry.id}
                        data-slot="file-upload-item"
                        layout
                        className={styles.item()}
                        variants={shouldReduceMotion ? undefined : itemVariants}
                        initial={shouldReduceMotion ? { opacity: 0 } : "hidden"}
                        animate={
                          shouldReduceMotion ? { opacity: 1 } : "visible"
                        }
                        exit={shouldReduceMotion ? { opacity: 0 } : "exit"}
                      >
                        <FileText
                          className={styles.fileIcon()}
                          aria-hidden="true"
                        />

                        <div className="min-w-0">
                          <p className={styles.fileName()}>{entry.file.name}</p>
                          <div className={styles.fileMeta()}>
                            <span>{formatFileSize(entry.file.size)}</span>
                            {entry.error ? <span>{entry.error}</span> : null}
                          </div>
                          {status === "uploading" ? (
                            <div
                              className={styles.progressTrack()}
                              aria-hidden="true"
                            >
                              <motion.div
                                className={styles.progressBar()}
                                initial={{ width: "12%" }}
                                animate={{ width: `${progress}%` }}
                                transition={{
                                  duration: 0.45,
                                  ease: smoothEase,
                                }}
                              />
                            </div>
                          ) : null}
                        </div>

                        <span className={styles.status()}>
                          {getStatusLabel(status)}
                        </span>

                        <button
                          type="button"
                          aria-label={`Remove ${entry.file.name}`}
                          className={styles.removeButton()}
                          disabled={disabled}
                          onClick={(event) => {
                            event.stopPropagation();
                            removeFile(entry.id);
                          }}
                        >
                          <X className="size-3.5" aria-hidden="true" />
                        </button>
                      </motion.li>
                    );
                  })}
                </AnimatePresence>
              </motion.ul>
            ) : null}
          </motion.div>
        )}
      </AnimatePresence>
    </Elevated>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { ChevronDown } from "lucide-react";
import {
  createContext,
  type KeyboardEvent,
  type ReactNode,
  useCallback,
  useContext,
  useId,
  useMemo,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";
import { spring } from "@/lib/motion-tokens";
import { Elevated } from "@/components/matos-ui/elevated";

const MotionElevated = motion.create(Elevated);

type ExpandableListContextValue = {
  openValues: Set<string>;
  toggle: (value: string) => void;
  registerItem: (value: string, node: HTMLButtonElement | null) => void;
  focusAdjacent: (value: string, direction: 1 | -1) => void;
};

const ExpandableListContext = createContext<ExpandableListContextValue | null>(
  null,
);

function useExpandableListContext(component: string) {
  const context = useContext(ExpandableListContext);
  if (!context) {
    throw new Error(`${component} must be used within an <ExpandableList>.`);
  }
  return context;
}

export interface ExpandableListProps {
  children: ReactNode;
  /** Item values expanded on mount. Any number of items can stay open at once. */
  defaultOpenValues?: string[];
  className?: string;
}

export function ExpandableList({
  children,
  defaultOpenValues = [],
  className,
}: ExpandableListProps) {
  const [openValues, setOpenValues] = useState<Set<string>>(
    () => new Set(defaultOpenValues),
  );
  // Registration order, not DOM order, drives arrow-key navigation — items
  // register on mount, so this stays correct even if the list reorders.
  const itemsRef = useRef<Map<string, HTMLButtonElement>>(new Map());
  const orderRef = useRef<string[]>([]);

  const toggle = useCallback((value: string) => {
    setOpenValues((current) => {
      const next = new Set(current);
      if (next.has(value)) {
        next.delete(value);
      } else {
        next.add(value);
      }
      return next;
    });
  }, []);

  const registerItem = useCallback(
    (value: string, node: HTMLButtonElement | null) => {
      if (node) {
        itemsRef.current.set(value, node);
        if (!orderRef.current.includes(value)) {
          orderRef.current.push(value);
        }
      } else {
        itemsRef.current.delete(value);
        orderRef.current = orderRef.current.filter(
          (current) => current !== value,
        );
      }
    },
    [],
  );

  const focusAdjacent = useCallback((value: string, direction: 1 | -1) => {
    const order = orderRef.current;
    const index = order.indexOf(value);
    if (index === -1 || order.length === 0) return;
    const nextIndex = (index + direction + order.length) % order.length;
    const nextValue = order[nextIndex];
    if (nextValue) {
      itemsRef.current.get(nextValue)?.focus();
    }
  }, []);

  const contextValue = useMemo<ExpandableListContextValue>(
    () => ({ openValues, toggle, registerItem, focusAdjacent }),
    [openValues, toggle, registerItem, focusAdjacent],
  );

  return (
    <ExpandableListContext.Provider value={contextValue}>
      <ul
        data-slot="expandable-list"
        className={cn("flex list-none flex-col gap-2", className)}
      >
        {children}
      </ul>
    </ExpandableListContext.Provider>
  );
}

export interface ExpandableListItemProps {
  value: string;
  title: ReactNode;
  children: ReactNode;
  className?: string;
}

export function ExpandableListItem({
  value,
  title,
  children,
  className,
}: ExpandableListItemProps) {
  const { openValues, toggle, registerItem, focusAdjacent } =
    useExpandableListContext("ExpandableListItem");
  const open = openValues.has(value);
  const shouldReduceMotion = useReducedMotion();
  const triggerId = useId();
  const panelId = useId();

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key === "ArrowDown") {
      event.preventDefault();
      focusAdjacent(value, 1);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      focusAdjacent(value, -1);
    }
    // Enter/Space activate the button natively — nothing to add here.
  }

  return (
    // `layout` on this wrapper is what animates the height change: the
    // panel below only fades/slides its own opacity, and Framer's FLIP
    // measurement turns that size delta into a smooth resize — no raw
    // `height: auto` tween, which never actually settles cleanly.
    <motion.li
      layout={!shouldReduceMotion}
      data-slot="expandable-list-item"
      className={cn("overflow-hidden rounded-xl bg-muted/30", className)}
    >
      <button
        ref={(node) => registerItem(value, node)}
        id={triggerId}
        type="button"
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => toggle(value)}
        onKeyDown={handleKeyDown}
        className={cn(
          "flex w-full items-center justify-between gap-3 px-4 py-3 text-left text-sm font-medium text-foreground outline-none",
          "transition-colors duration-150 hover:bg-muted/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset",
        )}
      >
        <span>{title}</span>
        <motion.span
          animate={{ rotate: open ? 180 : 0 }}
          transition={shouldReduceMotion ? { duration: 0 } : spring.fast}
          className="shrink-0 text-muted-foreground"
        >
          <ChevronDown className="size-4" aria-hidden="true" />
        </motion.span>
      </button>

      <AnimatePresence initial={false}>
        {open ? (
          <MotionElevated
            key="panel"
            offset={1}
            id={panelId}
            role="region"
            aria-labelledby={triggerId}
            initial={
              shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }
            }
            animate={{ opacity: 1, y: 0 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -4 }}
            transition={shouldReduceMotion ? { duration: 0 } : spring.moderate}
            className="rounded-none p-4 text-sm leading-relaxed text-muted-foreground"
          >
            {children}
          </MotionElevated>
        ) : null}
      </AnimatePresence>
    </motion.li>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Variants,
} from "framer-motion";
import { Activity, AlertCircle, Check, Clock, X } from "lucide-react";
import {
  createContext,
  type ReactNode,
  useContext,
  useEffect,
  useMemo,
  useRef,
} from "react";

import { cn } from "@/lib/utils";
import {
  spring,
  staggerContainer,
} from "@/lib/motion-tokens";
import { Elevated } from "@/components/matos-ui/elevated";

export type LiveQueueItemStatus = "pending" | "running" | "done" | "failed";

export type LiveQueueItemData = {
  id: string;
  title: string;
  description?: string;
  status: LiveQueueItemStatus;
};

type LiveQueueContextValue = {
  onItemComplete?: (id: string) => void;
};

const LiveQueueContext = createContext<LiveQueueContextValue>({});

export function useLiveQueueContext() {
  return useContext(LiveQueueContext);
}

export interface LiveQueueProps<T extends LiveQueueItemData> {
  items: T[];
  /** Called when a terminal (done/failed) item should leave the queue. */
  onItemComplete?: (id: string) => void;
  children: (item: T) => ReactNode;
  className?: string;
  "aria-label"?: string;
}

export function LiveQueue<T extends LiveQueueItemData>({
  items,
  onItemComplete,
  children,
  className,
  "aria-label": ariaLabel = "Live queue",
}: LiveQueueProps<T>) {
  const shouldReduceMotion = useReducedMotion();
  const contextValue = useMemo<LiveQueueContextValue>(
    () => ({ onItemComplete }),
    [onItemComplete],
  );

  return (
    <LiveQueueContext.Provider value={contextValue}>
      <motion.ul
        data-slot="live-queue"
        aria-live="polite"
        aria-label={ariaLabel}
        variants={shouldReduceMotion ? undefined : staggerContainer("fast")}
        initial="hidden"
        animate="visible"
        className={cn("flex list-none flex-col gap-2", className)}
      >
        <AnimatePresence mode="popLayout">
          {items.map((item) => children(item))}
        </AnimatePresence>
      </motion.ul>
    </LiveQueueContext.Provider>
  );
}

const itemVariants: Variants = {
  hidden: { opacity: 0, y: 8, scale: 0.98 },
  visible: { opacity: 1, y: 0, scale: 1, transition: spring.fast },
};

const reducedItemVariants: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { duration: 0 } },
};

const statusConfig: Record<
  LiveQueueItemStatus,
  { label: string; icon: typeof Clock; toneClassName: string }
> = {
  pending: {
    label: "Queued",
    icon: Clock,
    toneClassName: "text-muted-foreground",
  },
  running: {
    label: "Running",
    icon: Activity,
    toneClassName: "text-foreground",
  },
  done: {
    label: "Done",
    icon: Check,
    toneClassName: "text-primary",
  },
  failed: {
    label: "Failed",
    icon: AlertCircle,
    toneClassName: "text-destructive",
  },
};

// How long a "done" item lingers before it clears itself. Failures don't
// auto-clear — an error disappearing on its own would be easy to miss.
const AUTO_COMPLETE_DELAY_MS = 2400;

export interface LiveQueueItemProps<
  T extends LiveQueueItemData = LiveQueueItemData,
> {
  item: T;
  className?: string;
}

export function LiveQueueItem<T extends LiveQueueItemData>({
  item,
  className,
}: LiveQueueItemProps<T>) {
  const { onItemComplete } = useLiveQueueContext();
  const shouldReduceMotion = useReducedMotion();
  const firedRef = useRef(false);

  useEffect(() => {
    if (item.status !== "done") {
      firedRef.current = false;
      return;
    }
    if (firedRef.current) return;
    firedRef.current = true;

    const timer = window.setTimeout(() => {
      onItemComplete?.(item.id);
    }, AUTO_COMPLETE_DELAY_MS);

    return () => window.clearTimeout(timer);
  }, [item.status, item.id, onItemComplete]);

  const config = statusConfig[item.status];
  const StatusIcon = config.icon;
  const isTerminal = item.status === "done" || item.status === "failed";
  const isRunning = item.status === "running";

  return (
    <motion.li
      layout={!shouldReduceMotion}
      variants={shouldReduceMotion ? reducedItemVariants : itemVariants}
      exit={
        shouldReduceMotion
          ? { opacity: 0, transition: { duration: 0 } }
          : { opacity: 0, scale: 0.96, transition: spring.fast }
      }
      className={cn("list-none", className)}
    >
      <Elevated
        offset={1}
        className="relative flex items-center gap-3 overflow-hidden rounded-xl p-3"
      >
        <span
          className={cn(
            "flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted/60",
            config.toneClassName,
          )}
        >
          <StatusIcon className="size-4" aria-hidden="true" />
        </span>

        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-medium text-foreground">
            {item.title}
          </p>
          {item.description ? (
            <p className="truncate text-xs text-muted-foreground">
              {item.description}
            </p>
          ) : null}
        </div>

        <span
          className={cn("shrink-0 text-xs font-medium", config.toneClassName)}
        >
          {config.label}
        </span>

        {isTerminal ? (
          <button
            type="button"
            onClick={() => onItemComplete?.(item.id)}
            aria-label={`Dismiss ${item.title}`}
            className="shrink-0 rounded-md p-1 text-muted-foreground outline-none transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
          >
            <X className="size-3.5" aria-hidden="true" />
          </button>
        ) : null}

        {isRunning ? (
          <span
            aria-hidden="true"
            className="absolute inset-x-0 bottom-0 h-0.5 overflow-hidden bg-muted/50"
          >
            <motion.span
              className="block h-full w-1/3 rounded-full bg-primary/70"
              animate={
                shouldReduceMotion ? { x: "0%" } : { x: ["-100%", "300%"] }
              }
              transition={
                shouldReduceMotion
                  ? { duration: 0 }
                  : {
                      duration: 1.1,
                      ease: "linear",
                      repeat: Number.POSITIVE_INFINITY,
                    }
              }
            />
          </span>
        ) : null}
      </Elevated>
    </motion.li>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Variants,
} from "framer-motion";
import { X } from "lucide-react";
import {
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";

import { cn } from "@/lib/utils";
import {
  attentionPulse,
  spring,
  staggerContainer,
  useExitAnimation,
} from "@/lib/motion-tokens";
import { SurfaceProvider } from "@/lib/surface-context";
import { Elevated } from "@/components/matos-ui/elevated";

/** Steps above the page. Matches the conventional "above a dialog" rung. */
const ACHIEVEMENT_TOAST_OFFSET = 3;

/** Default time on screen, in ms. Pass `duration={0}` to keep it until dismissed. */
export const ACHIEVEMENT_TOAST_DURATION = 4000;

export type AchievementToastPosition =
  | "top-left"
  | "top-right"
  | "bottom-left"
  | "bottom-right";

const positionClasses: Record<AchievementToastPosition, string> = {
  "top-left": "top-4 left-4 items-start",
  "top-right": "top-4 right-4 items-end",
  "bottom-left": "bottom-4 left-4 items-start",
  "bottom-right": "bottom-4 right-4 items-end",
};

const isTop = (position: AchievementToastPosition) =>
  position.startsWith("top");

/**
 * The card arrives from off the nearest edge, so a bottom-corner toast rises
 * into place and a top-corner one drops in — the bounce lands against the edge
 * it came from instead of against nothing.
 */
function cardVariantsFor(position: AchievementToastPosition): Variants {
  const travel = isTop(position) ? -12 : 12;
  return {
    hidden: { opacity: 0, y: travel, scale: 0.9 },
    visible: {
      opacity: 1,
      y: 0,
      scale: 1,
      // The one place spring.playful is spent: a toast that only appears when
      // something went right. Chosen by hand, never via motionForOffset.
      transition: spring.playful,
    },
    // Exit runs on the tier's *exit* duration, not its full duration. The
    // unmount guard in useExitAnimation is armed off that same number, so an
    // exit animating for the longer entrance duration would get cut short.
    exit: {
      opacity: 0,
      y: travel * 0.6,
      scale: 0.96,
      transition: { duration: spring.playful.exit.duration },
    },
  };
}

const reducedCardVariants: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: spring.fast },
  exit: { opacity: 0, transition: { duration: spring.fast.exit.duration } },
};

/**
 * Counts down to a self-dismiss, and returns the handlers that suspend it.
 *
 * Pointer or focus inside the toast stops the clock: a celebration that
 * vanishes out from under the cursor reading it is worse than one that
 * overstays. Leaving restarts the full window rather than resuming the
 * remainder — whatever was just read deserves to be readable again.
 */
function useAutoDismiss(
  active: boolean,
  duration: number,
  onDismiss: () => void,
) {
  const [paused, setPaused] = useState(false);
  const onDismissRef = useRef(onDismiss);

  useEffect(() => {
    onDismissRef.current = onDismiss;
  }, [onDismiss]);

  useEffect(() => {
    if (!active || paused || duration <= 0) return;
    const timer = window.setTimeout(() => onDismissRef.current(), duration);
    return () => window.clearTimeout(timer);
  }, [active, paused, duration]);

  return {
    onPointerEnter: () => setPaused(true),
    onPointerLeave: () => setPaused(false),
    onFocusCapture: () => setPaused(true),
    onBlurCapture: () => setPaused(false),
  } as const;
}

type AchievementToastViewportProps = {
  position: AchievementToastPosition;
  className?: string;
  children: ReactNode;
};

function AchievementToastViewport({
  position,
  className,
  children,
}: AchievementToastViewportProps) {
  const [container, setContainer] = useState<HTMLElement | null>(null);

  // document.body only exists after hydration; reading it during render would
  // break SSR.
  useEffect(() => setContainer(document.body), []);

  if (!container) {
    return null;
  }

  return createPortal(
    // The toast is pinned to the viewport, so its substrate is always the page
    // — not whatever card happened to render it. Resetting the surface here
    // keeps offset={3} meaning the same rung from anywhere in the tree, which
    // is the opposite of what a nestable overlay like Stacked Dialog wants.
    <SurfaceProvider value={1}>
      <div
        data-slot="achievement-toast-viewport"
        aria-live="polite"
        className={cn(
          "not-prose pointer-events-none fixed z-50 flex w-[min(22rem,calc(100vw-2rem))] flex-col gap-2",
          positionClasses[position],
          className,
        )}
      >
        {children}
      </div>
    </SurfaceProvider>,
    container,
  );
}

type AchievementCardProps = {
  title: string;
  description?: string;
  icon?: ReactNode;
  /** True once the entrance has settled, which is what cues the icon pulse. */
  landed: boolean;
  onDismiss: () => void;
  shouldReduceMotion: boolean;
  className?: string;
};

function AchievementCard({
  title,
  description,
  icon,
  landed,
  onDismiss,
  shouldReduceMotion,
  className,
}: AchievementCardProps) {
  return (
    <Elevated
      offset={ACHIEVEMENT_TOAST_OFFSET}
      data-slot="achievement-toast"
      className={cn(
        // No border: the shadow-surface ring on <Elevated> already draws the
        // edge, and a border on top of it flattens the ladder.
        "flex w-full items-start gap-3 overflow-hidden rounded-2xl p-3 text-foreground",
        className,
      )}
    >
      {icon ? (
        <Elevated
          offset={1}
          className="flex size-9 shrink-0 items-center justify-center rounded-xl text-primary [&_svg]:size-4"
        >
          <motion.span
            className="flex items-center justify-center"
            variants={shouldReduceMotion ? undefined : attentionPulse}
            // Fires on landing, not on mount, so the pulse reads as the toast
            // settling rather than as a second thing happening at once.
            animate={landed && !shouldReduceMotion ? "pulse" : undefined}
            aria-hidden="true"
          >
            {icon}
          </motion.span>
        </Elevated>
      ) : null}

      <div className="min-w-0 flex-1 pt-0.5">
        <p className="truncate text-sm font-medium leading-none text-foreground">
          {title}
        </p>
        {description ? (
          <p className="mt-1.5 line-clamp-2 text-xs leading-snug text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <Elevated offset={1} className="shrink-0 rounded-md">
        <button
          type="button"
          onClick={onDismiss}
          aria-label={`Dismiss ${title}`}
          // Hover tints the surface instead of replacing it, so the control
          // keeps its rung on the ladder.
          className="flex size-6 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-foreground/8 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2"
        >
          <X className="size-3" strokeWidth={2} aria-hidden="true" />
        </button>
      </Elevated>
    </Elevated>
  );
}

export type AchievementToastProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: string;
  icon?: ReactNode;
  /** ms on screen before it dismisses itself. `0` disables auto-dismiss. */
  duration?: number;
  position?: AchievementToastPosition;
  className?: string;
};

export function AchievementToast({
  open,
  onOpenChange,
  title,
  description,
  icon,
  duration = ACHIEVEMENT_TOAST_DURATION,
  position = "bottom-right",
  className,
}: AchievementToastProps) {
  const shouldReduceMotion = useReducedMotion();
  const { mounted, onAnimationComplete } = useExitAnimation(
    open,
    spring.playful,
  );
  const [landed, setLanded] = useState(false);

  const dismiss = useCallback(() => onOpenChange(false), [onOpenChange]);
  const pauseHandlers = useAutoDismiss(open, duration, dismiss);

  useEffect(() => {
    if (!open) setLanded(false);
  }, [open]);

  const handleAnimationComplete = useCallback(() => {
    if (open) {
      setLanded(true);
      return;
    }
    onAnimationComplete();
  }, [open, onAnimationComplete]);

  if (!mounted) {
    return null;
  }

  const variants = shouldReduceMotion
    ? reducedCardVariants
    : cardVariantsFor(position);

  return (
    <AchievementToastViewport position={position}>
      <motion.div
        variants={variants}
        initial="hidden"
        animate={open ? "visible" : "exit"}
        onAnimationComplete={handleAnimationComplete}
        className="pointer-events-auto w-full"
        {...pauseHandlers}
      >
        <AchievementCard
          title={title}
          description={description}
          icon={icon}
          landed={landed}
          onDismiss={dismiss}
          shouldReduceMotion={Boolean(shouldReduceMotion)}
          className={className}
        />
      </motion.div>
    </AchievementToastViewport>
  );
}

export type AchievementData = {
  id: string;
  title: string;
  description?: string;
  icon?: ReactNode;
};

export type AchievementToastGroupProps = {
  achievements: AchievementData[];
  onDismiss: (id: string) => void;
  /** ms on screen before each item dismisses itself. `0` disables auto-dismiss. */
  duration?: number;
  position?: AchievementToastPosition;
  className?: string;
};

/**
 * Several achievements landing at once — the run of green at the end of a
 * pipeline, not a running feed. Uses `stagger.playful`, the widest gap in the
 * scale, so each one reads as its own arrival instead of as a list appearing.
 *
 * Like Live Queue, the stagger orchestrates whatever is already in the array
 * on mount; items appended later enter individually, without inheriting a
 * queued-up delay.
 */
export function AchievementToastGroup({
  achievements,
  onDismiss,
  duration = ACHIEVEMENT_TOAST_DURATION,
  position = "bottom-right",
  className,
}: AchievementToastGroupProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <AchievementToastViewport position={position} className={className}>
      <motion.div
        data-slot="achievement-toast-group"
        variants={shouldReduceMotion ? undefined : staggerContainer("playful")}
        initial={shouldReduceMotion ? false : "hidden"}
        animate="visible"
        className="flex w-full flex-col gap-2"
      >
        <AnimatePresence mode="popLayout">
          {achievements.map((achievement) => (
            <AchievementToastGroupItem
              key={achievement.id}
              achievement={achievement}
              duration={duration}
              position={position}
              onDismiss={onDismiss}
            />
          ))}
        </AnimatePresence>
      </motion.div>
    </AchievementToastViewport>
  );
}

type AchievementToastGroupItemProps = {
  achievement: AchievementData;
  duration: number;
  position: AchievementToastPosition;
  onDismiss: (id: string) => void;
};

function AchievementToastGroupItem({
  achievement,
  duration,
  position,
  onDismiss,
}: AchievementToastGroupItemProps) {
  const shouldReduceMotion = useReducedMotion();
  const [landed, setLanded] = useState(false);

  const dismiss = useCallback(
    () => onDismiss(achievement.id),
    [onDismiss, achievement.id],
  );
  const pauseHandlers = useAutoDismiss(true, duration, dismiss);

  return (
    <motion.div
      layout={!shouldReduceMotion}
      variants={
        shouldReduceMotion ? reducedCardVariants : cardVariantsFor(position)
      }
      exit="exit"
      onAnimationComplete={() => setLanded(true)}
      className="pointer-events-auto w-full"
      {...pauseHandlers}
    >
      <AchievementCard
        title={achievement.title}
        description={achievement.description}
        icon={achievement.icon}
        landed={landed}
        onDismiss={dismiss}
        shouldReduceMotion={Boolean(shouldReduceMotion)}
      />
    </motion.div>
  );
}

"use client";

import { ContextMenu as ContextMenuPrimitive } from "@base-ui/react/context-menu";
import type { Menu as MenuPrimitive } from "@base-ui/react/menu";
import {
  motion,
  type Target,
  useReducedMotion,
  type Variants,
} from "framer-motion";
import { CheckIcon, ChevronRightIcon } from "lucide-react";
import {
  type ComponentProps,
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";

import { cn } from "@/lib/utils";
import {
  type Direction,
  directionalVariants,
  liftVariants,
  motionForOffset,
  useExitAnimation,
} from "@/lib/motion-tokens";
import { Elevated } from "@/components/matos-ui/elevated";

// Same rung as dropdown / popover / select. This one is on the elevation
// ladder rather than on `bg-popover`, which is what lets it accept an offset
// at all.
const CONTEXT_MENU_OFFSET = 2;

// The overlay path, not the celebration path: a right-click menu is an
// ordinary popup, so its timing comes from the offset mapping instead of a
// hand-picked tier.
const contextMenuMotion = motionForOffset(CONTEXT_MENU_OFFSET);

const MotionElevated = motion.create(Elevated);

type Side = MenuPrimitive.Popup.State["side"];

/**
 * A popup enters *from* the side it is anchored to, which is the opposite of
 * where collision detection put it: a menu that had to flip above the cursor
 * (side "top") grows upward out of the pointer, so it travels from "bottom".
 *
 * Same mapping as the `slide-in-from-*` classes on Dropdown Menu, just as a
 * value instead of a class. Logical sides are read left-to-right; in RTL the
 * horizontal pair swaps, which costs 6px of travel in the wrong axis and
 * nothing else.
 */
const directionForSide: Record<Side, Direction> = {
  top: "bottom",
  bottom: "top",
  left: "right",
  right: "left",
  "inline-start": "right",
  "inline-end": "left",
};

/**
 * The two halves of the entrance, composed.
 *
 * `liftVariants` carries the elevation half — the fade, the scale, and the
 * tier resolved from the offset. `directionalVariants` carries the origin
 * half — which axis the menu travels on to grow out of the pointer. The lift's
 * own travel is zeroed out (`y: 0`) so the direction owns that decision
 * outright instead of adding a stray 4px on the wrong axis.
 *
 * Both helpers land on the same tier here — `liftVariants(2)` resolves
 * `motionForOffset(2)` internally and `contextMenuMotion` is that same value —
 * so the merge can't produce two competing timings.
 */
function popupVariantsFor(side: Side): Variants {
  const lift = liftVariants(CONTEXT_MENU_OFFSET, { y: 0 });
  const origin = directionalVariants(directionForSide[side], contextMenuMotion);
  return {
    hidden: { ...(lift.hidden as Target), ...(origin.hidden as Target) },
    visible: { ...(lift.visible as Target), ...(origin.visible as Target) },
  };
}

const reducedPopupVariants: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { duration: 0 } },
};

type ContextMenuMotionContextValue = { open: boolean };

const ContextMenuMotionContext =
  createContext<ContextMenuMotionContextValue | null>(null);

function useContextMenuMotionContext() {
  return useContext(ContextMenuMotionContext) ?? { open: true };
}

export type ContextMenuProps = ContextMenuPrimitive.Root.Props;

/**
 * Right-click / long-press menu.
 *
 * Base UI's ContextMenu re-exports the same `Menu.*` parts Dropdown Menu is
 * built on — Item, Group, SubmenuRoot and the rest are literally the same
 * components. Roving focus, typeahead, Esc-to-close and submenu timing are
 * therefore shared implementation, not a second copy of them; only the
 * anchor (a virtual element at the pointer) and the surface differ.
 */
export function ContextMenu({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  ...props
}: ContextMenuProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const open = openProp ?? uncontrolledOpen;
  const contextValue = useMemo(() => ({ open }), [open]);

  const handleOpenChange = useCallback<
    NonNullable<ContextMenuPrimitive.Root.Props["onOpenChange"]>
  >(
    (nextOpen, eventDetails) => {
      if (openProp === undefined) {
        setUncontrolledOpen(nextOpen);
      }
      onOpenChange?.(nextOpen, eventDetails);
    },
    [onOpenChange, openProp],
  );

  return (
    <ContextMenuMotionContext.Provider value={contextValue}>
      <ContextMenuPrimitive.Root
        open={open}
        onOpenChange={handleOpenChange}
        {...props}
      />
    </ContextMenuMotionContext.Provider>
  );
}

export type ContextMenuTriggerProps = ContextMenuPrimitive.Trigger.Props;

export function ContextMenuTrigger(props: ContextMenuTriggerProps) {
  return (
    <ContextMenuPrimitive.Trigger data-slot="context-menu-trigger" {...props} />
  );
}

// React's DOM handlers for CSS animations and native drag collide with
// framer-motion's props of the same name. Base UI never passes them to the
// render prop, so dropping them here costs nothing.
type PopupRenderProps = Omit<
  ComponentProps<"div">,
  | "onAnimationStart"
  | "onAnimationEnd"
  | "onAnimationIteration"
  | "onDrag"
  | "onDragStart"
  | "onDragEnd"
>;

type ContextMenuSurfaceProps = PopupRenderProps & {
  side: Side;
  open: boolean;
  shouldReduceMotion: boolean;
  onAnimationComplete: () => void;
};

function ContextMenuSurface({
  side,
  open,
  shouldReduceMotion,
  onAnimationComplete,
  ...props
}: ContextMenuSurfaceProps) {
  const variants = useMemo<Variants>(
    () => (shouldReduceMotion ? reducedPopupVariants : popupVariantsFor(side)),
    [side, shouldReduceMotion],
  );

  return (
    <MotionElevated
      offset={CONTEXT_MENU_OFFSET}
      // Pinned shadow weight, per Elevated's own guidance for menus: the fill
      // still tracks whatever substrate the menu opened over, but a menu
      // opened inside a dialog shouldn't cast a heavier drop than one opened
      // on the page.
      shadowLevel={3}
      variants={variants}
      initial="hidden"
      animate={open ? "visible" : "hidden"}
      // `hidden` carries no transition of its own, so this default only takes
      // effect on the way out — and it has to be the tier's *exit* duration,
      // because useExitAnimation arms its force-unmount fallback off that same
      // number. An exit running the longer entrance duration would be cut off
      // by its own guard.
      transition={
        open ? undefined : { duration: contextMenuMotion.exit.duration }
      }
      onAnimationComplete={onAnimationComplete}
      {...props}
    />
  );
}

export type ContextMenuContentProps = Omit<
  MenuPrimitive.Popup.Props,
  "className" | "render"
> &
  Pick<
    MenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  > & {
    className?: string;
  };

export function ContextMenuContent({
  align = "start",
  alignOffset = 2,
  side = "bottom",
  sideOffset = 2,
  className,
  ...props
}: ContextMenuContentProps) {
  const shouldReduceMotion = useReducedMotion();
  const { open } = useContextMenuMotionContext();
  const { mounted, onAnimationComplete } = useExitAnimation(
    open,
    contextMenuMotion,
  );

  if (!mounted) {
    return null;
  }

  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Positioner
        className="isolate z-50 outline-none"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <ContextMenuPrimitive.Popup
          data-slot="context-menu-content"
          className={cn(
            // No border: the shadow-surface ring on <Elevated> draws the edge.
            "max-h-(--available-height) min-w-40 origin-(--transform-origin) overflow-x-hidden overflow-y-auto rounded-xl p-1 outline-none",
            className,
          )}
          render={(popupProps, state) => (
            <ContextMenuSurface
              {...popupProps}
              side={state.side}
              open={open}
              shouldReduceMotion={Boolean(shouldReduceMotion)}
              onAnimationComplete={onAnimationComplete}
            />
          )}
          {...props}
        />
      </ContextMenuPrimitive.Positioner>
    </ContextMenuPrimitive.Portal>
  );
}

// Highlight tints the surface rather than replacing it, so a highlighted item
