type AreaDotProps = {
  cx?: number;
  cy?: number;
  index?: number;
  active?: boolean;
  animated?: boolean;
  motionDelay?: number;
};

function AreaDot({
  cx,
  cy,
  index = 0,
  active = false,
  animated = true,
  motionDelay = 0,
}: AreaDotProps) {
  if (typeof cx !== "number" || typeof cy !== "number") {
    return null;
  }

  const ringRadius = active ? 10 : 5;

  return (
    <g
      data-slot={
        active ? "animated-area-chart-active-dot" : "animated-area-chart-dot"
      }
    >
      {active ? (
        <motion.circle
          cx={cx}
          cy={cy}
          r={ringRadius}
          className="text-chart-2"
          fill="currentColor"
          initial={animated ? { r: 4, opacity: 0 } : false}
          animate={{ r: ringRadius, opacity: 0.14 }}
          transition={{
            duration: 0.18,
            ease: "easeOut",
          }}
        />
      ) : null}
      <motion.circle
        cx={cx}
        cy={cy}
        r={active ? 4 : 3}
        className="text-card"
        fill="currentColor"
        stroke="var(--chart-2)"
        strokeWidth={active ? 2 : 1.5}
        initial={animated ? { r: 0, opacity: 0 } : false}
        animate={{ r: active ? 4 : 3, opacity: active ? 1 : 0.78 }}
        transition={{
          delay: motionDelay + index * 0.035,
          duration: 0.28,
          ease: [0.22, 1, 0.36, 1],
        }}
      />
    </g>
  );
}

function AreaCursor({
  points,
  height,
}: {
  points?: { x?: number }[];
  height?: number;
}) {
  const x = points?.[0]?.x;

  if (typeof x !== "number") {
    return null;
  }

  return (
    <motion.g
      data-slot="animated-area-chart-cursor"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
    >
      <line
        x1={x}
        x2={x}
        y1={8}
        y2={(height ?? 0) - 8}
        stroke="currentColor"
        strokeDasharray="4 6"
        strokeLinecap="round"
        className="text-muted-foreground/45"
      />
    </motion.g>
  );
}

type ChartTooltipProps = Partial<
  Omit<TooltipContentProps, "labelFormatter">
> & {
  valueFormatter?: (value: number) => ReactNode;
  labelFormatter?: (label: string | number) => ReactNode;
