                  <clipPath id={clipId} clipPathUnits="objectBoundingBox">
                    <motion.rect
                      x="0"
                      y="0"
                      height="1"
                      initial={resolvedAnimated ? { width: 0 } : false}
                      animate={{ width: 1 }}
                      transition={{
                        duration: motionDuration,
                        delay: motionDelay,
                        ease: [0.16, 1, 0.3, 1],
                      }}
                    />
                  </clipPath>
                </defs>
                <rect
                  x="0"
                  y="0"
                  width="100%"
                  height="100%"
                  fill={`url(#${patternId})`}
                  opacity={gradient ? 0.42 : 0}
                />
                {showGrid ? (
                  <CartesianGrid
                    vertical={false}
                    stroke="currentColor"
                    strokeDasharray="2 8"
