                {showTooltip ? (
                  <Tooltip
                    key={selectedIndex ?? "hover"}
                    active={selectedIndex === null ? undefined : true}
                    defaultIndex={selectedIndex ?? undefined}
                    cursor={<AreaCursor />}
                    content={
