                />
                <Line
                  dataKey={yKey}
                  type={curveType}
                  fill="none"
                  stroke="currentColor"
                  strokeWidth={strokeWidth}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  clipPath={`url(#${clipId})`}
