}

export function SignalFlowChart({
  className,
  size,
  data = defaultData,
  title = "Signal Flow",
  description = "Live channel throughput",
  metricLabel = "Throughput",
  valueFormatter,
  max = 100,
  height = 300,
  animated = true,
  showParticles = true,
  showTooltip = true,
  showValues = true,
  motionDuration = 0.7,
  motionDelay = 0,
  loading = false,
  emptyState,
  onActiveChange,
  ...props
}: SignalFlowChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");
  const safeMax = Math.max(1, max);

  const normalizedData = useMemo(
    () =>
      data
        .filter((item) => Number.isFinite(item.value))
        .map((item, index) => ({
          ...item,
          value: clamp(item.value, 0, safeMax),
          color: resolveTone(item.tone, index),
        })),
    [data, safeMax],
  );

  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, normalizedData.length);
  const activeItem =
    activeIndex === null ? null : (normalizedData[activeIndex] ?? null);

  useEffect(() => {
    if (activeItem && activeIndex !== null) {
      onActiveChange?.(activeItem, activeIndex);
    }
  }, [activeIndex, activeItem, onActiveChange]);

  if (loading) {
    return (
      <div
        data-slot="signal-flow-chart"
        className={twMerge(signalFlowChartVariants({ size }), className)}
        {...props}
      >
        <ChartSkeleton height={height} />
      </div>
    );
  }

  if (!normalizedData.length) {
    return (
      <div
        data-slot="signal-flow-chart"
        className={twMerge(signalFlowChartVariants({ size }), className)}
        {...props}
      >
        <ChartEmpty>{emptyState}</ChartEmpty>
      </div>
    );
  }

  const motionEnabled = animated && !shouldReduceMotion;
  const particlesEnabled = motionEnabled && showParticles;

  const viewBoxWidth = 720;
  const topPad = 34;
  const bottomPad = 30;
  const laneGap = 54;
  const itemCount = normalizedData.length;
  const viewBoxHeight = topPad + (itemCount - 1) * laneGap + bottomPad;

  const railX = 150;
  const cableEndX = 558;
  const valueX = 700;
  const cableLength = cableEndX - railX;

  const lanes = normalizedData.map((item, index) => {
    const baseY = topPad + index * laneGap;
    const fraction = clamp(item.value / safeMax, 0, 1);
    const bump = index % 2 === 0 ? 9 : -9;

    const p0x = railX;
    const p1x = railX + cableLength * 0.32;
    const p2x = railX + cableLength * 0.68;
    const p3x = cableEndX;
    const p0y = baseY;
    const p1y = baseY + bump;
    const p2y = baseY - bump;
    const p3y = baseY;

    const trackPath = `M ${p0x} ${p0y} C ${p1x} ${p1y}, ${p2x} ${p2y}, ${p3x} ${p3y}`;

    // Visible fill keeps a small floor so low channels still read as live.
    const fillFraction = Math.max(fraction, 0.08);
    const tipX = cubicPoint(fillFraction, p0x, p1x, p2x, p3x);
    const tipY = cubicPoint(fillFraction, p0y, p1y, p2y, p3y);

    const particleCount = 2 + Math.round(fraction * 3);
    const particleDuration = 0.72 - fraction * 0.18;

    return {
      ...item,
      index,
      baseY,
      fraction,
      fillFraction,
      trackPath,
      tipX,
      tipY,
      particleCount,
      particleDuration,
      formattedValue: getTextValue(item.value, valueFormatter),
    };
  });

  const railTop = lanes[0].baseY;
  const railBottom = lanes[lanes.length - 1].baseY;
  const active = activeIndex === null ? null : (lanes[activeIndex] ?? null);

  const tooltipWidth = 158;
  const tooltipHeight = 58;
  const tooltipX = active
    ? clamp(
        active.tipX - tooltipWidth / 2,
        10,
        viewBoxWidth - tooltipWidth - 10,
      )
    : 0;
  const tooltipY = active
    ? clamp(active.baseY - tooltipHeight - 18, 6, viewBoxHeight)
    : 0;
  const anchorX = active
    ? clamp(active.tipX - tooltipX, 16, tooltipWidth - 16)
    : tooltipWidth / 2;

  return (
    <div
      data-slot="signal-flow-chart"
      className={twMerge(signalFlowChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="signal-flow-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="signal-flow-chart-plot"
        className="overflow-hidden"
        style={{ height }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="size-full"
            role="img"
            aria-labelledby={`${id}-title ${id}-desc`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <desc id={`${id}-desc`}>
              Signal flow chart with {itemCount} channels. Use pointer, touch,
              or arrow keys to inspect each channel.
            </desc>
            <defs>
              <filter id={`${id}-tooltip-shadow`}>
                <feDropShadow
                  dx="0"
                  dy="2"
                  floodColor="var(--foreground)"
                  floodOpacity="0.12"
                  stdDeviation="3"
                />
              </filter>
            </defs>

            {/* Source bus rail */}
            <line
              x1={railX}
              x2={railX}
              y1={railTop - 16}
              y2={railBottom + 16}
              stroke="var(--border)"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <line
              x1={cableEndX}
              x2={cableEndX}
              y1={railTop - 10}
              y2={railBottom + 10}
              stroke="var(--border)"
              strokeDasharray="3 7"
              strokeLinecap="round"
              opacity="0.5"
            />

            {lanes.map((lane) => {
              const isActive = activeIndex === lane.index;
              const laneId = `${id}-lane-${lane.index}`;
              const dimmed = activeIndex !== null && !isActive;

              return (
                <motion.g
                  key={lane.label}
                  data-slot="signal-flow-chart-lane"
                  tabIndex={0}
                  role="button"
                  aria-label={`${lane.label}: ${lane.formattedValue}`}
                  {...getItemProps(lane.index)}
                  animate={{ opacity: dimmed ? 0.58 : 1 }}
                  transition={{ duration: 0.3, ease: "easeOut" }}
                  style={{ color: lane.color }}
                  className="cursor-pointer outline-none focus-visible:[&_[data-fill]]:stroke-ring focus-visible:[&_[data-fill]]:stroke-[7]"
                >
                  {/* Per-lane gradient keeps currentColor bound to the lane tone */}
                  <defs>
                    <linearGradient
                      id={`${laneId}-fill`}
                      x1="0"
                      y1="0"
                      x2="1"
                      y2="0"
                    >
                      <stop
                        offset="0%"
                        stopColor="currentColor"
                        stopOpacity="0.18"
                      />
                      <stop
                        offset="55%"
                        stopColor="currentColor"
                        stopOpacity="0.7"
                      />
                      <stop
                        offset="100%"
                        stopColor="currentColor"
                        stopOpacity="1"
                      />
                    </linearGradient>
                  </defs>

                  {/* Hit area */}
                  <rect
                    x={railX - 14}
                    y={lane.baseY - laneGap / 2 + 4}
                    width={valueX - railX + 24}
                    height={laneGap - 8}
                    fill="transparent"
                  />

                  {/* Track */}
                  <path
                    id={`${laneId}-track`}
                    d={lane.trackPath}
                    fill="none"
                    stroke="var(--border)"
                    strokeWidth="6"
                    strokeLinecap="round"
                    opacity="0.55"
                  />
                  <path
                    d={lane.trackPath}
                    fill="none"
                    stroke="var(--muted)"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeDasharray="1 9"
                    opacity="0.6"
                  />

                  {/* Animated fill up to throughput */}
                  <motion.path
                    data-fill=""
                    d={lane.trackPath}
                    fill="none"
                    stroke={`url(#${laneId}-fill)`}
                    strokeWidth={isActive ? 6 : 5}
                    strokeLinecap="round"
                    initial={
                      motionEnabled ? { pathLength: 0, opacity: 0 } : false
                    }
                    animate={{
                      pathLength: lane.fillFraction,
                      opacity: 1,
                    }}
                    transition={{
                      pathLength: {
                        duration: motionDuration,
                        ease: [0.16, 1, 0.3, 1],
                        delay: motionDelay + lane.index * 0.08,
                      },
                      opacity: { duration: 0.3, delay: motionDelay },
                      strokeWidth: { duration: 0.25 },
                    }}
                  />

                  {/* Flowing particles */}
                  {particlesEnabled
                    ? Array.from({ length: lane.particleCount }).map(
                        (_, particleIndex) => {
                          const spacing =
                            (lane.particleDuration / lane.particleCount) *
                            particleIndex;

                          return (
                            <circle
                              // biome-ignore lint/suspicious/noArrayIndexKey: particle slots are stable per lane
                              key={particleIndex}
                              r={isActive ? 3 : 2.4}
                              fill="currentColor"
                              opacity={isActive ? 0.95 : 0.7}
                            >
                              <animateMotion
                                dur={`${lane.particleDuration}s`}
                                begin={`${(motionDelay + spacing).toFixed(2)}s`}
                                repeatCount="1"
                                keyPoints={`0;${lane.fillFraction.toFixed(3)}`}
                                keyTimes="0;1"
                                calcMode="linear"
                              >
                                <mpath
                                  href={`#${laneId}-track`}
                                  xlinkHref={`#${laneId}-track`}
                                />
                              </animateMotion>
                              <animate
                                attributeName="opacity"
                                values={
                                  isActive ? "0;0.95;0.95;0" : "0;0.7;0.7;0"
                                }
                                keyTimes="0;0.12;0.85;1"
                                dur={`${lane.particleDuration}s`}
                                begin={`${(motionDelay + spacing).toFixed(2)}s`}
                                repeatCount="1"
                              />
                            </circle>
                          );
                        },
                      )
                    : null}

                  {/* Source node on the rail */}
                  <circle
                    cx={railX}
                    cy={lane.baseY}
                    r="4.5"
                    fill="var(--card)"
                    stroke="currentColor"
                    strokeWidth="2.5"
                  />

                  {/* Sink node at the fill tip */}
                  <motion.g
                    initial={motionEnabled ? { scale: 0, opacity: 0 } : false}
                    animate={{ scale: 1, opacity: 1 }}
                    transition={{
                      delay:
                        motionDelay + motionDuration * 0.7 + lane.index * 0.08,
                      duration: 0.3,
                      ease: [0.16, 1, 0.3, 1],
                    }}
                    style={{ transformOrigin: `${lane.tipX}px ${lane.tipY}px` }}
                  >
                    <motion.circle
                      cx={lane.tipX}
                      cy={lane.tipY}
                      fill="currentColor"
                      animate={{
                        r: isActive ? 8 : 5,
                        opacity: isActive ? 0.14 : 0,
                      }}
                      transition={{ duration: 0.18, ease: "easeOut" }}
                    />
                    <circle
                      cx={lane.tipX}
                      cy={lane.tipY}
                      r="4"
                      fill="currentColor"
                    />
                    <circle
                      cx={lane.tipX}
                      cy={lane.tipY}
                      r="1.6"
                      fill="var(--card)"
                    />
                  </motion.g>

                  {/* Channel label */}
                  <text
                    x={railX - 16}
                    y={lane.baseY + 4}
                    textAnchor="end"
                    fill={
                      isActive ? "var(--foreground)" : "var(--muted-foreground)"
                    }
                    className="text-[13px] font-medium"
                  >
                    {lane.label}
                  </text>

                  {/* Value readout */}
                  {showValues ? (
                    <motion.text
                      x={valueX}
                      y={lane.baseY + 4}
                      textAnchor="end"
                      fill={
                        isActive
                          ? "var(--foreground)"
                          : "var(--muted-foreground)"
                      }
                      className="text-[13px] font-semibold tabular-nums"
                      initial={
                        motionEnabled ? { opacity: 0, x: valueX + 8 } : false
                      }
                      animate={{ opacity: isActive ? 1 : 0.85, x: valueX }}
                      transition={{
                        delay: motionDelay + 0.2 + lane.index * 0.07,
                        duration: 0.3,
                      }}
                    >
                      {lane.formattedValue}
                    </motion.text>
                  ) : null}
                </motion.g>
              );
            })}

            <AnimatePresence>
              {showTooltip && active ? (
                <motion.g
                  data-slot="signal-flow-chart-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? {
                          opacity: 0,
                          x: tooltipX,
                          y: tooltipY + 8,
                          scale: 0.98,
                        }
                      : false
                  }
                  animate={{ opacity: 1, x: tooltipX, y: tooltipY, scale: 1 }}
                  exit={{
                    opacity: 0,
                    x: tooltipX,
                    y: tooltipY + 6,
                    scale: 0.98,
                  }}
                  transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
                >
                  <rect
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="14"
                    fill="var(--popover)"
                    stroke="var(--border)"
                    filter={`url(#${id}-tooltip-shadow)`}
                  />
                  <path
                    d={`M ${anchorX - 7} ${tooltipHeight - 1} L ${anchorX} ${
                      tooltipHeight + 8
                    } L ${anchorX + 7} ${tooltipHeight - 1} Z`}
                    fill="var(--popover)"
                    stroke="var(--border)"
                    strokeLinejoin="round"
                  />
                  <text
                    x="15"
                    y="23"
                    fill="var(--popover-foreground)"
                    className="text-[13px] font-semibold"
                  >
                    {active.label}
                  </text>
                  <circle cx="19" cy="43" r="4.5" fill={active.color} />
                  <text
                    x="32"
                    y="47"
                    fill="var(--muted-foreground)"
                    className="text-[12px] font-medium"
                  >
                    {active.hint ?? metricLabel}
                  </text>
                  <text
                    x={tooltipWidth - 15}
                    y="47"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[13px] font-semibold tabular-nums"
                  >
                    {active.formattedValue}
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  type ComponentProps,
  type ReactNode,
  useEffect,
  useId,
  useMemo,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { useChartInteraction } from "./chart-interaction";

export const activityHeatmapChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[460px]",
      md: "max-w-[680px]",
      lg: "max-w-[840px]",
      full: "max-w-full",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type ActivityHeatmapDatum = {
  value: number;
  label?: string;
};

export type ActivityHeatmapChartProps = ComponentProps<"div"> &
  VariantProps<typeof activityHeatmapChartVariants> & {
    data?: ActivityHeatmapDatum[];
    title?: ReactNode;
    description?: ReactNode;
    monthLabels?: string[];
    dayLabels?: string[];
    tone?: string;
    max?: number;
    weeks?: number;
    valueFormatter?: (value: number) => ReactNode;
    animated?: boolean;
    showTooltip?: boolean;
    showLegend?: boolean;
    motionDelay?: number;
    loading?: boolean;
    emptyState?: ReactNode;
    onActiveChange?: (item: ActivityHeatmapDatum, index: number) => void;
  };

const DAYS = 7;

// Deterministic default pattern so SSR and client render identically.
function buildDefaultData(weeks: number): ActivityHeatmapDatum[] {
  const total = weeks * DAYS;
  return Array.from({ length: total }, (_, index) => {
    const wave = Math.sin(index * 0.7) + Math.cos(index * 0.27);
    const ramp = index / total;
    const raw = (wave + 1.6) * 2.1 * (0.45 + ramp);
    const value = Math.max(0, Math.round(raw)) % 11;
    return { value };
  });
}

const defaultMonthLabels = ["Jan", "Feb", "Mar", "Apr"];
const defaultDayLabels = ["", "Mon", "", "Wed", "", "Fri", ""];

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

function resolveTone(tone: string) {
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(") ||
    tone === "currentColor"
  ) {
    return tone;
  }

  return `var(--${tone})`;
}

function ChartSkeleton({ weeks }: { weeks: number }) {
  return (
    <div
      data-slot="activity-heatmap-chart-skeleton"
      className="overflow-hidden rounded-xl border border-border/60 bg-card p-5"
    >
      <div className="flex gap-1.5">
        {Array.from({ length: weeks }).map((_, column) => (
          <div
            // biome-ignore lint/suspicious/noArrayIndexKey: fixed skeleton grid
            key={column}
            className="flex flex-col gap-1.5"
          >
            {Array.from({ length: DAYS }).map((__, row) => (
              <span
                // biome-ignore lint/suspicious/noArrayIndexKey: fixed skeleton grid
                key={row}
                className="size-3 animate-pulse rounded-[3px] bg-muted"
              />
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

function ChartEmpty({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="activity-heatmap-chart-empty"
      className="grid min-h-56 place-items-center rounded-xl border border-dashed border-border/70 bg-card px-6 text-center"
    >
      <div className="max-w-60">
        <div className="mx-auto mb-4 grid w-fit grid-cols-4 gap-1 rounded-xl border border-border bg-muted p-2.5">
          {Array.from({ length: 12 }).map((_, cell) => (
            <span
              // biome-ignore lint/suspicious/noArrayIndexKey: fixed empty grid
              key={cell}
              className="size-2 rounded-[2px] bg-muted-foreground/30"
            />
          ))}
        </div>
        <p className="text-sm font-medium text-foreground">No activity yet</p>
        <p className="mt-1 text-xs leading-5 text-muted-foreground">
          {children ?? "Provide activity values to render this heatmap."}
        </p>
      </div>
    </div>
  );
}

export function ActivityHeatmapChart({
  className,
  size,
  data,
  title = "Activity Heatmap",
  description = "Daily engagement over the last weeks",
  monthLabels = defaultMonthLabels,
  dayLabels = defaultDayLabels,
  tone = "chart-2",
  max,
  weeks = 18,
  valueFormatter,
  animated = true,
  showTooltip = true,
  showLegend = true,
  motionDelay = 0,
  loading = false,
  emptyState,
  onActiveChange,
  ...props
}: ActivityHeatmapChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");

  const resolvedData = useMemo(
    () => data ?? buildDefaultData(weeks),
    [data, weeks],
  );
  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, resolvedData.length);

  const columns = Math.max(1, Math.ceil(resolvedData.length / DAYS));
  const safeMax = useMemo(() => {
    if (max && max > 0) {
      return max;
    }
    return Math.max(1, ...resolvedData.map((item) => item.value));
  }, [max, resolvedData]);

  const total = useMemo(
    () => resolvedData.reduce((sum, item) => sum + Math.max(0, item.value), 0),
    [resolvedData],
  );

  const activeItem = activeIndex === null ? null : resolvedData[activeIndex];

  useEffect(() => {
    if (activeItem && activeIndex !== null) {
      onActiveChange?.(activeItem, activeIndex);
    }
  }, [activeIndex, activeItem, onActiveChange]);

  const motionEnabled = animated && !shouldReduceMotion;
  const accent = resolveTone(tone);

  if (loading) {
    return (
      <div
        data-slot="activity-heatmap-chart"
        className={twMerge(activityHeatmapChartVariants({ size }), className)}
        {...props}
      >
        <ChartSkeleton weeks={columns} />
      </div>
    );
  }

  if (!resolvedData.length) {
    return (
      <div
        data-slot="activity-heatmap-chart"
        className={twMerge(activityHeatmapChartVariants({ size }), className)}
        {...props}
      >
        <ChartEmpty>{emptyState}</ChartEmpty>
      </div>
    );
  }

  const cell = 15;
  const gap = 4;
  const pitch = cell + gap;
  const leftGutter = 30;
  const topGutter = 18;
  const gridWidth = columns * pitch - gap;
  const gridHeight = DAYS * pitch - gap;
  const viewBoxWidth = leftGutter + gridWidth + 4;
  const viewBoxHeight = topGutter + gridHeight + 6;

  // Levels: 0 = empty track, 1..4 increasing intensity.
  const levelOpacity = [0.16, 0.34, 0.58, 0.82, 1];

  function levelFor(value: number) {
    if (value <= 0) {
      return 0;
    }
    return clamp(Math.ceil((value / safeMax) * 4), 1, 4);
  }

  const cells = resolvedData.map((item, index) => {
    const column = Math.floor(index / DAYS);
    const row = index % DAYS;
    const x = leftGutter + column * pitch;
    const y = topGutter + row * pitch;
    const level = levelFor(item.value);
    return { ...item, index, column, row, x, y, level };
  });

  const active =
    activeIndex === null ? null : cells.find((c) => c.index === activeIndex);

  const tooltipWidth = 150;
  const tooltipHeight = 46;
  const tooltipX = active
    ? clamp(
        active.x + cell / 2 - tooltipWidth / 2,
        2,
        viewBoxWidth - tooltipWidth - 2,
      )
    : 0;
  const tooltipY = active ? clamp(active.y - tooltipHeight - 8, 2, 9999) : 0;

  return (
    <div
      data-slot="activity-heatmap-chart"
      className={twMerge(activityHeatmapChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="activity-heatmap-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="activity-heatmap-chart-plot"
        className="overflow-hidden"
        style={{ color: accent }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="w-full"
            role="img"
            aria-labelledby={`${id}-title ${id}-desc`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <desc id={`${id}-desc`}>
              Activity heatmap with {cells.length} days across {columns} weeks.
              Total activity: {total}.
            </desc>

            {monthLabels.map((label, monthIndex) => {
              const column = Math.round(
                (monthIndex * columns) / monthLabels.length,
              );
              return (
                <text
                  key={`${label}-${column}`}
                  x={leftGutter + column * pitch}
                  y={topGutter - 6}
                  className="fill-muted-foreground text-[9px] font-medium"
                >
                  {label}
                </text>
              );
            })}

            {dayLabels.map((label, row) =>
              label ? (
                <text
                  key={label}
                  x={leftGutter - 8}
                  y={topGutter + row * pitch + cell - 3}
                  textAnchor="end"
                  className="fill-muted-foreground text-[9px] font-medium"
                >
                  {label}
                </text>
              ) : null,
            )}

            {cells.map((c) => {
              const isActive = activeIndex === c.index;
              const isEmpty = c.level === 0;

              return (
                <motion.rect
                  key={c.index}
                  x={c.x}
                  y={c.y}
                  width={cell}
                  height={cell}
                  rx="3.5"
                  fill={isEmpty ? "var(--muted)" : "currentColor"}
                  fillOpacity={isEmpty ? 0.5 : levelOpacity[c.level]}
                  stroke={isActive ? "currentColor" : "var(--border)"}
                  strokeOpacity={isActive ? 0.9 : 0.4}
                  strokeWidth={isActive ? 1.5 : 0.75}
                  tabIndex={0}
                  role="button"
                  aria-label={`${c.label ?? `Day ${c.index + 1}`}: ${c.value}`}
                  {...getItemProps(c.index)}
                  initial={motionEnabled ? { opacity: 0, scale: 0.3 } : false}
                  animate={{
                    opacity: 1,
                    scale: isActive ? 1.16 : 1,
                  }}
                  transition={{
                    opacity: {
                      delay: motionEnabled
                        ? motionDelay + (c.column + c.row) * 0.018
                        : 0,
                      duration: 0.32,
                      ease: [0.16, 1, 0.3, 1],
                    },
                    scale: isActive
                      ? { type: "spring", stiffness: 320, damping: 18 }
                      : {
                          delay: motionEnabled
                            ? motionDelay + (c.column + c.row) * 0.018
                            : 0,
                          duration: 0.32,
                          ease: [0.16, 1, 0.3, 1],
                        },
                  }}
                  style={{
                    transformOrigin: `${c.x + cell / 2}px ${c.y + cell / 2}px`,
                    cursor: "pointer",
                  }}
                  className="outline-none"
                />
              );
            })}

            <AnimatePresence>
              {showTooltip && active ? (
                <motion.g
                  data-slot="activity-heatmap-chart-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? { opacity: 0, y: tooltipY + 6, scale: 0.96 }
                      : false
                  }
                  animate={{ opacity: 1, y: tooltipY, scale: 1 }}
                  exit={{ opacity: 0, y: tooltipY + 4, scale: 0.96 }}
                  transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
                  style={{ transformOrigin: `${tooltipX}px ${tooltipY}px` }}
                >
                  <rect
                    x={tooltipX}
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="10"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <text
                    x={tooltipX + 12}
                    y={18}
                    fill="var(--popover-foreground)"
                    className="text-[11px] font-semibold tabular-nums"
                  >
                    {getTextValue(active.value, valueFormatter)}
                  </text>
                  <text
                    x={tooltipX + 12}
                    y={34}
                    fill="var(--muted-foreground)"
                    className="text-[10px] font-medium"
                  >
                    {active.label ?? `Week ${active.column + 1}`}
                  </text>
                  <rect
                    x={tooltipX + tooltipWidth - 26}
                    y={tooltipHeight / 2 - 7}
                    width="14"
                    height="14"
                    rx="3"
                    fill="currentColor"
                    fillOpacity={levelOpacity[active.level]}
                  />
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>

      {showLegend ? (
        <div
          data-slot="activity-heatmap-chart-legend"
          className="mt-2 flex items-center justify-between gap-3 text-[11px] text-muted-foreground"
        >
          <span>
            {columns} weeks {"·"} {DAYS * columns} days
          </span>
          <span
            className="inline-flex items-center gap-1.5"
            style={{ color: accent }}
          >
            Less
            {levelOpacity.map((opacity, level) => (
              <span
                // biome-ignore lint/suspicious/noArrayIndexKey: fixed legend scale
                key={level}
                className="size-2.5 rounded-[2px]"
                style={{
                  backgroundColor:
                    level === 0 ? "var(--muted)" : "currentColor",
                  opacity: level === 0 ? 0.5 : opacity,
                }}
              />
            ))}
            More
          </span>
        </div>
      ) : null}
    </div>
  );
}

function getTextValue(value: number, formatter?: (value: number) => ReactNode) {
  const formatted = formatter?.(value) ?? value;
  if (typeof formatted === "number" || typeof formatted === "string") {
    return String(formatted);
  }
  return String(value);
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  type ComponentProps,
  type ReactNode,
  useEffect,
  useId,
  useMemo,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { useChartInteraction } from "./chart-interaction";

export const candlestickChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[420px]",
      md: "max-w-[620px]",
      lg: "max-w-[820px]",
      full: "max-w-full",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type CandlestickDatum = {
  label: string;
  open: number;
  high: number;
  low: number;
  close: number;
};

export type CandlestickChartProps = ComponentProps<"div"> &
  VariantProps<typeof candlestickChartVariants> & {
    data?: CandlestickDatum[];
    title?: ReactNode;
    description?: ReactNode;
    valueFormatter?: (value: number) => ReactNode;
    height?: number;
    animated?: boolean;
    showGrid?: boolean;
    showTooltip?: boolean;
    showLegend?: boolean;
    upTone?: string;
    downTone?: string;
    motionDuration?: number;
    motionDelay?: number;
    loading?: boolean;
    emptyState?: ReactNode;
    onActiveChange?: (item: CandlestickDatum, index: number) => void;
  };

const defaultData: CandlestickDatum[] = [
  { label: "01", open: 30, high: 38, low: 28, close: 36 },
  { label: "02", open: 36, high: 40, low: 33, close: 34 },
  { label: "03", open: 34, high: 37, low: 30, close: 32 },
  { label: "04", open: 32, high: 35, low: 29, close: 34 },
  { label: "05", open: 34, high: 44, low: 33, close: 42 },
  { label: "06", open: 42, high: 46, low: 39, close: 40 },
  { label: "07", open: 40, high: 43, low: 36, close: 43 },
  { label: "08", open: 43, high: 52, low: 42, close: 50 },
  { label: "09", open: 50, high: 54, low: 46, close: 47 },
  { label: "10", open: 47, high: 50, low: 44, close: 49 },
  { label: "11", open: 49, high: 58, low: 48, close: 57 },
  { label: "12", open: 57, high: 61, low: 53, close: 55 },
  { label: "13", open: 55, high: 60, low: 52, close: 59 },
  { label: "14", open: 59, high: 68, low: 58, close: 66 },
  { label: "15", open: 66, high: 70, low: 62, close: 64 },
  { label: "16", open: 64, high: 72, low: 61, close: 71 },
];

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

function formatNumber(value: number) {
  return value.toLocaleString("en-US", { maximumFractionDigits: 1 });
}

function resolveTone(tone: string) {
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(") ||
    tone === "currentColor"
  ) {
    return tone;
  }
  return `var(--${tone})`;
}

function ChartSkeleton({ height }: { height: number }) {
  const bars = [40, 64, 52, 70, 48, 80, 58, 72];
  return (
    <div
      data-slot="candlestick-chart-skeleton"
      className="overflow-hidden rounded-xl border border-border/60 bg-card p-5"
      style={{ height }}
    >
      <div className="flex h-full items-center justify-between gap-3">
        {bars.map((value, index) => (
          <span
            // biome-ignore lint/suspicious/noArrayIndexKey: fixed skeleton bars
            key={index}
            className="w-2.5 animate-pulse rounded-full bg-muted"
            style={{ height: `${value}%` }}
          />
        ))}
      </div>
    </div>
  );
}

function ChartEmpty({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="candlestick-chart-empty"
      className="grid min-h-48 place-items-center rounded-xl border border-dashed border-border/70 bg-card px-6 text-center"
    >
      <div className="max-w-56">
        <div className="mx-auto mb-3 flex h-10 w-20 items-end justify-center gap-1.5">
          <span className="h-6 w-1.5 rounded-full bg-muted-foreground/40" />
          <span className="h-9 w-1.5 rounded-full bg-muted-foreground/50" />
          <span className="h-5 w-1.5 rounded-full bg-muted-foreground/30" />
        </div>
        <p className="text-sm font-medium text-foreground">No price data</p>
        <p className="mt-1 text-xs leading-5 text-muted-foreground">
          {children ?? "Provide OHLC data to render this candlestick chart."}
        </p>
      </div>
    </div>
  );
}

export function CandlestickChart({
  className,
  size,
  data = defaultData,
  title = "Sales Report",
  description = "Open-high-low-close price action",
  valueFormatter,
  height = 280,
  animated = true,
  showGrid = true,
  showTooltip = true,
  showLegend = true,
  upTone = "chart-2",
  downTone = "destructive",
  motionDuration = 0.5,
  motionDelay = 0,
  loading = false,
  emptyState,
  onActiveChange,
  ...props
}: CandlestickChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");
  const motionEnabled = animated && !shouldReduceMotion;
  const upColor = resolveTone(upTone);
  const downColor = resolveTone(downTone);

  const normalized = useMemo(
    () => data.filter((item) => Number.isFinite(item.close)),
    [data],
  );

  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, normalized.length);
  const activeItem = activeIndex === null ? null : normalized[activeIndex];

  useEffect(() => {
    if (activeItem && activeIndex !== null) {
      onActiveChange?.(activeItem, activeIndex);
    }
  }, [activeIndex, activeItem, onActiveChange]);

  function format(value: number) {
    const formatted = valueFormatter?.(value);
    return formatted === undefined ? formatNumber(value) : formatted;
  }

  if (loading) {
    return (
      <div
        data-slot="candlestick-chart"
        className={twMerge(candlestickChartVariants({ size }), className)}
        {...props}
      >
        <ChartSkeleton height={height} />
      </div>
    );
  }

  if (!normalized.length) {
    return (
      <div
        data-slot="candlestick-chart"
        className={twMerge(candlestickChartVariants({ size }), className)}
        {...props}
      >
        <ChartEmpty>{emptyState}</ChartEmpty>
      </div>
    );
  }

  const viewBoxWidth = 720;
  const viewBoxHeight = 300;
  const plotTop = 16;
  const plotBottom = 258;
  const plotLeft = 14;
  const plotRight = 706;
  const plotHeight = plotBottom - plotTop;
  const plotWidth = plotRight - plotLeft;
  const labelY = 282;

  const highest = Math.max(...normalized.map((item) => item.high));
  const lowest = Math.min(...normalized.map((item) => item.low));
  const pad = Math.max(1, (highest - lowest) * 0.08);
  const domainMax = highest + pad;
  const domainMin = lowest - pad;

  function yFor(value: number) {
    return (
      plotTop + ((domainMax - value) / (domainMax - domainMin)) * plotHeight
    );
  }

  const slot = plotWidth / normalized.length;
  const bodyWidth = Math.min(18, Math.max(4, slot * 0.58));

  const candles = normalized.map((item, index) => {
    const cx = plotLeft + slot * (index + 0.5);
    const up = item.close >= item.open;
    const bodyTop = yFor(Math.max(item.open, item.close));
    const bodyBottom = yFor(Math.min(item.open, item.close));
    return {
      ...item,
      index,
      cx,
      up,
      color: up ? upColor : downColor,
      yHigh: yFor(item.high),
      yLow: yFor(item.low),
      bodyTop,
      bodyHeight: Math.max(2, bodyBottom - bodyTop),
    };
  });

  const active = activeIndex === null ? null : candles[activeIndex];
  const tooltipWidth = 150;
  const tooltipHeight = 78;
  const tooltipX = active
    ? clamp(active.cx - tooltipWidth / 2, 4, viewBoxWidth - tooltipWidth - 4)
    : 0;
  const tooltipY = active
    ? clamp(active.yHigh - tooltipHeight - 12, 6, 9999)
    : 0;

  return (
    <div
      data-slot="candlestick-chart"
      className={twMerge(candlestickChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="candlestick-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 truncate text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="candlestick-chart-plot"
        className="overflow-hidden"
        style={{ height }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="size-full"
            role="img"
            aria-labelledby={`${id}-title ${id}-desc`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <desc id={`${id}-desc`}>
              Candlestick chart with {candles.length} periods. Latest close:{" "}
              {format(normalized[normalized.length - 1].close)}.
            </desc>

            {showGrid
              ? [0.25, 0.5, 0.75].map((step) => {
                  const y = plotTop + plotHeight * step;
                  return (
                    <line
                      key={step}
                      x1={plotLeft}
                      x2={plotRight}
                      y1={y}
                      y2={y}
                      stroke="var(--border)"
                      strokeDasharray="3 9"
                      opacity="0.5"
                    />
                  );
                })
              : null}

            {candles.map((candle) => {
              const isActive = activeIndex === candle.index;
              const dim = activeIndex !== null && !isActive;
              return (
                <motion.g
                  key={candle.label}
                  data-slot="candlestick-chart-candle"
                  tabIndex={0}
                  role="button"
                  aria-label={`${candle.label}: open ${format(candle.open)}, high ${format(candle.high)}, low ${format(candle.low)}, close ${format(candle.close)}`}
                  {...getItemProps(candle.index)}
                  animate={{ opacity: dim ? 0.4 : 1 }}
                  transition={{ duration: 0.25, ease: "easeOut" }}
                  style={{ color: candle.color, cursor: "pointer" }}
                  className="outline-none"
                >
                  <motion.line
                    x1={candle.cx}
                    x2={candle.cx}
                    y1={candle.yHigh}
                    y2={candle.yLow}
                    stroke="currentColor"
                    strokeWidth="1.5"
                    strokeLinecap="round"
                    initial={motionEnabled ? { scaleY: 0, opacity: 0 } : false}
                    animate={{ scaleY: 1, opacity: 1 }}
                    transition={{
                      duration: motionDuration,
                      delay: motionDelay + candle.index * 0.035,
                      ease: [0.16, 1, 0.3, 1],
                    }}
                    style={{
                      transformOrigin: `${candle.cx}px ${
                        (candle.yHigh + candle.yLow) / 2
                      }px`,
                    }}
                  />
                  <motion.rect
                    x={candle.cx - bodyWidth / 2}
                    y={candle.bodyTop}
                    width={bodyWidth}
                    height={candle.bodyHeight}
                    rx="2.5"
                    fill="currentColor"
                    initial={motionEnabled ? { scaleY: 0, opacity: 0 } : false}
                    animate={{ scaleY: 1, opacity: 1 }}
                    transition={{
                      duration: motionDuration,
                      delay: motionDelay + 0.06 + candle.index * 0.035,
                      ease: [0.16, 1, 0.3, 1],
                    }}
                    style={{
                      transformOrigin: `${candle.cx}px ${
                        candle.bodyTop + candle.bodyHeight / 2
                      }px`,
                    }}
                  />
                </motion.g>
              );
            })}

            {normalized.map((item, index) =>
              index % 2 === 0 ? (
                <text
                  key={item.label}
                  x={plotLeft + slot * (index + 0.5)}
                  y={labelY}
                  textAnchor="middle"
                  className="fill-muted-foreground text-[10px] font-medium"
                >
                  {item.label}
                </text>
              ) : null,
            )}

            <AnimatePresence>
              {showTooltip && active ? (
                <motion.g
                  data-slot="candlestick-chart-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? { opacity: 0, y: tooltipY + 6, scale: 0.97 }
                      : false
                  }
                  animate={{ opacity: 1, y: tooltipY, scale: 1 }}
                  exit={{ opacity: 0, y: tooltipY + 4, scale: 0.97 }}
                  transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
                  style={{ transformOrigin: `${tooltipX}px ${tooltipY}px` }}
                >
                  <rect
                    x={tooltipX}
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="12"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <text
                    x={tooltipX + 14}
                    y={22}
                    className="fill-popover-foreground text-[12px] font-semibold"
                  >
                    {active.label}
                  </text>
                  <circle
                    cx={tooltipX + tooltipWidth - 16}
                    cy={18}
                    r="4.5"
                    fill={active.color}
                  />
                  {(
                    [
                      ["O", active.open],
                      ["H", active.high],
                      ["L", active.low],
                      ["C", active.close],
                    ] as const
                  ).map(([key, value], row) => {
                    const col = row % 2;
                    const line = Math.floor(row / 2);
                    const tx = tooltipX + 14 + col * 70;
                    const ty = 42 + line * 20;
                    return (
                      <text key={key} x={tx} y={ty} className="text-[11px]">
                        <tspan className="fill-muted-foreground font-medium">
                          {key}{" "}
                        </tspan>
                        <tspan className="fill-popover-foreground font-semibold">
                          {format(value)}
                        </tspan>
                      </text>
                    );
                  })}
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>

      {showLegend ? (
        <div
          data-slot="candlestick-chart-legend"
          className="mt-2 flex items-center gap-4 text-[11px] text-muted-foreground"
        >
          <span className="inline-flex items-center gap-1.5">
            <span
              className="size-2.5 rounded-[3px]"
              style={{ backgroundColor: upColor }}
            />
            Bullish
          </span>
          <span className="inline-flex items-center gap-1.5">
            <span
              className="size-2.5 rounded-[3px]"
              style={{ backgroundColor: downColor }}
            />
            Bearish
          </span>
          {activeItem ? (
            <span className="ml-auto tabular-nums text-foreground">
              {activeItem.label} {"·"} {format(activeItem.close)}
            </span>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

