    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import {
  type ComponentProps,
  type ReactNode,
  useEffect,
  useId,
  useMemo,
} from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { useChartInteraction } from "./chart-interaction";

export const activityWaveformChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[420px]",
      md: "max-w-[560px]",
      lg: "max-w-[720px]",
      full: "max-w-full",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type WaveformBar = number | { value: number; label?: string };

export type WaveformSegment = {
  label: string;
  value: number;
  tone?: string;
};

export type ActivityWaveformChartProps = ComponentProps<"div"> &
  VariantProps<typeof activityWaveformChartVariants> & {
    data?: WaveformBar[];
    title?: ReactNode;
    value?: ReactNode;
    valueCaption?: ReactNode;
    description?: ReactNode;
    segments?: WaveformSegment[];
    startLabel?: ReactNode;
    endLabel?: ReactNode;
    tone?: string;
    valueFormatter?: (value: number) => ReactNode;
    height?: number;
    animated?: boolean;
    showTooltip?: boolean;
    motionDuration?: number;
    motionDelay?: number;
    loading?: boolean;
    emptyState?: ReactNode;
    onActiveChange?: (value: number, index: number) => void;
  };

const fallbackTones = ["var(--chart-2)", "var(--chart-4)", "var(--chart-3)"];

// Deterministic default waveform so SSR and client stay in sync.
function buildDefaultData(count: number): number[] {
  return Array.from({ length: count }, (_, index) => {
    const wave =
      Math.sin(index * 0.55) * 0.5 +
      Math.sin(index * 0.21 + 1.3) * 0.32 +
      Math.cos(index * 0.9) * 0.18;
    return Math.round((wave + 1.2) * 38);
  });
}

const defaultSegments: WaveformSegment[] = [
  { label: "Credit card", value: 83, tone: "chart-2" },
  { label: "Cash", value: 17, tone: "chart-4" },
];

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

function resolveTone(tone: string | undefined, index: number) {
  if (!tone) {
    return fallbackTones[index % fallbackTones.length];
  }
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(") ||
    tone === "currentColor"
  ) {
    return tone;
  }
  return `var(--${tone})`;
}

function barValue(bar: WaveformBar) {
  return typeof bar === "number" ? bar : bar.value;
}

function barLabel(bar: WaveformBar, index: number) {
  return typeof bar === "number"
    ? `#${index + 1}`
    : (bar.label ?? `#${index + 1}`);
}

function ChartEmpty({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="activity-waveform-chart-empty"
      className="grid min-h-44 place-items-center rounded-xl border border-dashed border-border/70 bg-card px-6 text-center"
    >
      <div className="max-w-56">
        <div className="mx-auto mb-3 flex h-8 items-end justify-center gap-1">
          {[5, 8, 4, 7, 6].map((value, index) => (
            <span
              // biome-ignore lint/suspicious/noArrayIndexKey: fixed empty bars
              key={index}
              className="w-1 rounded-full bg-muted-foreground/40"
              style={{ height: value * 3 }}
            />
          ))}
        </div>
        <p className="text-sm font-medium text-foreground">No activity</p>
        <p className="mt-1 text-xs leading-5 text-muted-foreground">
          {children ?? "Provide a series of values to render this waveform."}
        </p>
      </div>
    </div>
  );
}

export function ActivityWaveformChart({
  className,
  size,
  data,
  title = "Sales activity",
  value = "−$3,245.00",
  valueCaption = "This week you spent",
  description,
  segments = defaultSegments,
  startLabel = "Mon",
  endLabel = "Sun",
  tone = "chart-2",
  valueFormatter,
  height = 150,
  animated = true,
  showTooltip = true,
  motionDuration = 0.5,
  motionDelay = 0,
  loading = false,
  emptyState,
  onActiveChange,
  ...props
}: ActivityWaveformChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");
  const motionEnabled = animated && !shouldReduceMotion;
  const accent = resolveTone(tone, 0);

  const bars = useMemo(() => data ?? buildDefaultData(56), [data]);

  const peakIndex = useMemo(() => {
    let best = 0;
    for (let index = 1; index < bars.length; index += 1) {
      if (barValue(bars[index]) > barValue(bars[best])) {
        best = index;
      }
    }
    return best;
  }, [bars]);
  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, bars.length);

  useEffect(() => {
    if (activeIndex !== null) {
      onActiveChange?.(barValue(bars[activeIndex]), activeIndex);
    }
  }, [activeIndex, bars, onActiveChange]);

  const resolvedSegments = useMemo(
    () =>
      segments.map((segment, index) => ({
        ...segment,
        color: resolveTone(segment.tone, index),
      })),
    [segments],
  );
  const segmentsTotal = resolvedSegments.reduce(
    (sum, segment) => sum + Math.max(0, segment.value),
    0,
  );

  function format(input: number) {
    const formatted = valueFormatter?.(input);
    return formatted === undefined ? String(input) : formatted;
  }

  if (loading) {
    return (
      <div
        data-slot="activity-waveform-chart"
        className={twMerge(activityWaveformChartVariants({ size }), className)}
        {...props}
      >
        <div
          className="overflow-hidden rounded-xl border border-border/60 bg-card p-4"
          style={{ height: height + 70 }}
        >
          <div className="h-5 w-28 animate-pulse rounded bg-muted" />
          <div className="mt-3 h-8 w-40 animate-pulse rounded-lg bg-muted" />
          <div className="mt-5 h-20 animate-pulse rounded-lg bg-muted" />
        </div>
      </div>
    );
  }

  if (!bars.length) {
    return (
      <div
        data-slot="activity-waveform-chart"
        className={twMerge(activityWaveformChartVariants({ size }), className)}
        {...props}
      >
        <ChartEmpty>{emptyState}</ChartEmpty>
      </div>
    );
  }

  const viewBoxWidth = 720;
  const viewBoxHeight = 200;
  const plotTop = 14;
  const baseline = 176;
  const plotLeft = 6;
  const plotRight = 714;
  const plotWidth = plotRight - plotLeft;
  const plotHeight = baseline - plotTop;
  const maxValue = Math.max(1, ...bars.map(barValue));
  const slot = plotWidth / bars.length;
  const barWidth = Math.max(2, slot * 0.55);

  const computed = bars.map((bar, index) => {
    const v = barValue(bar);
    const barHeight = Math.max(3, (v / maxValue) * plotHeight);
    return {
      value: v,
      label: barLabel(bar, index),
      index,
      x: plotLeft + slot * index + (slot - barWidth) / 2,
      y: baseline - barHeight,
      height: barHeight,
      centerX: plotLeft + slot * index + slot / 2,
    };
  });

  const active = activeIndex === null ? null : computed[activeIndex];
  const tooltipWidth = 92;
  const tooltipHeight = 30;
  const tooltipX = active
    ? clamp(
        active.centerX - tooltipWidth / 2,
        2,
        viewBoxWidth - tooltipWidth - 2,
      )
    : 0;
  const tooltipY = active ? clamp(active.y - tooltipHeight - 10, 2, 9999) : 0;

  return (
    <div
      data-slot="activity-waveform-chart"
      className={twMerge(activityWaveformChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="activity-waveform-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {valueCaption ? (
          <p className="mt-2 text-xs leading-5 text-muted-foreground">
            {valueCaption}
          </p>
        ) : null}
        {value ? (
          <p className="mt-0.5 text-3xl font-semibold leading-tight text-foreground tabular-nums">
            {value}
          </p>
        ) : null}
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="activity-waveform-chart-plot"
        className="overflow-hidden"
        style={{ height, color: accent }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="size-full"
            role="img"
            aria-labelledby={`${id}-title ${id}-desc`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <desc id={`${id}-desc`}>
              Activity waveform with {bars.length} samples. Peak value{" "}
              {format(computed[peakIndex].value)}.
            </desc>

            {computed.map((bar) => {
              const isActive = activeIndex === bar.index;
              return (
                <motion.rect
                  key={bar.index}
                  x={bar.x}
                  y={bar.y}
                  width={barWidth}
                  height={bar.height}
                  rx={Math.min(barWidth / 2, 3)}
                  fill="currentColor"
                  fillOpacity={isActive ? 1 : 0.85}
                  tabIndex={0}
                  role="button"
                  aria-label={`${bar.label}: ${format(bar.value)}`}
                  {...getItemProps(bar.index)}
                  initial={motionEnabled ? { scaleY: 0, opacity: 0 } : false}
                  animate={{ scaleY: 1, opacity: 1 }}
                  transition={{
                    duration: motionDuration,
                    delay: motionEnabled ? motionDelay + bar.index * 0.012 : 0,
                    ease: [0.16, 1, 0.3, 1],
                  }}
                  style={{
                    transformOrigin: `${bar.centerX}px ${baseline}px`,
                    cursor: "pointer",
                  }}
                  className="outline-none"
                />
              );
            })}

            <AnimatePresence>
              {showTooltip && active ? (
                <motion.g
                  data-slot="activity-waveform-chart-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? { opacity: 0, y: tooltipY + 4, scale: 0.96 }
                      : false
                  }
                  animate={{ opacity: 1, y: tooltipY, scale: 1 }}
                  exit={{ opacity: 0, y: tooltipY + 4, scale: 0.96 }}
                  transition={{ duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
                  style={{ transformOrigin: `${tooltipX}px ${tooltipY}px` }}
                >
                  <rect
                    x={tooltipX}
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="9"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <text
                    x={tooltipX + tooltipWidth / 2}
                    y={tooltipHeight / 2 + 4}
                    textAnchor="middle"
                    className="fill-popover-foreground text-[12px] font-semibold tabular-nums"
                  >
                    {format(active.value)}
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>

      <div
        data-slot="activity-waveform-chart-axis"
        className="mt-1 flex items-center justify-between text-[11px] font-medium text-muted-foreground"
      >
        <span>{startLabel}</span>
        <span>{endLabel}</span>
      </div>

      {resolvedSegments.length && segmentsTotal > 0 ? (
        <div data-slot="activity-waveform-chart-legend" className="mt-3">
          <div className="flex h-2.5 w-full overflow-hidden rounded-full bg-muted">
            {resolvedSegments.map((segment, index) => (
              <motion.span
                key={segment.label}
                className="block h-full first:rounded-l-full last:rounded-r-full"
                style={{
                  backgroundColor: segment.color,
                  width: `${(segment.value / segmentsTotal) * 100}%`,
                }}
                initial={motionEnabled ? { scaleX: 0 } : false}
                animate={{ scaleX: 1 }}
                transition={{
                  duration: 0.5,
                  delay: motionDelay + 0.1 + index * 0.08,
                  ease: [0.16, 1, 0.3, 1],
                }}
              />
            ))}
          </div>
          <div className="mt-2.5 flex flex-wrap items-center gap-x-4 gap-y-1.5 text-xs text-muted-foreground">
            {resolvedSegments.map((segment) => (
              <span
                key={segment.label}
                className="inline-flex items-center gap-1.5"
              >
                <span
                  className="size-2.5 rounded-[3px]"
                  style={{ backgroundColor: segment.color }}
                />
                {segment.label}
                <span className="font-medium text-foreground tabular-nums">
                  {Math.round((segment.value / segmentsTotal) * 100)}%
                </span>
              </span>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type ComponentProps, type ReactNode, useId, useMemo } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { useChartInteraction } from "./chart-interaction";

export const performanceWaterfallChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[460px]",
      md: "max-w-[680px]",
      lg: "max-w-[840px]",
      full: "max-w-full",
    },
  },
  defaultVariants: { size: "md" },
});

export type PerformanceWaterfallDatum = {
  label: string;
  start: number;
  duration: number;
  tone?: string;
};

export type PerformanceWaterfallChartProps = ComponentProps<"div"> &
  VariantProps<typeof performanceWaterfallChartVariants> & {
    data?: PerformanceWaterfallDatum[];
    title?: ReactNode;
    description?: ReactNode;
    markerLabel?: string;
    markerAt?: number;
    valueFormatter?: (ms: number) => string;
    animated?: boolean;
    showTooltip?: boolean;
    showMarker?: boolean;
    height?: number;
    motionDelay?: number;
    loading?: boolean;
  };

const defaultData: PerformanceWaterfallDatum[] = [
  { label: "DNS Lookup", start: 0, duration: 28, tone: "chart-2" },
  { label: "TLS / SSL", start: 28, duration: 42, tone: "chart-4" },
  { label: "TTFB", start: 70, duration: 186, tone: "chart-3" },
  { label: "HTML Parse", start: 256, duration: 94, tone: "chart-2" },
  { label: "JS Bundle", start: 350, duration: 224, tone: "chart-1" },
  { label: "Images", start: 440, duration: 312, tone: "destructive" },
];

const fallbackTones = [
  "var(--chart-2)",
  "var(--chart-4)",
  "var(--chart-3)",
  "var(--chart-1)",
  "var(--destructive)",
  "var(--foreground)",
] as const;

function resolveTone(tone: string | undefined, index: number) {
  if (!tone) return fallbackTones[index % fallbackTones.length];
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(")
  )
    return tone;
  return `var(--${tone})`;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(Math.max(v, lo), hi);
}

function defaultFormatter(ms: number) {
  return ms >= 1000 ? `${(ms / 1000).toFixed(2)}s` : `${Math.round(ms)}ms`;
}

export function PerformanceWaterfallChart({
  className,
  size,
  data = defaultData,
  title = "Performance Waterfall",
  description = "Network resource timing breakdown",
  markerLabel = "LCP",
  markerAt,
  valueFormatter = defaultFormatter,
  animated = true,
  showTooltip = true,
  showMarker = true,
  height = 320,
  motionDelay = 0,
  loading = false,
  ...props
}: PerformanceWaterfallChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");

  const motionEnabled = animated && !shouldReduceMotion;

  const normalizedData = useMemo(
    () =>
      data.filter(
        (d) =>
          Number.isFinite(d.start) &&
          Number.isFinite(d.duration) &&
          d.duration > 0,
      ),
    [data],
  );

  const totalTime = useMemo(
    () =>
      Math.max(1, ...normalizedData.map((d) => d.start + d.duration)) * 1.04,
    [normalizedData],
  );

  const n = normalizedData.length;
  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, n);

  // Layout constants
  const viewBoxWidth = 760;
  const labelWidth = 110;
  const barStartX = labelWidth + 12;
  const rightPad = 20;
  const barAreaWidth = viewBoxWidth - barStartX - rightPad;
  const topGutter = 34;
  const rowPitch = n > 0 ? Math.min(48, Math.max(36, (height * 0.72) / n)) : 40;
  const barH = Math.round(rowPitch * 0.54);
  const bottomGutter = 50;
  const viewBoxHeight = topGutter + n * rowPitch + bottomGutter;
  const axisY = topGutter + n * rowPitch;

  const bars = normalizedData.map((d, i) => {
    const bx = barStartX + (d.start / totalTime) * barAreaWidth;
    const bw = Math.max(4, (d.duration / totalTime) * barAreaWidth);
    const by = topGutter + i * rowPitch + Math.round((rowPitch - barH) / 2);
    const color = resolveTone(d.tone, i);
    return { ...d, bx, bw, by, color, i };
  });

  const activeBar = activeIndex !== null ? bars[activeIndex] : null;
  const tooltipWidth = 176;
  const tooltipHeight = 70;
  const tooltipX = activeBar
    ? clamp(
        activeBar.bx + activeBar.bw / 2 - tooltipWidth / 2,
        barStartX,
        viewBoxWidth - tooltipWidth - rightPad,
      )
    : 0;
  const tooltipY = activeBar
    ? clamp(activeBar.by - tooltipHeight - 10, 4, viewBoxHeight - tooltipHeight)
    : 0;

  const markerX =
    markerAt != null ? barStartX + (markerAt / totalTime) * barAreaWidth : null;

  const tickCount = 5;
  const ticks = Array.from({ length: tickCount }, (_, t) => ({
    x: barStartX + (t / (tickCount - 1)) * barAreaWidth,
    label: valueFormatter((t / (tickCount - 1)) * totalTime),
  }));

  return (
    <div
      data-slot="performance-waterfall-chart"
      className={twMerge(
        performanceWaterfallChartVariants({ size }),
        className,
      )}
      {...interactionProps}
      {...props}
    >
      <div data-slot="performance-waterfall-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="performance-waterfall-chart-plot"
        className="overflow-hidden"
        style={{ height }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="size-full"
            role="img"
            aria-labelledby={`${id}-title`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <defs>
              {bars.map((bar) => (
                <clipPath key={`clip-${bar.i}`} id={`${id}-bc-${bar.i}`}>
                  <motion.rect
                    x={bar.bx}
                    y={bar.by - 2}
                    width={bar.bw}
                    height={barH + 4}
                    initial={motionEnabled ? { scaleX: 0 } : false}
                    animate={{ scaleX: 1 }}
                    transition={{
                      delay: motionDelay + bar.i * 0.09,
                      duration: 0.62,
                      ease: [0.16, 1, 0.3, 1],
                    }}
                    style={{
                      transformBox: "fill-box",
                      transformOrigin: "left center",
                    }}
                  />
                </clipPath>
              ))}
            </defs>

            {/* Row tracks */}
            {bars.map((bar) => (
              <rect
                key={`track-${bar.i}`}
                x={barStartX}
                y={bar.by}
                width={barAreaWidth}
                height={barH}
                rx={barH / 2}
                fill="var(--muted)"
                fillOpacity="0.35"
              />
            ))}

            {/* Grid lines */}
            {ticks.slice(1, -1).map((tick) => (
              <line
                key={`grid-${tick.x}`}
                x1={tick.x}
                x2={tick.x}
                y1={topGutter - 2}
                y2={axisY}
                stroke="var(--border)"
                strokeDasharray="3 7"
                strokeWidth="1"
                opacity="0.5"
              />
            ))}

            {/* Bars */}
            {bars.map((bar) => {
              const isActive = activeIndex === bar.i;
              return (
                <motion.g
                  key={`bar-${bar.i}`}
                  data-slot="performance-waterfall-chart-bar"
                  tabIndex={0}
                  role="button"
                  aria-label={`${bar.label}: ${valueFormatter(bar.start)} + ${valueFormatter(bar.duration)}`}
                  {...getItemProps(bar.i)}
                  animate={{ opacity: isActive ? 1 : 0.78 }}
                  transition={{ duration: 0.22 }}
                  className="outline-none focus-visible:[&>rect]:stroke-ring focus-visible:[&>rect]:stroke-2"
                  style={{ color: bar.color }}
                >
                  {/* Step label */}
                  <text
                    x={labelWidth - 4}
                    y={bar.by + barH / 2 + 1}
                    textAnchor="end"
                    dominantBaseline="middle"
                    fill={
                      isActive ? "var(--foreground)" : "var(--muted-foreground)"
                    }
                    className="text-[11.5px] font-medium"
                  >
                    {bar.label}
                  </text>

                  {/* Bar body */}
                  <rect
                    x={bar.bx}
                    y={bar.by}
                    width={bar.bw}
                    height={barH}
                    rx={barH / 2}
                    fill="currentColor"
                    clipPath={`url(#${id}-bc-${bar.i})`}
                  />

                  {/* Duration label inside bar if wide enough */}
                  {bar.bw > 52 ? (
                    <motion.text
                      x={bar.bx + bar.bw - 8}
                      y={bar.by + barH / 2 + 1}
                      textAnchor="end"
                      dominantBaseline="middle"
                      fill="var(--background)"
                      fillOpacity="0.85"
                      className="text-[10px] font-semibold tabular-nums"
                      initial={motionEnabled ? { opacity: 0 } : false}
                      animate={{ opacity: 1 }}
                      transition={{
                        delay: motionDelay + bar.i * 0.09 + 0.45,
                        duration: 0.22,
                      }}
                      clipPath={`url(#${id}-bc-${bar.i})`}
                    >
                      {valueFormatter(bar.duration)}
                    </motion.text>
                  ) : null}
                </motion.g>
              );
            })}

            {/* Baseline */}
            <line
              x1={barStartX}
              x2={barStartX + barAreaWidth}
              y1={axisY}
              y2={axisY}
              stroke="var(--border)"
              strokeWidth="1.5"
              opacity="0.7"
            />

            {/* Time axis ticks */}
            {ticks.map((tick, ti) => (
              <g key={`tick-${tick.label}-${tick.x.toFixed(2)}`}>
                <line
                  x1={tick.x}
                  x2={tick.x}
                  y1={axisY}
                  y2={axisY + 5}
                  stroke="var(--border)"
                  strokeWidth="1"
                  opacity="0.6"
                />
                <text
                  x={tick.x}
                  y={axisY + 17}
                  textAnchor={
                    ti === 0 ? "start" : ti === tickCount - 1 ? "end" : "middle"
                  }
                  fill="var(--muted-foreground)"
                  className="text-[10px] font-medium tabular-nums"
                >
                  {tick.label}
                </text>
              </g>
            ))}

            {/* LCP / milestone marker */}
            {showMarker && markerX !== null ? (
              <g data-slot="performance-waterfall-chart-marker">
                <motion.line
                  x1={markerX}
                  x2={markerX}
                  y1={topGutter - 4}
                  y2={axisY + 2}
                  stroke="var(--foreground)"
                  strokeWidth="1.5"
                  strokeDasharray="4 5"
                  strokeLinecap="round"
                  opacity="0.55"
                  initial={
                    motionEnabled ? { pathLength: 0, opacity: 0 } : false
                  }
                  animate={{ pathLength: 1, opacity: 0.55 }}
                  transition={{
                    delay: motionDelay + 0.7,
                    duration: 0.45,
                    ease: [0.22, 1, 0.36, 1],
                  }}
                />
                <motion.text
                  x={markerX + 5}
                  y={topGutter - 8}
                  fill="var(--foreground)"
                  className="text-[10px] font-semibold"
                  initial={motionEnabled ? { opacity: 0 } : false}
                  animate={{ opacity: 0.72 }}
                  transition={{ delay: motionDelay + 1.1, duration: 0.24 }}
                >
                  {markerLabel}
                </motion.text>
                <circle
                  cx={markerX}
                  cy={topGutter - 4}
                  r="3"
                  fill="var(--foreground)"
                  opacity="0.55"
                />
              </g>
            ) : null}

            {/* Tooltip */}
            <AnimatePresence>
              {showTooltip && activeBar ? (
                <motion.g
                  data-slot="performance-waterfall-chart-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? {
                          opacity: 0,
                          x: tooltipX,
                          y: tooltipY + 6,
                          scale: 0.97,
                        }
                      : false
                  }
                  animate={{ opacity: 1, x: tooltipX, y: tooltipY, scale: 1 }}
                  exit={{
                    opacity: 0,
                    x: tooltipX,
                    y: tooltipY + 4,
                    scale: 0.97,
                  }}
                  transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
                >
                  <rect
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="12"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <text
                    x="14"
                    y="22"
                    fill="var(--popover-foreground)"
                    className="text-[12px] font-semibold"
                  >
                    {activeBar.label}
                  </text>
                  <line
                    x1="14"
                    x2={tooltipWidth - 14}
                    y1="30"
                    y2="30"
                    stroke="var(--border)"
                    opacity="0.5"
                  />
                  <text
                    x="14"
                    y="45"
                    fill="var(--muted-foreground)"
                    className="text-[11px] font-medium"
                  >
                    Start
                  </text>
                  <text
                    x={tooltipWidth - 14}
                    y="45"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[11px] font-semibold tabular-nums"
                  >
                    {valueFormatter(activeBar.start)}
                  </text>
                  <text
                    x="14"
                    y="60"
                    fill="var(--muted-foreground)"
                    className="text-[11px] font-medium"
                  >
                    Duration
                  </text>
                  <text
                    x={tooltipWidth - 14}
                    y="60"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[11px] font-semibold tabular-nums"
                    style={{ fill: activeBar.color }}
                  >
                    {valueFormatter(activeBar.duration)}
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type ComponentProps, type ReactNode, useId, useMemo } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { useChartInteraction } from "./chart-interaction";

export const thresholdBandChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[380px]",
      md: "max-w-[560px]",
      lg: "max-w-[720px]",
      full: "max-w-full",
    },
  },
  defaultVariants: { size: "md" },
});

export type ThresholdBand = {
  label: string;
  max?: number;
  tone?: string;
};

export type ThresholdBandChartProps = ComponentProps<"div"> &
  VariantProps<typeof thresholdBandChartVariants> & {
    bands?: ThresholdBand[];
    value?: number;
    title?: ReactNode;
    description?: ReactNode;
    totalMax?: number;
    unit?: string;
    valueFormatter?: (value: number) => string;
    animated?: boolean;
    showTooltip?: boolean;
    motionDelay?: number;
  };

const defaultBands: ThresholdBand[] = [
  { label: "Good", max: 2500, tone: "chart-2" },
  { label: "Needs improvement", max: 4000, tone: "chart-4" },
  { label: "Poor", tone: "destructive" },
];

function resolveTone(tone: string | undefined, fallback: string) {
  if (!tone) return fallback;
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(")
  )
    return tone;
  return `var(--${tone})`;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(Math.max(v, lo), hi);
}

function defaultFormatter(v: number, unit: string) {
  if (unit === "ms") {
    return v >= 1000 ? `${(v / 1000).toFixed(2)}s` : `${Math.round(v)}ms`;
  }
  return `${v}${unit}`;
}

export function ThresholdBandChart({
  className,
  size,
  bands = defaultBands,
  value = 2800,
  title = "LCP Threshold",
  description = "Largest Contentful Paint — how fast your page feels",
  totalMax,
  unit = "ms",
  valueFormatter,
  animated = true,
  showTooltip = true,
  motionDelay = 0,
  ...props
}: ThresholdBandChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");

  const motionEnabled = animated && !shouldReduceMotion;
  const fmt = (v: number) =>
    valueFormatter ? valueFormatter(v) : defaultFormatter(v, unit);

  // Normalize band maxes
  const resolvedBands = useMemo(() => {
    const maxes = bands.map((b) => b.max ?? null);
    // Auto total max = last defined max * 1.5
    const lastDefined = [...maxes].reverse().find((m) => m !== null);
    const auto = (lastDefined ?? 100) * 1.6;
    const safeTotal = totalMax ?? auto;

    let prev = 0;
    return bands.map((b) => {
      const end = b.max ?? safeTotal;
      const result = { ...b, start: prev, end, safeTotal };
      prev = end;
      return result;
    });
  }, [bands, totalMax]);

  const safeTotal = resolvedBands[resolvedBands.length - 1]?.safeTotal ?? 100;
  const {
    activeIndex: activeBandIndex,
    getItemProps,
    hasEnteredView,
    interactionProps,
  } = useChartInteraction(id, resolvedBands.length);
  const safeValue = clamp(value, 0, safeTotal);

  // Current band index
  const currentBandIndex = useMemo(() => {
    for (let i = 0; i < resolvedBands.length - 1; i++) {
      if (safeValue <= resolvedBands[i].end) return i;
    }
    return resolvedBands.length - 1;
  }, [resolvedBands, safeValue]);

  const currentBand = resolvedBands[currentBandIndex];

  // SVG layout
  const viewBoxWidth = 560;
  const viewBoxHeight = 178;
  const bandAreaX = 12;
  const bandAreaW = viewBoxWidth - 24;
  const bandY = 56;
  const bandH = 28;
  const bandRx = bandH / 2;

  const markerX = bandAreaX + (safeValue / safeTotal) * bandAreaW;

  const activeBand =
    activeBandIndex !== null ? resolvedBands[activeBandIndex] : null;
  const tooltipWidth = 168;
  const tooltipHeight = 58;
  const activeBandCenterX = activeBand
    ? bandAreaX +
      ((activeBand.start + activeBand.end) / 2 / safeTotal) * bandAreaW
    : markerX;
  const tooltipX = clamp(
    activeBandCenterX - tooltipWidth / 2,
    4,
    viewBoxWidth - tooltipWidth - 4,
  );
  const tooltipY = bandY + bandH + 28;
  const tooltipArrowX = clamp(
    activeBandCenterX - tooltipX,
    14,
    tooltipWidth - 14,
  );
  const activeBandRange = activeBand
    ? activeBandIndex === 0
      ? `≤ ${fmt(activeBand.end)}`
      : activeBandIndex === resolvedBands.length - 1
        ? `> ${fmt(activeBand.start)}`
        : `${fmt(activeBand.start)} – ${fmt(activeBand.end)}`
    : "";

  return (
    <div
      data-slot="threshold-band-chart"
      className={twMerge(thresholdBandChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="threshold-band-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div data-slot="threshold-band-chart-plot" className="overflow-hidden">
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="w-full"
            role="img"
            aria-labelledby={`${id}-title`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <defs>
              {resolvedBands.map((band, bi) => (
                <clipPath
                  key={`clip-${band.label}-${band.start}-${band.end}`}
                  id={`${id}-band-clip-${bi}`}
                >
                  <motion.rect
                    x={bandAreaX + (band.start / safeTotal) * bandAreaW}
                    y={bandY - 2}
                    height={bandH + 4}
                    rx={bandRx}
                    initial={
                      motionEnabled
                        ? { width: 0 }
                        : {
                            width:
                              ((band.end - band.start) / safeTotal) * bandAreaW,
                          }
                    }
                    animate={{
                      width: ((band.end - band.start) / safeTotal) * bandAreaW,
                    }}
                    transition={{
                      delay: motionDelay + bi * 0.1,
                      duration: 0.64,
                      ease: [0.16, 1, 0.3, 1],
                    }}
                  />
                </clipPath>
              ))}
            </defs>

            {/* Band segments */}
            {resolvedBands.map((band, bi) => {
              const bx = bandAreaX + (band.start / safeTotal) * bandAreaW;
              const bw = ((band.end - band.start) / safeTotal) * bandAreaW;
              const tone = resolveTone(band.tone, "var(--muted-foreground)");
              const isActive = activeBandIndex === bi;
              const isCurrent = currentBandIndex === bi;
              const accessibleRange =
                bi === 0
                  ? `up to ${fmt(band.end)}`
                  : bi === resolvedBands.length - 1
                    ? `above ${fmt(band.start)}`
                    : `${fmt(band.start)} to ${fmt(band.end)}`;

              return (
                <motion.g
                  key={`band-${band.label}-${band.start}-${band.end}`}
                  tabIndex={0}
                  role="button"
                  aria-label={`${band.label}: ${accessibleRange}`}
                  aria-describedby={
                    showTooltip && isActive ? `${id}-tooltip` : undefined
                  }
                  {...getItemProps(bi)}
                  style={{ cursor: "pointer" }}
                >
                  <rect
                    x={bx}
                    y={bandY}
                    width={bw}
                    height={bandH}
                    rx={bandRx}
                    fill={tone}
                    fillOpacity={
                      isCurrent
                        ? isActive
                          ? 0.28
                          : 0.2
                        : isActive
                          ? 0.16
                          : 0.1
                    }
                    clipPath={`url(#${id}-band-clip-${bi})`}
                  />
                  <motion.rect
                    x={bx}
                    y={bandY}
                    width={bw}
                    height={bandH}
                    rx={bandRx}
                    fill={tone}
                    fillOpacity={isCurrent ? 1 : 0.5}
                    stroke={isCurrent ? tone : "none"}
                    strokeWidth={isCurrent ? "0.5" : "0"}
                    clipPath={`url(#${id}-band-clip-${bi})`}
                    animate={{
                      fillOpacity: isCurrent
                        ? isActive
                          ? 0.82
                          : 0.62
                        : isActive
                          ? 0.45
                          : 0.3,
                    }}
                    transition={{ duration: 0.22 }}
                  />
                  {/* Band label above */}
                  <motion.text
                    x={bx + bw / 2}
                    y={bandY - 10}
                    textAnchor="middle"
                    fill={tone}
                    fillOpacity={isCurrent ? 1 : 0.6}
                    className="text-[11px] font-semibold"
                    initial={
                      motionEnabled ? { opacity: 0, y: bandY - 4 } : false
                    }
                    animate={{ opacity: isCurrent ? 1 : 0.6, y: bandY - 10 }}
                    transition={{
                      delay: motionDelay + bi * 0.1 + 0.3,
                      duration: 0.28,
                    }}
                  >
                    {band.label}
                  </motion.text>
                  {/* Band max label */}
                  {bi < resolvedBands.length - 1 ? (
                    <text
                      x={bx + bw}
                      y={bandY + bandH + 14}
                      textAnchor="middle"
                      fill="var(--muted-foreground)"
                      className="text-[10px] font-medium tabular-nums"
                    >
                      {fmt(band.end)}
                    </text>
                  ) : null}
                </motion.g>
              );
            })}

            {/* Value marker */}
            <motion.g
              data-slot="threshold-band-chart-marker"
              initial={
                motionEnabled
                  ? { x: bandAreaX, opacity: 0 }
                  : { x: markerX - 1, opacity: 1 }
              }
              animate={{ x: markerX - 1, opacity: 1 }}
              transition={{
                x: {
                  delay: motionDelay + 0.5,
                  duration: 0.9,
                  ease: [0.16, 1, 0.3, 1],
                },
                opacity: { delay: motionDelay + 0.5, duration: 0.32 },
              }}
            >
              {/* Vertical line */}
              <line
                x1="1"
                x2="1"
                y1={bandY - 3}
                y2={bandY + bandH + 3}
                stroke="var(--foreground)"
                strokeWidth="2"
                strokeLinecap="round"
              />
              {/* Top diamond */}
              <polygon
                points="1,-4 5,0 1,4 -3,0"
                transform={`translate(0 ${bandY - 7})`}
                fill="var(--foreground)"
              />
              {/* Bottom label */}
              <motion.text
                x="1"
                y={bandY + bandH + 26}
                textAnchor="middle"
                fill="var(--foreground)"
                className="text-[12.5px] font-semibold tabular-nums"
                animate={{ opacity: activeBand ? 0 : 1 }}
                transition={{ duration: 0.14 }}
              >
                {fmt(safeValue)}
              </motion.text>
            </motion.g>

            {/* Active band tooltip */}
            <AnimatePresence>
              {showTooltip && activeBand ? (
                <motion.g
                  id={`${id}-tooltip`}
                  data-slot="threshold-band-chart-tooltip"
                  role="tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? {
                          opacity: 0,
                          x: tooltipX,
                          y: tooltipY + 5,
                          scale: 0.97,
                        }
                      : false
                  }
                  animate={{ opacity: 1, x: tooltipX, y: tooltipY, scale: 1 }}
                  exit={{
                    opacity: 0,
                    x: tooltipX,
                    y: tooltipY + 3,
                    scale: 0.97,
                  }}
                  transition={{ duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
                >
                  <path
                    d={`M ${tooltipArrowX - 6} 0 L ${tooltipArrowX} -7 L ${tooltipArrowX + 6} 0 Z`}
                    fill="var(--popover)"
                    stroke="var(--border)"
                    strokeLinejoin="round"
                  />
                  <rect
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="10"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <text
                    x="12"
                    y="22"
                    fill="var(--popover-foreground)"
                    className="text-[11px] font-semibold"
                  >
                    {activeBand.label}
                  </text>
                  <text
                    x="12"
                    y="40"
                    fill="var(--muted-foreground)"
                    className="text-[10px] font-medium"
                  >
                    Range
                  </text>
                  <text
                    x={tooltipWidth - 12}
                    y="40"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[10px] font-semibold tabular-nums"
                  >
                    {activeBandRange}
                  </text>
                  <text
                    x="12"
                    y="52"
                    fill="var(--muted-foreground)"
                    className="text-[10px] font-medium"
                  >
                    Current value
                  </text>
                  <text
                    x={tooltipWidth - 12}
                    y="52"
                    textAnchor="end"
                    fill={resolveTone(
                      currentBand?.tone,
                      "var(--muted-foreground)",
                    )}
                    className="text-[10px] font-semibold tabular-nums"
                  >
                    {fmt(safeValue)}
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type ComponentProps, type ReactNode, useId, useMemo } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { useChartInteraction } from "./chart-interaction";

export const impactPriorityMatrixVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[420px]",
      md: "max-w-[560px]",
      lg: "max-w-[720px]",
      full: "max-w-full",
    },
  },
  defaultVariants: { size: "md" },
});

export type ImpactPriorityItem = {
  label: string;
  effort: number;
  impact: number;
  description?: string;
  tone?: string;
};

export type ImpactPriorityMatrixProps = ComponentProps<"div"> &
  VariantProps<typeof impactPriorityMatrixVariants> & {
    data?: ImpactPriorityItem[];
    title?: ReactNode;
    description?: ReactNode;
    effortLabel?: string;
    impactLabel?: string;
    quadrantLabels?: [string, string, string, string];
    animated?: boolean;
    showTooltip?: boolean;
    height?: number;
    motionDelay?: number;
  };

const defaultData: ImpactPriorityItem[] = [
  {
    label: "Optimize images",
    effort: 20,
    impact: 88,
    description: "Compress and lazy-load images",
    tone: "chart-2",
  },
  {
    label: "Reduce JS",
    effort: 55,
    impact: 82,
    description: "Code-split and tree-shake bundle",
    tone: "chart-2",
  },
  {
    label: "Swap font",
    effort: 18,
    impact: 42,
    description: "Use system font stack",
    tone: "chart-4",
  },
  {
    label: "Remove scripts",
    effort: 78,
    impact: 90,
    description: "Eliminate blocking third-party",
    tone: "chart-3",
  },
  {
    label: "Add CDN",
    effort: 64,
    impact: 35,
    description: "Route assets through edge CDN",
    tone: "destructive",
  },
  {
    label: "Enable cache",
    effort: 22,
    impact: 58,
    description: "Set long-lived cache headers",
    tone: "chart-2",
  },
];

const fallbackTones = [
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-1)",
  "var(--destructive)",
] as const;

function resolveTone(tone: string | undefined, index: number) {
  if (!tone) return fallbackTones[index % fallbackTones.length];
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(")
  )
    return tone;
  return `var(--${tone})`;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(Math.max(v, lo), hi);
}

export function ImpactPriorityMatrix({
  className,
  size,
  data = defaultData,
  title = "Impact Priority Matrix",
  description = "Prioritize improvements by effort and impact",
  effortLabel = "Effort",
  impactLabel = "Impact",
  quadrantLabels = ["Quick Wins", "Strategic", "Low Priority", "Expensive"],
  animated = true,
  showTooltip = true,
  height = 360,
  motionDelay = 0,
  ...props
}: ImpactPriorityMatrixProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");

  const motionEnabled = animated && !shouldReduceMotion;
  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, data.length);

  // Layout
  const viewBoxWidth = 500;
  const viewBoxHeight = 440;
  const gridX = 54;
  const gridY = 34;
  const gridW = 416;
  const gridH = 348;
  const midX = gridX + gridW / 2;
  const midY = gridY + gridH / 2;

  const points = useMemo(
    () =>
      data.map((d, i) => ({
        ...d,
        i,
        px: gridX + (clamp(d.effort, 0, 100) / 100) * gridW,
        py: gridY + (1 - clamp(d.impact, 0, 100) / 100) * gridH,
        color: resolveTone(d.tone, i),
      })),
    [data],
  );

  const activePoint = activeIndex !== null ? points[activeIndex] : null;

  const tooltipWidth = 196;
  const tooltipHeight = 66;
  const tooltipX = activePoint
    ? clamp(
        activePoint.px - tooltipWidth / 2,
        gridX,
        gridX + gridW - tooltipWidth,
      )
    : 0;
  const tooltipY = activePoint
    ? clamp(
        activePoint.py - tooltipHeight - 16,
        gridY,
        gridY + gridH - tooltipHeight,
      )
    : 0;

  const quadrantConfigs = [
    {
      id: "quick-wins",
      x: gridX,
      y: gridY,
      w: gridW / 2,
      h: gridH / 2,
      label: quadrantLabels[0],
      labelX: gridX + 14,
      labelY: gridY + 18,
      tone: "var(--chart-2)",
    },
    {
      id: "strategic",
      x: midX,
      y: gridY,
      w: gridW / 2,
      h: gridH / 2,
      label: quadrantLabels[1],
      labelX: gridX + gridW - 14,
      labelY: gridY + 18,
      tone: "var(--chart-3)",
    },
    {
      id: "low-priority",
      x: gridX,
      y: midY,
      w: gridW / 2,
      h: gridH / 2,
      label: quadrantLabels[2],
      labelX: gridX + 14,
      labelY: gridY + gridH - 10,
      tone: "var(--muted-foreground)",
    },
    {
      id: "expensive",
      x: midX,
      y: midY,
      w: gridW / 2,
      h: gridH / 2,
      label: quadrantLabels[3],
      labelX: gridX + gridW - 14,
      labelY: gridY + gridH - 10,
      tone: "var(--destructive)",
    },
  ] as const;

  return (
    <div
      data-slot="impact-priority-matrix"
      className={twMerge(impactPriorityMatrixVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="impact-priority-matrix-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="impact-priority-matrix-plot"
        className="overflow-hidden"
        style={{ height }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="size-full"
            role="img"
            aria-labelledby={`${id}-title`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            {/* Quadrant backgrounds */}
            {quadrantConfigs.map((q) => (
              <rect
                key={q.id}
                x={q.x}
                y={q.y}
                width={q.w}
                height={q.h}
                fill={q.tone}
                fillOpacity="0.035"
              />
            ))}

            {/* Grid border */}
            <rect
              x={gridX}
              y={gridY}
              width={gridW}
              height={gridH}
              fill="none"
              stroke="var(--border)"
              strokeWidth="1"
              opacity="0.5"
            />

            {/* Axis dividers */}
            <line
              x1={midX}
              x2={midX}
              y1={gridY}
              y2={gridY + gridH}
              stroke="var(--border)"
              strokeWidth="1.5"
              strokeDasharray="5 6"
              opacity="0.6"
            />
            <line
              x1={gridX}
              x2={gridX + gridW}
              y1={midY}
              y2={midY}
              stroke="var(--border)"
              strokeWidth="1.5"
              strokeDasharray="5 6"
              opacity="0.6"
            />

            {/* Quadrant labels */}
            {quadrantConfigs.map((q, qi) => (
              <text
                key={`qlabel-${q.id}`}
                x={q.labelX}
                y={q.labelY}
                textAnchor={qi % 2 === 0 ? "start" : "end"}
                fill={q.tone}
                fillOpacity="0.6"
                className="text-[10.5px] font-semibold uppercase tracking-wider"
              >
                {q.label}
              </text>
            ))}

            {/* Axis labels */}
            <text
              x={midX}
              y={gridY + gridH + 22}
              textAnchor="middle"
              fill="var(--muted-foreground)"
              className="text-[11px] font-medium"
            >
              {effortLabel} →
            </text>
            <text
              x={gridX - 10}
              y={midY}
              textAnchor="middle"
              fill="var(--muted-foreground)"
              className="text-[11px] font-medium"
              transform={`rotate(-90, ${gridX - 10}, ${midY})`}
            >
              {impactLabel} →
            </text>

            {/* Low/High axis labels */}
            <text
              x={gridX}
              y={gridY + gridH + 22}
              textAnchor="start"
              fill="var(--muted-foreground)"
              fillOpacity="0.6"
              className="text-[10px] font-medium"
            >
              Low
            </text>
            <text
              x={gridX + gridW}
              y={gridY + gridH + 22}
              textAnchor="end"
              fill="var(--muted-foreground)"
              fillOpacity="0.6"
              className="text-[10px] font-medium"
            >
              High
            </text>
            <text
              x={gridX - 36}
              y={gridY + gridH}
              textAnchor="middle"
              fill="var(--muted-foreground)"
              fillOpacity="0.6"
              className="text-[10px] font-medium"
            >
              Low
            </text>
            <text
              x={gridX - 36}
              y={gridY + 4}
              textAnchor="middle"
              fill="var(--muted-foreground)"
              fillOpacity="0.6"
              className="text-[10px] font-medium"
            >
              High
            </text>

            {/* Points */}
            {points.map((p) => {
              const isActive = activeIndex === p.i;
              return (
                <motion.g
                  key={`point-${p.i}`}
                  data-slot="impact-priority-matrix-point"
                  tabIndex={0}
                  role="button"
                  aria-label={`${p.label}: effort ${p.effort}, impact ${p.impact}`}
                  {...getItemProps(p.i)}
                  className="outline-none"
                  style={{ color: p.color }}
                >
                  {/* Glow ring */}
                  {isActive ? (
                    <motion.circle
                      cx={p.px}
                      cy={p.py}
                      r="16"
                      fill="currentColor"
                      fillOpacity="0.12"
                      initial={{ opacity: 0, scale: 0.92 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ duration: 0.18, ease: "easeOut" }}
                      style={{ transformOrigin: `${p.px}px ${p.py}px` }}
                    />
                  ) : null}

                  {/* Outer ring */}
                  <motion.circle
                    cx={p.px}
                    cy={p.py}
                    r={isActive ? 11 : 9}
                    fill="currentColor"
                    fillOpacity={isActive ? 0.2 : 0.12}
                    stroke="currentColor"
                    strokeWidth={isActive ? 1.5 : 1}
                    strokeOpacity={isActive ? 0.7 : 0.35}
                    initial={motionEnabled ? { scale: 0, opacity: 0 } : false}
                    animate={{ scale: 1, opacity: 1 }}
                    transition={{
                      delay: motionDelay + 0.12 + p.i * 0.07,
                      type: "spring",
                      stiffness: 260,
                      damping: 18,
                    }}
                    style={{ transformOrigin: `${p.px}px ${p.py}px` }}
                  />

                  {/* Core dot */}
                  <motion.circle
                    cx={p.px}
                    cy={p.py}
                    r={isActive ? 6 : 5}
                    fill="currentColor"
                    initial={motionEnabled ? { scale: 0 } : false}
                    animate={{ scale: 1 }}
                    transition={{
                      delay: motionDelay + 0.2 + p.i * 0.07,
                      type: "spring",
                      stiffness: 300,
                      damping: 16,
                    }}
                    style={{ transformOrigin: `${p.px}px ${p.py}px` }}
                  />

                  {/* Point label */}
                  <motion.text
                    x={p.px}
                    y={p.py - 14}
                    textAnchor="middle"
                    fill="var(--foreground)"
                    fillOpacity={isActive ? 1 : 0}
                    className="text-[10.5px] font-semibold"
                    animate={{ fillOpacity: isActive ? 1 : 0 }}
                    transition={{ duration: 0.18 }}
                  >
                    {p.label}
                  </motion.text>
                </motion.g>
              );
            })}

            {/* Tooltip */}
            <AnimatePresence>
              {showTooltip && activePoint ? (
                <motion.g
                  data-slot="impact-priority-matrix-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? {
                          opacity: 0,
                          x: tooltipX,
                          y: tooltipY + 6,
                          scale: 0.97,
                        }
                      : false
                  }
                  animate={{ opacity: 1, x: tooltipX, y: tooltipY, scale: 1 }}
                  exit={{
                    opacity: 0,
                    x: tooltipX,
                    y: tooltipY + 4,
                    scale: 0.97,
                  }}
                  transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
                >
                  <rect
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="12"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <circle cx="14" cy="18" r="4.5" fill={activePoint.color} />
                  <text
                    x="26"
                    y="22"
                    fill="var(--popover-foreground)"
                    className="text-[12px] font-semibold"
                  >
                    {activePoint.label}
                  </text>
                  {activePoint.description ? (
                    <text
                      x="14"
                      y="38"
                      fill="var(--muted-foreground)"
                      className="text-[10.5px] font-medium"
                    >
                      {activePoint.description}
                    </text>
                  ) : null}
                  <text
                    x="14"
                    y="55"
                    fill="var(--muted-foreground)"
                    className="text-[10px] font-medium"
                  >
                    Effort {activePoint.effort} · Impact {activePoint.impact}
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import {
  type FocusEvent,
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useState,
} from "react";

type ChartItemElement = HTMLElement | SVGElement;

export type ChartInteractionProps = {
  "aria-pressed": boolean;
  "data-chart-item-index": number;
  onBlur: (event: FocusEvent<ChartItemElement>) => void;
  onClick: () => void;
  onFocus: () => void;
  onKeyDown: (event: KeyboardEvent<ChartItemElement>) => void;
  onPointerEnter: (event: PointerEvent<ChartItemElement>) => void;
  onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
};

export type ChartInteraction = {
  activeIndex: number | null;
  clearSelection: () => void;
  getItemProps: (index: number) => ChartInteractionProps;
  interactionProps: {
    "data-chart-interaction": string;
    "data-chart-viewport": string;
    onPointerLeave: (event: PointerEvent<ChartItemElement>) => void;
  };
  hasEnteredView: boolean;
  selectedIndex: number | null;
  selectIndex: (index: number | null) => void;
};

export function useChartInView(viewportId: string): boolean {
  const [hasEnteredView, setHasEnteredView] = useState(false);

  useEffect(() => {
    if (hasEnteredView) return;

    const root = document.querySelector(
      `[data-chart-viewport="${viewportId}"]`,
    );

    if (!root || typeof IntersectionObserver === "undefined") {
      setHasEnteredView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry?.isIntersecting) return;
        setHasEnteredView(true);
        observer.disconnect();
      },
      { threshold: 0.2 },
    );

    observer.observe(root);
    return () => observer.disconnect();
  }, [hasEnteredView, viewportId]);

  return hasEnteredView;
}

/**
 * Shared intent model for SVG charts: hover/focus is temporary while click,
 * tap, Enter, or Space pins a selection until Escape or an outside press.
 */
export function useChartInteraction(
  interactionId: string,
  itemCount: number,
): ChartInteraction {
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const hasEnteredView = useChartInView(interactionId);

  useEffect(() => {
    setHoveredIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
    setSelectedIndex((index) =>
      index !== null && index >= itemCount ? null : index,
    );
  }, [itemCount]);

  useEffect(() => {
    if (selectedIndex === null) return;

    function handlePointerDown(event: globalThis.PointerEvent) {
      const target = event.target;

      if (
        target instanceof Element &&
        target.closest(`[data-chart-interaction="${interactionId}"]`)
      ) {
        return;
      }

      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") return;
      setSelectedIndex(null);
      setHoveredIndex(null);
    }

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [interactionId, selectedIndex]);

  const focusItem = useCallback(
    (index: number) => {
      const root = document.querySelector<HTMLElement>(
        `[data-chart-interaction="${interactionId}"]`,
      );
      const item = root?.querySelector<HTMLElement>(
        `[data-chart-item-index="${index}"]`,
      );
      item?.focus();
    },
    [interactionId],
  );

  const getItemProps = useCallback(
    (index: number): ChartInteractionProps => ({
      "aria-pressed": selectedIndex === index,
      "data-chart-item-index": index,
      onBlur: (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHoveredIndex(null);
        }
      },
      onClick: () => {
        setHoveredIndex(null);
        setSelectedIndex((current) => (current === index ? null : index));
      },
      onFocus: () => setHoveredIndex(index),
      onKeyDown: (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          setHoveredIndex(null);
          setSelectedIndex((current) => (current === index ? null : index));
          return;
        }

        const direction =
          event.key === "ArrowRight" || event.key === "ArrowDown"
            ? 1
            : event.key === "ArrowLeft" || event.key === "ArrowUp"
              ? -1
              : 0;

        if (!direction || itemCount < 2) return;
        event.preventDefault();
        const nextIndex = (index + direction + itemCount) % itemCount;
        setHoveredIndex(nextIndex);
        focusItem(nextIndex);
      },
      onPointerEnter: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(index);
      },
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    }),
    [focusItem, itemCount, selectedIndex],
  );

  return {
    activeIndex: hoveredIndex ?? selectedIndex,
    clearSelection: () => {
      setHoveredIndex(null);
      setSelectedIndex(null);
    },
    getItemProps,
    interactionProps: {
      "data-chart-interaction": interactionId,
      "data-chart-viewport": interactionId,
      onPointerLeave: (event) => {
        if (event.pointerType !== "touch") setHoveredIndex(null);
      },
    },
    hasEnteredView,
    selectedIndex,
    selectIndex: (index) => {
      setHoveredIndex(null);
      setSelectedIndex(
        index !== null && index >= 0 && index < itemCount ? index : null,
      );
    },
  };
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { type ComponentProps, type ReactNode, useId, useMemo } from "react";
import { twMerge } from "tailwind-merge";
import { tv, type VariantProps } from "tailwind-variants";
import { useChartInteraction } from "./chart-interaction";

export const resourceTreemapChartVariants = tv({
  base: "not-prose w-full text-foreground",
  variants: {
    size: {
      sm: "max-w-[400px]",
      md: "max-w-[600px]",
      lg: "max-w-[780px]",
      full: "max-w-full",
    },
  },
  defaultVariants: { size: "md" },
});

export type ResourceTreemapDatum = {
  label: string;
  value: number;
  unit?: string;
  tone?: string;
};

export type ResourceTreemapChartProps = ComponentProps<"div"> &
  VariantProps<typeof resourceTreemapChartVariants> & {
    data?: ResourceTreemapDatum[];
    title?: ReactNode;
    description?: ReactNode;
    valueFormatter?: (value: number, unit?: string) => string;
    animated?: boolean;
    showTooltip?: boolean;
    showLabels?: boolean;
    height?: number;
    motionDelay?: number;
  };

const defaultData: ResourceTreemapDatum[] = [
  { label: "JavaScript", value: 48, unit: "KB", tone: "chart-1" },
  { label: "Images", value: 28, unit: "KB", tone: "chart-2" },
  { label: "CSS", value: 12, unit: "KB", tone: "chart-4" },
  { label: "Fonts", value: 8, unit: "KB", tone: "chart-3" },
  { label: "Other", value: 4, unit: "KB", tone: "muted-foreground" },
];

const fallbackTones = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--foreground)",
] as const;

function resolveTone(tone: string | undefined, index: number) {
  if (!tone) return fallbackTones[index % fallbackTones.length];
  if (
    tone.startsWith("var(") ||
    tone.startsWith("color-mix(") ||
    tone.startsWith("oklch(")
  )
    return tone;
  return `var(--${tone})`;
}

function clamp(v: number, lo: number, hi: number) {
  return Math.min(Math.max(v, lo), hi);
}

type TileRect = {
  x: number;
  y: number;
  w: number;
  h: number;
};

function layoutTreemap(
  values: number[],
  x: number,
  y: number,
  width: number,
  height: number,
): TileRect[] {
  if (values.length === 0) return [];
  if (values.length === 1) return [{ x, y, w: width, h: height }];

  const total = values.reduce((s, v) => s + v, 0);
  let leftSum = 0;
  let splitIdx = 1;
  for (let i = 0; i < values.length - 1; i++) {
    leftSum += values[i];
    splitIdx = i + 1;
    if (leftSum / total >= 0.5) break;
  }

  const leftFraction = leftSum / total;
  const leftValues = values.slice(0, splitIdx);
  const rightValues = values.slice(splitIdx);

  if (width >= height) {
    const lw = width * leftFraction;
    return [
      ...layoutTreemap(leftValues, x, y, lw, height),
      ...layoutTreemap(rightValues, x + lw, y, width - lw, height),
    ];
  }

  const th = height * leftFraction;
  return [
    ...layoutTreemap(leftValues, x, y, width, th),
    ...layoutTreemap(rightValues, x, y + th, width, height - th),
  ];
}

export function ResourceTreemapChart({
  className,
  size,
  data = defaultData,
  title = "Resource Treemap",
  description = "Page weight breakdown by resource type",
  valueFormatter,
  animated = true,
  showTooltip = true,
  showLabels = true,
  height = 320,
  motionDelay = 0,
  ...props
}: ResourceTreemapChartProps) {
  const shouldReduceMotion = useReducedMotion();
  const rawId = useId();
  const id = rawId.replace(/:/g, "");

  const motionEnabled = animated && !shouldReduceMotion;

  const normalizedData = useMemo(
    () => data.filter((d) => Number.isFinite(d.value) && d.value > 0),
    [data],
  );
  const { activeIndex, getItemProps, hasEnteredView, interactionProps } =
    useChartInteraction(id, normalizedData.length);

  const total = useMemo(
    () => normalizedData.reduce((s, d) => s + d.value, 0),
    [normalizedData],
  );

  const sorted = useMemo(
    () => [...normalizedData].sort((a, b) => b.value - a.value),
    [normalizedData],
  );

  const fmt = (d: ResourceTreemapDatum) => {
    if (valueFormatter) return valueFormatter(d.value, d.unit);
    return d.unit ? `${d.value}${d.unit}` : String(d.value);
  };

  // SVG layout
  const viewBoxWidth = 560;
  const viewBoxHeight = 320;
  const gap = 3;
  const outerPad = 0;

  const tiles = useMemo(() => {
    const values = sorted.map((d) => d.value);
    const rects = layoutTreemap(
      values,
      outerPad,
      outerPad,
      viewBoxWidth - outerPad * 2,
      viewBoxHeight - outerPad * 2,
    );
    return sorted.map((d, i) => ({
      ...d,
      i,
      originalIndex: normalizedData.indexOf(d),
      color: resolveTone(d.tone, i),
      rect: rects[i],
      percent: Math.round((d.value / total) * 100),
    }));
  }, [sorted, total, normalizedData]);

  const activePoint = activeIndex !== null ? tiles[activeIndex] : null;

  const tooltipWidth = 168;
  const tooltipHeight = 64;
  const tooltipX = activePoint
    ? clamp(
        activePoint.rect.x + activePoint.rect.w / 2 - tooltipWidth / 2,
        2,
        viewBoxWidth - tooltipWidth - 2,
      )
    : 0;
  const tooltipY = activePoint
    ? clamp(
        activePoint.rect.y + activePoint.rect.h / 2 - tooltipHeight - 10,
        2,
        viewBoxHeight - tooltipHeight - 2,
      )
    : 0;

  return (
    <div
      data-slot="resource-treemap-chart"
      className={twMerge(resourceTreemapChartVariants({ size }), className)}
      {...interactionProps}
      {...props}
    >
      <div data-slot="resource-treemap-chart-header" className="mb-3">
        <h3 className="truncate text-sm font-semibold tracking-tight text-foreground">
          {title}
        </h3>
        {description ? (
          <p className="mt-1 text-xs leading-5 text-muted-foreground">
            {description}
          </p>
        ) : null}
      </div>

      <div
        data-slot="resource-treemap-chart-plot"
        className="overflow-hidden rounded-xl"
        style={{ height }}
      >
        {!motionEnabled || hasEnteredView ? (
          <svg
            viewBox={`0 0 ${viewBoxWidth} ${viewBoxHeight}`}
            className="size-full"
            role="img"
            aria-labelledby={`${id}-title`}
          >
            <title id={`${id}-title`}>{String(title)}</title>
            <defs>
              {tiles.map((tile) => (
                <radialGradient
                  key={`grad-${tile.i}`}
                  id={`${id}-grad-${tile.i}`}
                  cx="30%"
                  cy="28%"
                  r="80%"
                >
                  <stop
                    offset="0%"
                    stopColor={`color-mix(in oklab, ${tile.color} 55%, white)`}
                  />
                  <stop offset="55%" stopColor={tile.color} />
                  <stop
                    offset="100%"
                    stopColor={`color-mix(in oklab, ${tile.color} 70%, black)`}
                  />
                </radialGradient>
              ))}
            </defs>

            {tiles.map((tile) => {
              const isActive = activeIndex === tile.i;
              const r = tile.rect;
              const rx = r.x + gap / 2;
              const ry = r.y + gap / 2;
              const rw = Math.max(0, r.w - gap);
              const rh = Math.max(0, r.h - gap);
              const cx = rx + rw / 2;
              const cy = ry + rh / 2;
              const isLargest = tile.i === 0;
              const showLabel = showLabels && rw > 60 && rh > 36;
              const showValue = rw > 60 && rh > 54;

              return (
                <motion.g
                  key={`tile-${tile.i}`}
                  data-slot="resource-treemap-chart-tile"
                  tabIndex={0}
                  role="button"
                  aria-label={`${tile.label}: ${fmt(tile)}, ${tile.percent}%`}
                  {...getItemProps(tile.i)}
                  className="outline-none"
                  style={{ transformOrigin: `${cx}px ${cy}px` }}
                  animate={{
                    scale: isActive ? 1.012 : 1,
                  }}
                  transition={{
                    type: "spring",
                    stiffness: 300,
                    damping: 22,
                  }}
                >
                  <motion.rect
                    x={rx}
                    y={ry}
                    width={rw}
                    height={rh}
                    rx="6"
                    fill={`url(#${id}-grad-${tile.i})`}
                    fillOpacity={isActive ? 1 : 0.88}
                    stroke="var(--background)"
                    strokeWidth="0"
                    initial={
                      motionEnabled
                        ? { scale: 0, opacity: 0 }
                        : { scale: 1, opacity: 0.88 }
                    }
                    animate={{ scale: 1, opacity: isActive ? 1 : 0.88 }}
                    transition={{
                      scale: {
                        delay: motionDelay + tile.i * 0.06,
                        type: "spring",
                        stiffness: 180,
                        damping: 20,
                      },
                      opacity: {
                        delay: motionDelay + tile.i * 0.06,
                        duration: 0.32,
                      },
                    }}
                    style={{ transformOrigin: `${cx}px ${cy}px` }}
                  />

                  {/* Highlight edge on active */}
                  {isActive ? (
                    <rect
                      x={rx}
                      y={ry}
                      width={rw}
                      height={rh}
                      rx="6"
                      fill="none"
                      stroke="white"
                      strokeOpacity="0.25"
                      strokeWidth="1.5"
                      pointerEvents="none"
                    />
                  ) : null}

                  {/* Percentage badge for large tiles */}
                  {isLargest && rw > 100 ? (
                    <motion.text
                      x={rx + 10}
                      y={ry + 18}
                      fill="white"
                      fillOpacity="0.55"
                      className="text-[11px] font-semibold tabular-nums"
                      initial={motionEnabled ? { opacity: 0 } : false}
                      animate={{ opacity: 1 }}
                      transition={{ delay: motionDelay + 0.5, duration: 0.3 }}
                    >
                      {tile.percent}%
                    </motion.text>
                  ) : null}

                  {showLabel ? (
                    <motion.text
                      x={cx}
                      y={showValue ? cy - 8 : cy + 4}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      fill="white"
                      fillOpacity="0.92"
                      className="text-[12px] font-semibold"
                      initial={motionEnabled ? { opacity: 0 } : false}
                      animate={{ opacity: 1 }}
                      transition={{
                        delay: motionDelay + tile.i * 0.06 + 0.32,
                        duration: 0.28,
                      }}
                    >
                      {tile.label}
                    </motion.text>
                  ) : null}

                  {showValue ? (
                    <motion.text
                      x={cx}
                      y={cy + 10}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      fill="white"
                      fillOpacity="0.65"
                      className="text-[11px] font-medium tabular-nums"
                      initial={motionEnabled ? { opacity: 0 } : false}
                      animate={{ opacity: 1 }}
                      transition={{
                        delay: motionDelay + tile.i * 0.06 + 0.4,
                        duration: 0.28,
                      }}
                    >
                      {fmt(tile)}
                    </motion.text>
                  ) : null}
                </motion.g>
              );
            })}

            {/* Tooltip */}
            <AnimatePresence>
              {showTooltip && activePoint ? (
                <motion.g
                  data-slot="resource-treemap-chart-tooltip"
                  pointerEvents="none"
                  initial={
                    motionEnabled
                      ? {
                          opacity: 0,
                          x: tooltipX,
                          y: tooltipY + 6,
                          scale: 0.97,
                        }
                      : false
                  }
                  animate={{ opacity: 1, x: tooltipX, y: tooltipY, scale: 1 }}
                  exit={{
                    opacity: 0,
                    x: tooltipX,
                    y: tooltipY + 4,
                    scale: 0.97,
                  }}
                  transition={{ duration: 0.16, ease: [0.22, 1, 0.36, 1] }}
                >
                  <rect
                    width={tooltipWidth}
                    height={tooltipHeight}
                    rx="10"
                    fill="var(--popover)"
                    stroke="var(--border)"
                  />
                  <circle cx="14" cy="18" r="4.5" fill={activePoint.color} />
                  <text
                    x="26"
                    y="22"
                    fill="var(--popover-foreground)"
                    className="text-[12px] font-semibold"
                  >
                    {activePoint.label}
                  </text>
                  <text
                    x="14"
                    y="40"
                    fill="var(--muted-foreground)"
                    className="text-[10.5px] font-medium"
                  >
                    Size
                  </text>
                  <text
                    x={tooltipWidth - 14}
                    y="40"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[10.5px] font-semibold tabular-nums"
                  >
                    {fmt(activePoint)}
                  </text>
                  <text
                    x="14"
                    y="54"
                    fill="var(--muted-foreground)"
                    className="text-[10.5px] font-medium"
                  >
                    Share
                  </text>
                  <text
                    x={tooltipWidth - 14}
                    y="54"
                    textAnchor="end"
                    fill="var(--popover-foreground)"
                    className="text-[10.5px] font-semibold tabular-nums"
                  >
                    {activePoint.percent}%
                  </text>
                </motion.g>
              ) : null}
            </AnimatePresence>
          </svg>
        ) : null}
      </div>
    </div>
  );
}

