export function InputField({
  id,
  className,
  label,
  description,
  error,
  success,
  state = "default",
  trailing,
  reserveMessageSpace = true,
  required,
  disabled,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: InputFieldProps) {
  const generatedId = useId();
  const shouldReduceMotion = useReducedMotion();
  const inputId = id ?? generatedId;
  const invalid =
    Boolean(error) ||
    state === "error" ||
    ariaInvalid === true ||
    ariaInvalid === "true";
  const resolvedState = invalid ? "error" : state;
  const messageId =
    description || error || success ? `${inputId}-message` : undefined;
  const describedBy = [ariaDescribedBy, messageId].filter(Boolean).join(" ");
  const showStatusIcon =
    trailing ?? (resolvedState === "loading" || resolvedState === "success");

  return (
    <Field data-slot="input-field" invalid={invalid} disabled={disabled}>
      {label ? (
        <FieldLabel htmlFor={inputId} required={required}>
          {label}
        </FieldLabel>
      ) : null}
      <div className="relative">
        <Input
          id={inputId}
          className={cn(showStatusIcon && "pr-9", className)}
          state={resolvedState}
          required={required}
          disabled={disabled}
          aria-describedby={describedBy || undefined}
          aria-invalid={invalid || undefined}
          {...props}
        />
        <AnimatePresence initial={false}>
          {showStatusIcon ? (
            <motion.span
              key={resolvedState}
              data-slot="input-status"
              aria-hidden="true"
              initial={
                shouldReduceMotion
                  ? { opacity: 0 }
                  : { opacity: 0, scale: 0.92 }
              }
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.92 }}
              transition={
                shouldReduceMotion ? { duration: duration.fast } : spring.fast
              }
              className="pointer-events-none absolute inset-y-0 right-3 flex items-center text-muted-foreground"
            >
              {trailing ??
                (resolvedState === "loading" ? (
                  <LoaderCircle className="size-4 animate-spin" />
                ) : (
                  <Check className="size-4 text-foreground" />
                ))}
            </motion.span>
          ) : null}
        </AnimatePresence>
      </div>
      <FieldMessage
        id={messageId}
        description={description}
        error={error}
        success={success}
        reserveSpace={reserveMessageSpace}
      />
    </Field>
  );
}

