export type PasswordInputProps = Omit<
  ComponentProps<"input">,
  "type" | "size"
> &
  VariantProps<typeof passwordInputVariants> & {
    label?: ReactNode;
    description?: ReactNode;
    error?: ReactNode;
    criteria?: readonly PasswordCriterion[];
    showCriteria?: boolean;
    inputClassName?: string;
    strengthLabel?: (completed: number, total: number) => ReactNode;
    reserveMessageSpace?: boolean;
  };

export function PasswordInput({
  id,
  className,
  inputClassName,
  size = "md",
  label,
  description,
  error,
  criteria = defaultPasswordCriteria,
  showCriteria = true,
  strengthLabel,
  reserveMessageSpace = false,
  required,
  disabled,
  value,
  defaultValue,
  onChange,
  onFocus,
  onBlur,
  autoComplete = "new-password",
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: PasswordInputProps) {
  const generatedId = useId();
  const shouldReduceMotion = useReducedMotion();
  const [visible, setVisible] = useState(false);
  const [isMeterOpen, setIsMeterOpen] = useState(false);
  const [internalValue, setInternalValue] = useState(() =>
    typeof defaultValue === "string" ? defaultValue : "",
  );
  const inputId = id ?? generatedId;
  const password = typeof value === "string" ? value : internalValue;
  const invalid =
    Boolean(error) || ariaInvalid === true || ariaInvalid === "true";
  const results = criteria.map((criterion) => ({
    ...criterion,
    met: criterion.test(password),
  }));
  const completed = results.filter((criterion) => criterion.met).length;
  const isComplete = password.length > 0 && completed === criteria.length;
  const meterWidth =
    password.length > 0
      ? Math.max((completed / Math.max(criteria.length, 1)) * 100, 10)
      : 0;
  const messageId = description || error ? `${inputId}-message` : undefined;
  const criteriaId =
    showCriteria && isMeterOpen ? `${inputId}-criteria` : undefined;
  const describedBy = [ariaDescribedBy, messageId, criteriaId]
    .filter(Boolean)
    .join(" ");
  const styles = passwordInputVariants({ size });

  function handleChange(event: ChangeEvent<HTMLInputElement>) {
    setInternalValue(event.target.value);
    onChange?.(event);
  }

  function handleFocus(event: FocusEvent<HTMLInputElement>) {
    setIsMeterOpen(true);
    onFocus?.(event);
  }

  function handleBlur(event: FocusEvent<HTMLInputElement>) {
    setIsMeterOpen(false);
    onBlur?.(event);
  }

  return (
    <Field
      data-slot="password-input"
      className={twMerge(styles.root(), className)}
      invalid={invalid}
      disabled={disabled}
    >
      {label ? (
        <FieldLabel htmlFor={inputId} required={required}>
          {label}
        </FieldLabel>
      ) : null}
      <div data-slot="password-input-control" className={styles.control()}>
        <Input
          id={inputId}
          type={visible ? "text" : "password"}
          inputSize={size}
          className={twMerge("pr-10", inputClassName)}
          state={invalid ? "error" : isComplete ? "success" : "default"}
          value={value}
          defaultValue={defaultValue}
          autoComplete={autoComplete}
          required={required}
          disabled={disabled}
          aria-describedby={describedBy || undefined}
          aria-invalid={invalid || undefined}
          onChange={handleChange}
          onFocus={handleFocus}
          onBlur={handleBlur}
          {...props}
        />
        <button
          type="button"
          data-slot="password-input-toggle"
          className={styles.toggle()}
          aria-label={visible ? "Hide password" : "Show password"}
          aria-pressed={visible}
          disabled={disabled}
          onPointerDown={(event) => event.preventDefault()}
          onClick={() => setVisible((current) => !current)}
        >
          <AnimatePresence initial={false} mode="wait">
            <motion.span
              key={visible ? "visible" : "hidden"}
              initial={
                shouldReduceMotion
                  ? { opacity: 0 }
                  : { opacity: 0, scale: 0.94 }
              }
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.94 }}
              transition={
                shouldReduceMotion ? { duration: duration.fast } : spring.fast
              }
            >
              {visible ? (
                <EyeOff className="size-4" aria-hidden="true" />
              ) : (
                <Eye className="size-4" aria-hidden="true" />
              )}
            </motion.span>
          </AnimatePresence>
        </button>
        <AnimatePresence initial={false}>
          {showCriteria && isMeterOpen ? (
            <MotionElevated
              offset={2}
              id={criteriaId}
              data-slot="password-input-meter"
              className={styles.meter()}
              initial={
                shouldReduceMotion
                  ? { opacity: 0 }
                  : { opacity: 0, y: -6, scale: 0.985 }
              }
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={
                shouldReduceMotion
                  ? { opacity: 0 }
                  : {
                      opacity: 0,
                      y: -4,
                      scale: 0.99,
                      transition: meterMotion.exit,
                    }
              }
              transition={shouldReduceMotion ? { duration: 0 } : meterMotion}
            >
              <div className={styles.meterHeader()}>
                <span>Password strength</span>
                <span>
                  {strengthLabel?.(completed, criteria.length) ??
                    `${completed}/${criteria.length} met`}
                </span>
              </div>
              <div className={styles.meterTrack()} aria-hidden="true">
                <motion.div
                  className={styles.meterBar()}
                  initial={false}
                  animate={{
                    width: `${meterWidth}%`,
                    opacity: password ? 1 : 0,
                  }}
                  transition={
                    shouldReduceMotion ? { duration: 0 } : spring.moderate
                  }
                />
              </div>
              <ul className={styles.criteria()}>
                {results.map((criterion) => (
                  <li
                    key={criterion.id}
                    data-met={criterion.met}
                    className={styles.criterion()}
                  >
                    <span className={styles.criterionIcon()} aria-hidden="true">
                      <AnimatePresence initial={false} mode="wait">
                        <motion.span
                          key={criterion.met ? "valid" : "pending"}
                          className="flex"
                          initial={
                            shouldReduceMotion
                              ? { opacity: 0 }
                              : { opacity: 0, scale: 0.88 }
                          }
                          animate={{ opacity: 1, scale: 1 }}
                          exit={{ opacity: 0, scale: 0.88 }}
                          transition={
                            shouldReduceMotion
                              ? { duration: duration.fast }
                              : spring.fast
                          }
                        >
                          {criterion.met ? (
                            <IconCircleCheck className="text-primary drop-shadow-sm" />
                          ) : (
                            <Circle className="size-2 fill-muted text-muted" />
                          )}
                        </motion.span>
                      </AnimatePresence>
                    </span>
                    {criterion.label}
                  </li>
                ))}
              </ul>
            </MotionElevated>
          ) : null}
        </AnimatePresence>
      </div>
      {description || error || reserveMessageSpace ? (
        <FieldMessage
          id={messageId}
          description={description}
          error={error}
          reserveSpace={reserveMessageSpace}
        />
      ) : null}
    </Field>
  );
}

