function getMotionStyle(style?: CSSProperties): CSSProperties {
  return {
    "--motion-duration": `${selectMotion.visualDuration}s`,
    "--motion-exit-duration": `${selectMotion.exit.duration}s`,
    ...style,
  } as CSSProperties;
